type RouteHealth string

const (
	HealthHealthy    RouteHealth = "HEALTHY"
	HealthDegraded   RouteHealth = "DEGRADED"
	HealthFailing    RouteHealth = "FAILING"
	HealthFailed     RouteHealth = "FAILED"
	HealthRecovering RouteHealth = "RECOVERING"
)

type RouteTier string

const (
	TierActive    RouteTier = "ACTIVE"
	TierStandby   RouteTier = "STANDBY"
	TierCandidate RouteTier = "CANDIDATE"
	TierFailed    RouteTier = "FAILED"
)

type StabilityGrade string

const (
	GradeStable      StabilityGrade = "STABLE"
	GradeFluctuating StabilityGrade = "FLUCTUATING"
	GradeDegraded    StabilityGrade = "DEGRADED"
	GradeUnstable    StabilityGrade = "UNSTABLE"
	GradeFailed      StabilityGrade = "FAILED"
)

type RouteRecommendation string

const (
	RecBest     RouteRecommendation = "BEST"
	RecGood     RouteRecommendation = "GOOD"
	RecUsable   RouteRecommendation = "USABLE"
	RecDegraded RouteRecommendation = "DEGRADED"
	RecAvoid    RouteRecommendation = "AVOID"
	RecFailed   RouteRecommendation = "FAILED"
)

// RouteMetrics is the unified data contract representing a route's measured quality.
type RouteMetrics struct {
	ID                    string              `json:"id"`
	IP                    string              `json:"ip"`
	Port                  int                 `json:"port"`
	Colo                  string              `json:"colo"`
	Tier                  RouteTier           `json:"tier"`
	Health                RouteHealth         `json:"health"`
	StabilityGrade        StabilityGrade      `json:"stability_grade"`
	Recommendation        RouteRecommendation `json:"recommendation"`
	RecommendationReasons []string            `json:"recommendation_reasons"`
	RTT                   float64             `json:"rtt"`            // ms (TCPLatency)
	PacketLoss            float64             `json:"packet_loss"`    // 0.0 - 1.0 (0% - 100%)
	Jitter                float64             `json:"jitter"`         // ms
	DownloadSpeed         float64             `json:"download_speed"` // MB/s
	SingleSpeed           float64             `json:"single_speed"`   // MB/s
	P10Speed              float64             `json:"p10_speed"`      // MB/s
	P25Speed              float64             `json:"p25_speed"`      // MB/s
	MedianSpeed           float64             `json:"median_speed"`   // MB/s
	MinSpeed              float64             `json:"min_speed"`      // MB/s (true minimum, includes 0)
	MaxSpeed              float64             `json:"max_speed"`      // MB/s
	StdDev                float64             `json:"std_dev"`
	CV                    float64             `json:"cv"`
	Stability             float64             `json:"stability"`    // 0.0 - 100.0 (Composite stability)
	LoadLatency           float64             `json:"load_latency"` // ms
	HandshakeSuccess      bool                `json:"handshake_success"`
	GOWAYWSSCompatible    bool                `json:"goway_wss_compatible"`
	GOWAYWSSLatency       float64             `json:"goway_wss_latency"`
	WSSJitter             float64             `json:"wss_jitter,omitempty"`
	WSSSuccessRate        float64             `json:"wss_success_rate,omitempty"`
	GOWAYWSSErrorStage    string              `json:"goway_wss_error_stage,omitempty"`
	GOWAYWSSHTTPStatus    int                 `json:"goway_wss_http_status,omitempty"`
	GOWAYWSSErrorMessage  string              `json:"goway_wss_error_message,omitempty"`
	GOWAYWSSSNISent       string              `json:"goway_wss_sni_sent,omitempty"`
	GOWAYWSSHostSent      string              `json:"goway_wss_host_sent,omitempty"`
	GOWAYWSSPathSent      string              `json:"goway_wss_path_sent,omitempty"`
	ZeroSpeedIntervals    int                 `json:"zero_speed_intervals"`
	StallCount            int                 `json:"stall_count"`
	TotalStallDuration    float64             `json:"total_stall_duration"`
	LongestStallDuration  float64             `json:"longest_stall_duration"`
	StallRate             float64             `json:"stall_rate"`
	DurationSeconds       float64             `json:"duration_seconds,omitempty"`
	BaselineP10           float64             `json:"baseline_p10"`
	SpeedDropPercent      float64             `json:"speed_drop_percent"`
	Confidence            float64             `json:"confidence"` // 0.0 - 100.0
	PeakHourScore         float64             `json:"peak_hour_score"`
	InstantScore          float64             `json:"instant_score"`
	ShortTermScore        float64             `json:"short_term_score"`
	LongTermScore         float64             `json:"long_term_score"`
	FinalScore            float64             `json:"final_score"`
	EWMA                  *EWMASnapshot       `json:"ewma,omitempty"`
	ConsecutiveFails      int                 `json:"consecutive_failures"`
	ConsecutiveSuccess    int                 `json:"consecutive_successes"`
	ConsecutiveDegraded   int                 `json:"consecutive_degraded"`
	IsStale               bool                `json:"is_stale"`
	ObservationDuration   float64             `json:"observation_duration_sec"` // Total seconds between first and last sample
	LastSuccess           time.Time           `json:"last_success,omitempty"`
	LastTested            time.Time           `json:"last_tested"`
	Timestamp             time.Time           `json:"timestamp"`
}

// GenerateRouteID creates a canonical route ID from IP and Port.
func GenerateRouteID(ip string, port int) string {
	sanitized := strings.ReplaceAll(ip, ".", "-")
	sanitized = strings.ReplaceAll(sanitized, ":", "-")
	return fmt.Sprintf("route-%s-%d", sanitized, port)
}

// UpdateHealth transitions the route health state machine based on recent probe results with de-bouncing.
func (m *RouteMetrics) UpdateHealth(success bool, baselineP10 float64) {
	const (
		failureThreshold  = 3
		recoveryThreshold = 3
		degradedThreshold = 3
	)

	m.BaselineP10 = baselineP10
	if !success || !m.HandshakeSuccess || m.RTT <= 0 {
		m.ConsecutiveFails++
		m.ConsecutiveSuccess = 0
		m.ConsecutiveDegraded = 0

		if m.ConsecutiveFails >= failureThreshold {
			m.Health = HealthFailed
			m.Tier = TierFailed
			m.StabilityGrade = GradeFailed
			m.Recommendation = RecFailed
		} else {
			m.Health = HealthFailing
		}
		return
	}

	// Probe succeeded
	m.ConsecutiveSuccess++
	m.ConsecutiveFails = 0

	// Check degradation triggers:
	// 1. Packet loss > 15%
	// 2. Jitter > 25ms
	// 3. P10 speed drop > 30% compared to baseline P10 (if baseline is established)
	// 4. Stalls observed in current probe
	isDegradedCondition := false
	if m.PacketLoss > 0.15 {
		isDegradedCondition = true
	}
	if m.Jitter > 25.0 {
		isDegradedCondition = true
	}
	if m.StallCount > 0 || m.ZeroSpeedIntervals > 0 {
		isDegradedCondition = true
	}

	effectiveP10 := m.P10Speed
	if effectiveP10 <= 0 && m.MinSpeed > 0 {
		effectiveP10 = m.MinSpeed
	}
	if effectiveP10 <= 0 && m.SingleSpeed > 0 {
		effectiveP10 = m.SingleSpeed
	}
	if baselineP10 > 2.0 && effectiveP10 >= 0 {
		drop := (1.0 - (effectiveP10 / baselineP10)) * 100.0
		if drop > 0 {
			m.SpeedDropPercent = math.Round(drop*10) / 10
		} else {
			m.SpeedDropPercent = 0
		}
		if m.SpeedDropPercent >= 30.0 {
			isDegradedCondition = true
		}
	} else {
		m.SpeedDropPercent = 0
	}

	if isDegradedCondition {
		m.ConsecutiveDegraded++
	} else {
		if m.ConsecutiveDegraded > 0 {
			m.ConsecutiveDegraded--
		}
	}

	switch m.Health {
	case HealthFailed, HealthFailing:
		m.Health = HealthRecovering
	case HealthRecovering:
		if m.ConsecutiveSuccess >= recoveryThreshold && m.ConsecutiveDegraded == 0 {
			m.Health = HealthHealthy
		}
	default:
		if m.ConsecutiveDegraded >= degradedThreshold {
			m.Health = HealthDegraded
		} else if m.ConsecutiveDegraded == 0 {
			m.Health = HealthHealthy
		}
	}
}

// DetermineStabilityGrade classifies route stability.
func (m *RouteMetrics) DetermineStabilityGrade() StabilityGrade {
	if m.Health == HealthFailed {
		return GradeFailed
	}
	if m.Health == HealthFailing {
		return GradeUnstable
	}
	if m.StallCount > 0 || m.PacketLoss >= 0.10 || m.Jitter >= 30.0 {
		return GradeUnstable
	}
	if m.Health == HealthDegraded || m.SpeedDropPercent >= 30.0 {
		return GradeDegraded
	}
	if m.CV >= 0.35 || (m.MedianSpeed > 0 && m.P10Speed < m.MedianSpeed*0.50) {
		return GradeFluctuating
	}
	return GradeStable
}

// GenerateRecommendation assigns a recommendation tier and explanatory reasons.
func (m *RouteMetrics) GenerateRecommendation() (RouteRecommendation, []string) {
	var reasons []string

	if m.Health == HealthFailed {
		reasons = append(reasons, fmt.Sprintf("FAILED: Route failed %d consecutive probes", m.ConsecutiveFails))
		return RecFailed, reasons
	}

	if m.Health == HealthFailing {
		reasons = append(reasons, fmt.Sprintf("FAILING: Route recently failed probe (fails: %d)", m.ConsecutiveFails))
		return RecAvoid, reasons
	}

	if m.StallRate > 0.10 || m.LongestStallDuration >= 2.0 {
		reasons = append(reasons, fmt.Sprintf("AVOID: Severe stall detected (stall rate: %.1f%%, longest: %.1fs)", m.StallRate*100, m.LongestStallDuration))
		return RecAvoid, reasons
	}

	if m.PacketLoss >= 0.15 {
		reasons = append(reasons, fmt.Sprintf("AVOID: High packet loss (%.1f%%)", m.PacketLoss*100))
		return RecAvoid, reasons
	}

	if m.Health == HealthDegraded {
		if m.SpeedDropPercent >= 30.0 {
			reasons = append(reasons, fmt.Sprintf("DEGRADED: Speed dropped by %.1f%% against baseline", m.SpeedDropPercent))
		}
		if m.Jitter > 25.0 {
			reasons = append(reasons, fmt.Sprintf("DEGRADED: High jitter (%.1fms)", m.Jitter))
		}
		return RecDegraded, reasons
	}

	if m.Health == HealthRecovering {
		reasons = append(reasons, fmt.Sprintf("USABLE: Route is recovering (%d/%d probe successes)", m.ConsecutiveSuccess, 3))
		return RecUsable, reasons
	}

	// For Healthy routes, evaluate score and metrics
	effectiveSpeed := m.SingleSpeed
	if effectiveSpeed <= 0 {
		effectiveSpeed = m.DownloadSpeed
	}

	if m.FinalScore >= 85.0 && m.Stability >= 80.0 && m.PacketLoss == 0 && m.Jitter <= 15.0 && m.StallCount == 0 {
		reasons = append(reasons,
			fmt.Sprintf("BEST: P10 speed %.1f MB/s, 0%% loss, jitter %.1fms, peak score %.1f, confidence %.0f%%",
				m.P10Speed, m.Jitter, m.PeakHourScore, m.Confidence),
		)
		return RecBest, reasons
	}

	if m.FinalScore >= 70.0 && m.Stability >= 65.0 && m.PacketLoss <= 0.05 && m.StallCount == 0 {
		reasons = append(reasons,
			fmt.Sprintf("GOOD: P10 speed %.1f MB/s, stability %.1f%%, loss %.1f%%",
				m.P10Speed, m.Stability, m.PacketLoss*100),
		)
		return RecGood, reasons
	}

	reasons = append(reasons,
		fmt.Sprintf("USABLE: Score %.1f, speed %.1f MB/s, stability %.1f%%",
			m.FinalScore, effectiveSpeed, m.Stability),
	)
	return RecUsable, reasons
}

// ToNodeResult converts RouteMetrics to legacy NodeResult for backward compatibility with CLI/CSV.
func (m *RouteMetrics) ToNodeResult() NodeResult {
	return NodeResult{
		IP:                   m.IP,
		Port:                 m.Port,
		TCPLatency:           m.RTT,
		DownloadSpeed:        m.DownloadSpeed,
		SingleSpeed:          m.SingleSpeed,
		LoadLatency:          m.LoadLatency,
		Colo:                 m.Colo,
		Score:                m.FinalScore,
		Jitter:               m.Jitter,
		Stability:            m.Stability,
		MinSpeed:             m.MinSpeed,
		P10Speed:             m.P10Speed,
		MedianSpeed:          m.MedianSpeed,
		StallCount:           m.StallCount,
		TotalStallDuration:   m.TotalStallDuration,
		ZeroSpeedIntervals:   m.ZeroSpeedIntervals,
		PacketLoss:           m.PacketLoss,
		Recommendation:       string(m.Recommendation),
		GOWAYWSSCompatible:   m.GOWAYWSSCompatible,
		GOWAYWSSLatency:      m.GOWAYWSSLatency,
		WSSJitter:            m.WSSJitter,
		WSSSuccessRate:       m.WSSSuccessRate,
		GOWAYWSSErrorStage:   m.GOWAYWSSErrorStage,
		GOWAYWSSHTTPStatus:   m.GOWAYWSSHTTPStatus,
		GOWAYWSSErrorMessage: m.GOWAYWSSErrorMessage,
		GOWAYWSSSNISent:      m.GOWAYWSSSNISent,
		GOWAYWSSHostSent:     m.GOWAYWSSHostSent,
		GOWAYWSSPathSent:     m.GOWAYWSSPathSent,
	}
}

// FromNodeResult populates a RouteMetrics struct from a NodeResult.
func FromNodeResult(n NodeResult, tier RouteTier) *RouteMetrics {
	now := time.Now()
	p10 := n.P10Speed
	if p10 <= 0 && n.SingleSpeed > 0 {
		p10 = n.MinSpeed
	}
	median := n.MedianSpeed
	if median <= 0 && n.SingleSpeed > 0 {
		median = n.SingleSpeed
	}

	is403 := strings.TrimSpace(n.Colo) == "403" || n.GOWAYWSSHTTPStatus == 403
	health := HealthHealthy
	consecSuccess := 1
	consecFails := 0
	if is403 {
		health = HealthFailed
		consecSuccess = 0
		consecFails = 1
	}

	rm := &RouteMetrics{
		ID:                   GenerateRouteID(n.IP, n.Port),
		IP:                   n.IP,
		Port:                 n.Port,
		Colo:                 n.Colo,
		Tier:                 tier,
		Health:               health,
		StabilityGrade:       GradeStable,
		Recommendation:       RecGood,
		RTT:                  n.TCPLatency,
		PacketLoss:           n.PacketLoss,
		Jitter:               n.Jitter,
		DownloadSpeed:        n.DownloadSpeed,
		SingleSpeed:          n.SingleSpeed,
		P10Speed:             p10,
		MedianSpeed:          median,
		MinSpeed:             n.MinSpeed,
		Stability:            n.Stability,
		LoadLatency:          n.LoadLatency,
		HandshakeSuccess:     !is403 && (n.GOWAYWSSCompatible || (n.Colo != "ERR" && n.Colo != "429" && n.TCPLatency > 0)),
		GOWAYWSSCompatible:   !is403 && n.GOWAYWSSCompatible,
		GOWAYWSSLatency:      n.GOWAYWSSLatency,
		WSSJitter:            n.WSSJitter,
		WSSSuccessRate:       n.WSSSuccessRate,
		GOWAYWSSErrorStage:   n.GOWAYWSSErrorStage,
		GOWAYWSSHTTPStatus:   n.GOWAYWSSHTTPStatus,
		GOWAYWSSErrorMessage: n.GOWAYWSSErrorMessage,
		GOWAYWSSSNISent:      n.GOWAYWSSSNISent,
		GOWAYWSSHostSent:     n.GOWAYWSSHostSent,
		GOWAYWSSPathSent:     n.GOWAYWSSPathSent,
		StallCount:           n.StallCount,
		ZeroSpeedIntervals:   n.ZeroSpeedIntervals,
		Confidence:           50.0,
		InstantScore:         n.Score,
		ShortTermScore:       n.Score,
		LongTermScore:        n.Score,
		FinalScore:           n.Score,
		ConsecutiveSuccess:   consecSuccess,
		ConsecutiveFails:     consecFails,
		LastTested:           now,
		Timestamp:            now,
	}
	rm.StabilityGrade = rm.DetermineStabilityGrade()
	rec, reasons := rm.GenerateRecommendation()
	rm.Recommendation = rec
	rm.RecommendationReasons = reasons
	return rm
}

// ============================================================================
// SECTION: SCORING ENGINE & STABILITY (from score.go)
// ============================================================================
// ScoreMode identifies the current scoring preference mode.
type ScoreMode string

const (
	ModeNormal ScoreMode = "normal"
	ModePeak   ScoreMode = "peak"
)

// ComponentWeights configures the percentage contribution of each metric to the score.
type ComponentWeights struct {
	SpeedWeight      float64 `json:"speed_weight"`       // SingleStream/Download speed (0.20)
	P10SpeedWeight   float64 `json:"p10_speed_weight"`   // P10 speed anti-buffering floor (0.20)
	MinSpeedWeight   float64 `json:"min_speed_weight"`   // Floor speed (0.10)
	StabilityWeight  float64 `json:"stability_weight"`   // Speed stability (0.20)
	PacketLossWeight float64 `json:"packet_loss_weight"` // Packet loss (0.10)
	JitterWeight     float64 `json:"jitter_weight"`      // Latency jitter (0.10)
	LatencyWeight    float64 `json:"latency_weight"`     // TCP Latency / RTT (0.05)
	HandshakeWeight  float64 `json:"handshake_weight"`   // WSS Handshake success (0.05)
	ColoBonus        float64 `json:"colo_bonus"`         // Extra bonus for valid CDN Colo
}

// HorizonWeights configures weights across instant, short-term, long-term, peak hour, and confidence.
type HorizonWeights struct {
	InstantWeight    float64 `json:"instant_weight"`
	ShortTermWeight  float64 `json:"short_term_weight"`
	LongTermWeight   float64 `json:"long_term_weight"`
	PeakHourWeight   float64 `json:"peak_hour_weight"`
	ConfidenceWeight float64 `json:"confidence_weight"`
}

// DefaultNormalWeights returns default weights optimized for normal non-congested hours.
func DefaultNormalWeights() ComponentWeights {
	return ComponentWeights{
		SpeedWeight:      0.20,
		P10SpeedWeight:   0.20,
		MinSpeedWeight:   0.10,
		StabilityWeight:  0.20,
		PacketLossWeight: 0.10,
		JitterWeight:     0.10,
		LatencyWeight:    0.05,
		HandshakeWeight:  0.05,
		ColoBonus:        3.0,
	}
}

// DefaultPeakWeights returns default weights optimized for peak congested hours (focus on P10 & stability).
func DefaultPeakWeights() ComponentWeights {
	return ComponentWeights{
		SpeedWeight:      0.15,
		P10SpeedWeight:   0.25,
		MinSpeedWeight:   0.10,
		StabilityWeight:  0.25,
		PacketLossWeight: 0.10,
		JitterWeight:     0.10,
		LatencyWeight:    0.025,
		HandshakeWeight:  0.025,
		ColoBonus:        2.0,
	}
}

// DefaultNormalHorizons returns horizons for normal hours.
func DefaultNormalHorizons() HorizonWeights {
	return HorizonWeights{
		InstantWeight:    0.20,
		ShortTermWeight:  0.30,
		LongTermWeight:   0.25,
		PeakHourWeight:   0.15,
		ConfidenceWeight: 0.10,
	}
}

// DefaultPeakHorizons returns horizons for peak congested hours.
func DefaultPeakHorizons() HorizonWeights {
	return HorizonWeights{
		InstantWeight:    0.10,
		ShortTermWeight:  0.25,
		LongTermWeight:   0.25,
		PeakHourWeight:   0.25,
		ConfidenceWeight: 0.15,
	}
}

// ScoreEngine calculates instant, short-term, long-term, and final route scores.
type ScoreEngine struct {
	mu            sync.RWMutex
	Mode          ScoreMode        `json:"mode"`
	NormalWeights ComponentWeights `json:"normal_weights"`
	PeakWeights   ComponentWeights `json:"peak_weights"`
	NormalHorizon HorizonWeights   `json:"normal_horizons"`
	PeakHorizon   HorizonWeights   `json:"peak_horizons"`
}

var GlobalScoreEngine = NewScoreEngine(ModeNormal)

func NewScoreEngine(mode ScoreMode) *ScoreEngine {
	if mode == "" {
		mode = ModeNormal
	}
	return &ScoreEngine{
		Mode:          mode,
		NormalWeights: DefaultNormalWeights(),
		PeakWeights:   DefaultPeakWeights(),
		NormalHorizon: DefaultNormalHorizons(),
		PeakHorizon:   DefaultPeakHorizons(),
	}
}

func (e *ScoreEngine) SetMode(mode ScoreMode) {
	e.mu.Lock()
	defer e.mu.Unlock()
	e.Mode = mode
}

func (e *ScoreEngine) GetMode() ScoreMode {
	e.mu.RLock()
	defer e.mu.RUnlock()
	return e.Mode
}

func (e *ScoreEngine) ActiveWeights() ComponentWeights {
	e.mu.RLock()
	defer e.mu.RUnlock()
	if e.Mode == ModePeak {
		return e.PeakWeights
	}
	return e.NormalWeights
}

func (e *ScoreEngine) ActiveHorizons() HorizonWeights {
	e.mu.RLock()
	defer e.mu.RUnlock()
	if e.Mode == ModePeak {
		return e.PeakHorizon
	}
	return e.NormalHorizon
}

// calcMetricScore calculates a 0-100 composite score from raw metric values.
func (e *ScoreEngine) calcMetricScore(w ComponentWeights, speed, p10Speed, minSpeed, latency, jitter, loss, stability float64, handshake bool, colo string) float64 {
	// 1. Average/Single speed score: 15 MB/s 达到 85 分，15~50 MB/s 线性递增至 95 分，50~100 MB/s 递增至 100 分（拉开超高速与千兆节点差距）
	var scoreSpeed float64
	if speed <= 0 {
		scoreSpeed = 0
	} else if speed <= 15.0 {
		scoreSpeed = (speed / 15.0) * 85.0
	} else if speed <= 50.0 {
		scoreSpeed = 85.0 + ((speed-15.0)/35.0)*10.0
	} else {
		scoreSpeed = 95.0 + math.Min((speed-50.0)/50.0*5.0, 5.0)
	}

	// 2. P10Speed score: 12 MB/s 达到 85 分，12~35 MB/s 递增至 95 分，35~80 MB/s 递增至 100 分（强力保障看视频与高速隧道不缓冲）
	var scoreP10 float64
	if p10Speed <= 0 {
		scoreP10 = 0
	} else if p10Speed <= 12.0 {
		scoreP10 = (p10Speed / 12.0) * 85.0
	} else if p10Speed <= 35.0 {
		scoreP10 = 85.0 + ((p10Speed-12.0)/23.0)*10.0
	} else {
		scoreP10 = 95.0 + math.Min((p10Speed-35.0)/45.0*5.0, 5.0)
	}

	// 3. MinSpeed score: cap 10 MB/s (true minimum, 0 if stalled)
	scoreMinSpeed := math.Min(minSpeed/10.0*100.0, 100.0)
	if scoreMinSpeed < 0 {
		scoreMinSpeed = 0
	}

	// 4. Latency score: base 25ms, 兼顾网页代理转发首包响应 (TTFB/RTT)
	scoreLatency := 100.0 - (latency-25.0)*0.55
	if scoreLatency < 0 {
		scoreLatency = 0
	} else if scoreLatency > 100.0 {
		scoreLatency = 100.0
	}

	// 5. Jitter score: >10ms starts steep penalty
	scoreJitter := 100.0 - jitter*2.5
	if scoreJitter < 0 {
		scoreJitter = 0
	} else if scoreJitter > 100.0 {
		scoreJitter = 100.0
	}

	// 6. Packet loss score: 0% loss = 100, 10% loss = 50, >=20% loss = 0
	scoreLoss := 100.0 - loss*500.0
	if scoreLoss < 0 {
		scoreLoss = 0
	} else if scoreLoss > 100.0 {
		scoreLoss = 100.0
	}

	// 7. Stability score (0 - 100)
	scoreStability := stability
	if scoreStability < 0 {
		scoreStability = 0
	} else if scoreStability > 100.0 {
		scoreStability = 100.0
	}

	// 8. Handshake score
	scoreHandshake := 0.0
	if handshake {
		scoreHandshake = 100.0
	}

	total := scoreSpeed*w.SpeedWeight +
		scoreP10*w.P10SpeedWeight +
		scoreMinSpeed*w.MinSpeedWeight +
		scoreStability*w.StabilityWeight +
		scoreLoss*w.PacketLossWeight +
		scoreJitter*w.JitterWeight +
		scoreLatency*w.LatencyWeight +
		scoreHandshake*w.HandshakeWeight

	if colo != "" && colo != "UNK" && colo != "ERR" && colo != "429" && colo != "403" {
		total += w.ColoBonus
	}

	if total < 0 {
		total = 0
	} else if total > 100.0 {
		total = 100.0
	}
	return math.Round(total*10) / 10
}

// EvaluateRoute computes InstantScore, ShortTermScore, LongTermScore, and FinalScore for a route.
func (e *ScoreEngine) EvaluateRoute(m *RouteMetrics, shortEWMA, longEWMA EWMASnapshot, peakHourPenalty float64) {
	w := e.ActiveWeights()
	hw := e.ActiveHorizons()

	effectiveSpeed := m.SingleSpeed
	if effectiveSpeed <= 0 {
		effectiveSpeed = m.DownloadSpeed
	}
	effectiveP10 := m.P10Speed
	if effectiveP10 <= 0 && effectiveSpeed > 0 {
		if m.MinSpeed > 0 {
			effectiveP10 = m.MinSpeed
		} else {
			effectiveP10 = effectiveSpeed
		}
	}
	effectiveMin := m.MinSpeed
	if effectiveMin <= 0 && effectiveSpeed > 0 {
		effectiveMin = effectiveP10
	}
	effectiveStability := m.Stability
	if effectiveStability <= 0 && effectiveSpeed > 0 {
		latCons := 100.0
		if m.RTT > 0 {
			latCons = math.Max(0, math.Min(100, 100.0-(m.Jitter/(m.RTT+1.0))*100.0))
		}
		lossCons := math.Max(0, math.Min(100, (1.0-m.PacketLoss)*100.0))
		effectiveStability = 80.0*0.50 + latCons*0.25 + lossCons*0.25
	}

	// 1. InstantScore from current measurement
	m.InstantScore = e.calcMetricScore(w, effectiveSpeed, effectiveP10, effectiveMin, m.RTT, m.Jitter, m.PacketLoss, effectiveStability, m.HandshakeSuccess, m.Colo)

	// 2. ShortTermScore from short-term EWMA (~5-15 min window)
	shortSpeed := shortEWMA.Speed
	if shortSpeed <= 0 {
		shortSpeed = effectiveSpeed
	}
	shortP10 := shortEWMA.P10Speed
	if shortP10 <= 0 {
		shortP10 = effectiveP10
	}
	shortMinSpeed := shortEWMA.MinSpeed
	if shortMinSpeed <= 0 {
		shortMinSpeed = effectiveMin
	}
	shortStability := shortEWMA.Stability
	if shortStability <= 0 {
		shortStability = effectiveStability
	}
	m.ShortTermScore = e.calcMetricScore(w, shortSpeed, shortP10, shortMinSpeed, shortEWMA.Latency, shortEWMA.Jitter, shortEWMA.Loss, shortStability, m.HandshakeSuccess, m.Colo)

	// 3. LongTermScore from long-term EWMA (~several hours)
	longSpeed := longEWMA.Speed
	if longSpeed <= 0 {
		longSpeed = shortSpeed
	}
	longP10 := longEWMA.P10Speed
	if longP10 <= 0 {
		longP10 = shortP10
	}
	longMinSpeed := longEWMA.MinSpeed
	if longMinSpeed <= 0 {
		longMinSpeed = shortMinSpeed
	}
	longStability := longEWMA.Stability
	if longStability <= 0 {
		longStability = shortStability
	}
	rawLongScore := e.calcMetricScore(w, longSpeed, longP10, longMinSpeed, longEWMA.Latency, longEWMA.Jitter, longEWMA.Loss, longStability, m.HandshakeSuccess, m.Colo)
	m.LongTermScore = math.Max(0, rawLongScore-peakHourPenalty)

	// 4. PeakHourScore
	peakScore := m.PeakHourScore
	if peakScore <= 0 {
		peakScore = m.LongTermScore
	}

	// 5. Confidence
	conf := m.Confidence
	if conf <= 0 {
		conf = 50.0
	}

	// 6. FinalScore = Instant + ShortTerm + LongTerm + PeakHour + Confidence - WSS instability penalty
	final := m.InstantScore*hw.InstantWeight +
		m.ShortTermScore*hw.ShortTermWeight +
		m.LongTermScore*hw.LongTermWeight +
		peakScore*hw.PeakHourWeight +
		conf*hw.ConfidenceWeight
	final -= calcWSSSuccessPenalty(m.GOWAYWSSCompatible, m.WSSSuccessRate)

	if final < 0 {
		final = 0
	} else if final > 100.0 {
		final = 100.0
	}
	m.FinalScore = math.Round(final*10) / 10
}

// calcWSSSuccessPenalty penalizes flaky GOWAY WSS handshakes (e.g. 67% -> -10, 33% -> -20).
func calcWSSSuccessPenalty(compatible bool, successRate float64) float64 {
	if !compatible || successRate <= 0 || successRate >= 1.0 {
		return 0
	}
	return (1.0 - successRate) * 30.0
}

// ============================================================================
// SECTION: EWMA STATS & SMOOTHING (from ewma.go)
// ============================================================================
// EWMAValue tracks a single metric using Exponential Weighted Moving Average.
type EWMAValue struct {
	Value       float64   `json:"value"`
	Alpha       float64   `json:"alpha"`
	Initialized bool      `json:"initialized"`
	LastUpdate  time.Time `json:"last_update"`
}

func NewEWMAValue(alpha float64) EWMAValue {
	if alpha <= 0 || alpha > 1.0 {
		alpha = 0.2
	}
	return EWMAValue{Alpha: alpha}
}

func (e *EWMAValue) Update(val float64, now time.Time) {
	if !e.Initialized {
		e.Value = val
		e.Initialized = true
		e.LastUpdate = now
		return
	}
	e.Value = e.Alpha*val + (1.0-e.Alpha)*e.Value
	e.LastUpdate = now
}

// EWMASnapshot is an immutable representation of current EWMA values.
type EWMASnapshot struct {
	Speed           float64 `json:"speed"`
	P10Speed        float64 `json:"p10_speed"`
	MinSpeed        float64 `json:"min_speed"`
	Latency         float64 `json:"latency"`
	Loss            float64 `json:"loss"`
	Jitter          float64 `json:"jitter"`
	Stability       float64 `json:"stability"`
	StallRate       float64 `json:"stall_rate"`
	FailurePressure float64 `json:"failure_pressure"`
}

// RouteEWMATracker tracks both short-term and long-term EWMA for a route.
type RouteEWMATracker struct {
	mu sync.RWMutex

	// Short-term (alpha ~ 0.30 for faster reaction, ~5-15 min horizon)
	ShortSpeed           EWMAValue `json:"short_speed"`
	ShortP10Speed        EWMAValue `json:"short_p10_speed"`
	ShortMinSpeed        EWMAValue `json:"short_min_speed"`
	ShortLatency         EWMAValue `json:"short_latency"`
	ShortLoss            EWMAValue `json:"short_loss"`
	ShortJitter          EWMAValue `json:"short_jitter"`
	ShortStability       EWMAValue `json:"short_stability"`
	ShortStallRate       EWMAValue `json:"short_stall_rate"`
	ShortFailurePressure EWMAValue `json:"short_failure_pressure"`

	// Long-term (alpha ~ 0.05 for smoothed long-term baseline, ~several hours)
	LongSpeed           EWMAValue `json:"long_speed"`
	LongP10Speed        EWMAValue `json:"long_p10_speed"`
	LongMinSpeed        EWMAValue `json:"long_min_speed"`
	LongLatency         EWMAValue `json:"long_latency"`
	LongLoss            EWMAValue `json:"long_loss"`
	LongJitter          EWMAValue `json:"long_jitter"`
	LongStability       EWMAValue `json:"long_stability"`
	LongStallRate       EWMAValue `json:"long_stall_rate"`
	LongFailurePressure EWMAValue `json:"long_failure_pressure"`
}

func NewRouteEWMATracker(shortAlpha, longAlpha float64) *RouteEWMATracker {
	if shortAlpha <= 0 || shortAlpha > 1.0 {
		shortAlpha = 0.30
	}
	if longAlpha <= 0 || longAlpha > 1.0 {
		longAlpha = 0.05
	}
	return &RouteEWMATracker{
		ShortSpeed:           NewEWMAValue(shortAlpha),
		ShortP10Speed:        NewEWMAValue(shortAlpha),
		ShortMinSpeed:        NewEWMAValue(shortAlpha),
		ShortLatency:         NewEWMAValue(shortAlpha),
		ShortLoss:            NewEWMAValue(shortAlpha),
		ShortJitter:          NewEWMAValue(shortAlpha),
		ShortStability:       NewEWMAValue(shortAlpha),
		ShortStallRate:       NewEWMAValue(shortAlpha),
		ShortFailurePressure: NewEWMAValue(shortAlpha),

		LongSpeed:           NewEWMAValue(longAlpha),
		LongP10Speed:        NewEWMAValue(longAlpha),
		LongMinSpeed:        NewEWMAValue(longAlpha),
		LongLatency:         NewEWMAValue(longAlpha),
		LongLoss:            NewEWMAValue(longAlpha),
		LongJitter:          NewEWMAValue(longAlpha),
		LongStability:       NewEWMAValue(longAlpha),
		LongStallRate:       NewEWMAValue(longAlpha),
		LongFailurePressure: NewEWMAValue(longAlpha),
	}
}

func (t *RouteEWMATracker) Record(speed, p10Speed, minSpeed, latency, loss, jitter, stability, stallRate float64, now time.Time) {
	t.mu.Lock()
	defer t.mu.Unlock()

	t.ShortSpeed.Update(speed, now)
	t.ShortP10Speed.Update(p10Speed, now)
	t.ShortMinSpeed.Update(minSpeed, now)
	t.ShortLatency.Update(latency, now)
	t.ShortLoss.Update(loss, now)
	t.ShortJitter.Update(jitter, now)
	t.ShortStability.Update(stability, now)
	t.ShortStallRate.Update(stallRate, now)
	t.ShortFailurePressure.Update(0.0, now)

	t.LongSpeed.Update(speed, now)
	t.LongP10Speed.Update(p10Speed, now)
	t.LongMinSpeed.Update(minSpeed, now)
	t.LongLatency.Update(latency, now)
	t.LongLoss.Update(loss, now)
	t.LongJitter.Update(jitter, now)
	t.LongStability.Update(stability, now)
	t.LongStallRate.Update(stallRate, now)
	t.LongFailurePressure.Update(0.0, now)
}

// RecordFailure updates EWMA during failed probes, applying degradation pressure.
func (t *RouteEWMATracker) RecordFailure(now time.Time) {
	t.mu.Lock()
	defer t.mu.Unlock()

	t.ShortFailurePressure.Update(100.0, now)
	t.LongFailurePressure.Update(100.0, now)

	t.ShortLoss.Update(1.0, now)
	t.LongLoss.Update(0.5, now)

	t.ShortStallRate.Update(1.0, now)
	t.LongStallRate.Update(0.3, now)

	t.ShortStability.Update(0.0, now)
	if t.LongStability.Initialized {
		t.LongStability.Value *= 0.80
		t.LongStability.LastUpdate = now
	}

	if t.ShortSpeed.Initialized {
		t.ShortSpeed.Value *= 0.65
		t.ShortSpeed.LastUpdate = now
	}
	if t.ShortP10Speed.Initialized {
		t.ShortP10Speed.Value *= 0.60
		t.ShortP10Speed.LastUpdate = now
	}
	if t.ShortMinSpeed.Initialized {
		t.ShortMinSpeed.Value = 0
		t.ShortMinSpeed.LastUpdate = now
	}

	if t.LongSpeed.Initialized {
		t.LongSpeed.Value *= 0.85
		t.LongSpeed.LastUpdate = now
	}
	if t.LongP10Speed.Initialized {
		t.LongP10Speed.Value *= 0.80
		t.LongP10Speed.LastUpdate = now
	}
	if t.LongMinSpeed.Initialized {
		t.LongMinSpeed.Value *= 0.50
		t.LongMinSpeed.LastUpdate = now
	}
}

func (t *RouteEWMATracker) ShortSnapshot() EWMASnapshot {
	t.mu.RLock()
	defer t.mu.RUnlock()
	return EWMASnapshot{
		Speed:           t.ShortSpeed.Value,
		P10Speed:        t.ShortP10Speed.Value,
		MinSpeed:        t.ShortMinSpeed.Value,
		Latency:         t.ShortLatency.Value,
		Loss:            t.ShortLoss.Value,
		Jitter:          t.ShortJitter.Value,
		Stability:       t.ShortStability.Value,
		StallRate:       t.ShortStallRate.Value,
		FailurePressure: t.ShortFailurePressure.Value,
	}
}

func (t *RouteEWMATracker) LongSnapshot() EWMASnapshot {
	t.mu.RLock()
	defer t.mu.RUnlock()
	return EWMASnapshot{
		Speed:           t.LongSpeed.Value,
		P10Speed:        t.LongP10Speed.Value,
		MinSpeed:        t.LongMinSpeed.Value,
		Latency:         t.LongLatency.Value,
		Loss:            t.LongLoss.Value,
		Jitter:          t.LongJitter.Value,
		Stability:       t.LongStability.Value,
		StallRate:       t.LongStallRate.Value,
		FailurePressure: t.LongFailurePressure.Value,
	}
}

// Clone returns a deep copy of the tracker captured under read lock.
// The copy carries a fresh zero mutex so it can be marshaled safely
// outside the store lock without racing concurrent Record/RecordFailure.
func (t *RouteEWMATracker) Clone() *RouteEWMATracker {
	if t == nil {
		return nil
	}
	t.mu.RLock()
	defer t.mu.RUnlock()
	return &RouteEWMATracker{
		ShortSpeed:           t.ShortSpeed,
		ShortP10Speed:        t.ShortP10Speed,
		ShortMinSpeed:        t.ShortMinSpeed,
		ShortLatency:         t.ShortLatency,
		ShortLoss:            t.ShortLoss,
		ShortJitter:          t.ShortJitter,
		ShortStability:       t.ShortStability,
		ShortStallRate:       t.ShortStallRate,
		ShortFailurePressure: t.ShortFailurePressure,
		LongSpeed:            t.LongSpeed,
		LongP10Speed:         t.LongP10Speed,
		LongMinSpeed:         t.LongMinSpeed,
		LongLatency:          t.LongLatency,
		LongLoss:             t.LongLoss,
		LongJitter:           t.LongJitter,
		LongStability:        t.LongStability,
		LongStallRate:        t.LongStallRate,
		LongFailurePressure:  t.LongFailurePressure,
	}
}

// ============================================================================
// SECTION: ROUTE STORE & HISTORY TRACKING (from history.go)
// ============================================================================
// MeasurementSample stores one discrete observation for historical analysis.
type MeasurementSample struct {
	Timestamp          time.Time `json:"timestamp"`
	Speed              float64   `json:"speed"`
	P10Speed           float64   `json:"p10_speed"`
	MedianSpeed        float64   `json:"median_speed"`
	MinSpeed           float64   `json:"min_speed"`
	RTT                float64   `json:"rtt"`
	PacketLoss         float64   `json:"packet_loss"`
	Jitter             float64   `json:"jitter"`
	Stability          float64   `json:"stability"`
	StallCount         int       `json:"stall_count"`
	TotalStallDuration float64   `json:"total_stall_duration"`
	ZeroSpeedIntervals int       `json:"zero_speed_intervals"`
	DurationSeconds    float64   `json:"duration_seconds,omitempty"`
	Success            bool      `json:"success"`
}

// WindowStats aggregates metrics over a given sliding window (e.g. 5m, 15m, 1h, 6h, 24h).
type WindowStats struct {
	Duration           string  `json:"duration"`
	Count              int     `json:"count"`
	AvgSpeed           float64 `json:"avg_speed"`
	MedianSpeed        float64 `json:"median_speed"`
	P10Speed           float64 `json:"p10_speed"`
	MinSpeed           float64 `json:"min_speed"`
	AvgRTT             float64 `json:"avg_rtt"`
	P95RTT             float64 `json:"p95_rtt"`
	AvgLoss            float64 `json:"avg_loss"`
	AvgJitter          float64 `json:"avg_jitter"`
	P95Jitter          float64 `json:"p95_jitter"`
	AvgStability       float64 `json:"avg_stability"`
	FailRate           float64 `json:"fail_rate"`
	StallRate          float64 `json:"stall_rate"`
	TotalStallDuration float64 `json:"total_stall_duration"`
	LongestStall       float64 `json:"longest_stall"`
	Confidence         float64 `json:"confidence"` // 0.0 - 100.0
}

// HourStats tracks metrics aggregated for a specific hour of the day (00..23).
type HourStats struct {
	Hour          int       `json:"hour"`
	Count         int       `json:"count"`
	FailCount     int       `json:"fail_count"`
	AvgSpeed      float64   `json:"avg_speed"`
	MedianSpeed   float64   `json:"median_speed"`
	P10Speed      float64   `json:"p10_speed"`
	MinSpeed      float64   `json:"min_speed"`
	AvgRTT        float64   `json:"avg_rtt"`
	AvgLoss       float64   `json:"avg_loss"`
	AvgJitter     float64   `json:"avg_jitter"`
	AvgStability  float64   `json:"avg_stability"`
	StallRate     float64   `json:"stall_rate"`
	FailRate      float64   `json:"fail_rate"`
	PeakHourScore float64   `json:"peak_hour_score"`
	LastUpdated   time.Time `json:"last_updated,omitempty"`
}

// CalcPeakHourScore computes a 0-100 composite quality score for a given hour.
func CalcPeakHourScore(hs *HourStats) float64 {
	if hs == nil || hs.Count == 0 {
		return 50.0 // neutral baseline
	}
	if hs.FailRate >= 1.0 {
		return 0.0
	}

	// Speed/P10 base score (cap 15 MB/s)
	speedScore := math.Min(hs.P10Speed/12.0*100.0, 100.0)
	if speedScore <= 0 && hs.AvgSpeed > 0 {
		speedScore = math.Min(hs.AvgSpeed/15.0*100.0, 100.0)
	}

	// Stability score
	stabilityScore := hs.AvgStability
	if stabilityScore < 0 {
		stabilityScore = 0
	}

	// Jitter score
	jitterScore := math.Max(0, 100.0-hs.AvgJitter*2.5)

	// Loss score
	lossScore := math.Max(0, 100.0-hs.AvgLoss*500.0)

	base := speedScore*0.25 + stabilityScore*0.35 + lossScore*0.20 + jitterScore*0.20

	// Penalize high fail rate and stalls
	penalty := hs.FailRate*40.0 + hs.StallRate*30.0
	score := math.Max(0, base-penalty)
	return math.Round(score*10) / 10
}

// RouteRecord wraps RouteMetrics with its EWMA tracker, sample log, and peak hour matrix.
type RouteRecord struct {
	Metrics   RouteMetrics        `json:"metrics"`
	EWMA      *RouteEWMATracker   `json:"ewma_tracker"`
	PeakHours [24]HourStats       `json:"peak_hours"`
	Samples   []MeasurementSample `json:"samples"`
}

func NewRouteRecord(m RouteMetrics) *RouteRecord {
	r := &RouteRecord{
		Metrics: m,
		EWMA:    NewRouteEWMATracker(0.30, 0.05),
		Samples: make([]MeasurementSample, 0, 120),
	}
	for h := 0; h < 24; h++ {
		r.PeakHours[h] = HourStats{Hour: h, PeakHourScore: 50.0}
	}
	return r
}

// AddSample inserts a new measurement sample, updates PeakHour stats and EWMA, and trims older samples.
func (r *RouteRecord) AddSample(s MeasurementSample) {
	// 1. Append sample
	r.Samples = append(r.Samples, s)

	// Keep samples up to 24 hours (Max 10000 samples to prevent unbounded memory growth while fully covering 24h)
	latestTime := s.Timestamp
	for _, sample := range r.Samples {
		if sample.Timestamp.After(latestTime) {
			latestTime = sample.Timestamp
		}
	}
	cutoff := latestTime.Add(-24 * time.Hour)
	startIdx := 0
	for startIdx < len(r.Samples) && r.Samples[startIdx].Timestamp.Before(cutoff) {
		startIdx++
	}
	if startIdx > 0 {
		r.Samples = r.Samples[startIdx:]
	}
	if len(r.Samples) > 10000 {
		r.Samples = r.Samples[len(r.Samples)-10000:]
	}

	// 2. Update EWMA
	sampleDuration := s.DurationSeconds
	if sampleDuration <= 0 {
		sampleDuration = 10.0 // legacy snapshot fallback
	}

	if s.Success {
		stallRate := 0.0
		if s.TotalStallDuration > 0 {
			stallRate = s.TotalStallDuration / sampleDuration
			if stallRate > 1.0 {
				stallRate = 1.0
			}
		}
		r.EWMA.Record(s.Speed, s.P10Speed, s.MinSpeed, s.RTT, s.PacketLoss, s.Jitter, s.Stability, stallRate, s.Timestamp)
	} else {
		r.EWMA.RecordFailure(s.Timestamp)
	}

	// 3. Update PeakHour stats (0..23) with time-based decay
	h := s.Timestamp.Hour()
	hs := &r.PeakHours[h]

	isInitial := (hs.Count == 0 && hs.AvgSpeed == 0)

	// If hs was updated on a previous day/cycle (>12h ago), apply exponential decay to historical counts
	if !hs.LastUpdated.IsZero() && s.Timestamp.Sub(hs.LastUpdated) > 12*time.Hour {
		days := math.Max(1.0, s.Timestamp.Sub(hs.LastUpdated).Hours()/24.0)
		decay := math.Pow(0.60, days)
		hs.Count = int(float64(hs.Count) * decay)
		if hs.Count < 1 {
			hs.Count = 1
		}
		hs.FailCount = int(float64(hs.FailCount) * decay)
	}
	hs.LastUpdated = s.Timestamp
	hs.Count++

	if !s.Success {
		hs.FailCount++
	} else {
		// Alpha-weighted EWMA update so recent peak hour quality has stronger weight
		alpha := 0.35
		if isInitial {
			hs.AvgSpeed = s.Speed
			hs.MedianSpeed = s.MedianSpeed
			hs.P10Speed = s.P10Speed
			hs.MinSpeed = s.MinSpeed
			hs.AvgRTT = s.RTT
			hs.AvgLoss = s.PacketLoss
			hs.AvgJitter = s.Jitter
			hs.AvgStability = s.Stability
			if s.TotalStallDuration > 0 {
				hs.StallRate = s.TotalStallDuration / sampleDuration
			}
		} else {
			hs.AvgSpeed = hs.AvgSpeed*(1-alpha) + s.Speed*alpha
			if s.MedianSpeed > 0 {
				hs.MedianSpeed = hs.MedianSpeed*(1-alpha) + s.MedianSpeed*alpha
			}
			if s.P10Speed > 0 {
				hs.P10Speed = hs.P10Speed*(1-alpha) + s.P10Speed*alpha
			}
			if s.MinSpeed < hs.MinSpeed || hs.MinSpeed <= 0 {
				hs.MinSpeed = s.MinSpeed
			} else {
				hs.MinSpeed = hs.MinSpeed*(1-alpha) + s.MinSpeed*alpha
			}
			hs.AvgRTT = hs.AvgRTT*(1-alpha) + s.RTT*alpha
			hs.AvgLoss = hs.AvgLoss*(1-alpha) + s.PacketLoss*alpha
			hs.AvgJitter = hs.AvgJitter*(1-alpha) + s.Jitter*alpha
			hs.AvgStability = hs.AvgStability*(1-alpha) + s.Stability*alpha
			sampleStallRate := s.TotalStallDuration / sampleDuration
			hs.StallRate = hs.StallRate*(1-alpha) + sampleStallRate*alpha
		}
	}
	if hs.Count > 0 {
		hs.FailRate = float64(hs.FailCount) / float64(hs.Count)
	}
	hs.PeakHourScore = CalcPeakHourScore(hs)
}

// CalcConfidence computes a 0-100 confidence score based on:
// 1. Observation duration (span between earliest and latest sample)
// 2. Sample count
// 3. Success rate
// 4. Peak hour coverage
// 5. Recency
func (r *RouteRecord) CalcConfidence(now time.Time) float64 {
	if len(r.Samples) == 0 {
		return 20.0 // neutral starting baseline
	}

	firstTime := r.Samples[0].Timestamp
	lastTime := r.Samples[len(r.Samples)-1].Timestamp
	span := lastTime.Sub(firstTime)
	if span < 0 {
		span = 0
	}

	total := len(r.Samples)
	var validCount int
	hasPeakHour := false
	for _, s := range r.Samples {
		if s.Success {
			validCount++
		}
		h := s.Timestamp.Hour()
		if h >= 20 && h <= 22 {
			hasPeakHour = true
		}
	}

	// 1. Duration score (0 to 50 points): requires observation time to climb
	var durationScore float64
	spanMins := span.Minutes()
	if spanMins < 2 {
		durationScore = 10.0
	} else if spanMins < 5 {
		durationScore = 15.0
	} else if spanMins < 15 {
		durationScore = 25.0
	} else if spanMins < 30 {
		durationScore = 35.0
	} else if spanMins < 60 {
		durationScore = 40.0
	} else if spanMins < 180 {
		durationScore = 45.0
	} else {
		durationScore = 50.0
	}

	// 2. Sample count score (0 to 30 points)
	countScore := math.Min(30.0, float64(total)/20.0*30.0)

	// 3. Peak hour coverage bonus (0 to 10 points)
	peakBonus := 0.0
	if hasPeakHour && spanMins >= 15 {
		peakBonus = 10.0
	}

	// 4. Stability / Success bonus (0 to 10 points)
	successRate := float64(validCount) / float64(total)
	successBonus := successRate * 10.0

	rawConfidence := durationScore + countScore + peakBonus + successBonus

	// 5. Recency penalty (if last tested was long ago)
	timeSinceLast := now.Sub(lastTime)
	if timeSinceLast > 10*time.Minute {
		overMins := timeSinceLast.Minutes() - 10.0
		decay := math.Max(0.50, 1.0-(overMins/60.0)*0.50)
		rawConfidence *= decay
	}

	if rawConfidence < 20.0 {
		rawConfidence = 20.0
	} else if rawConfidence > 100.0 {
		rawConfidence = 100.0
	}
	return math.Round(rawConfidence*10) / 10
}

// CalcWindowStats aggregates samples within the specified duration before now.
func (r *RouteRecord) CalcWindowStats(d time.Duration, now time.Time) WindowStats {
	cutoff := now.Add(-d)
	var sumSpeed, sumRTT, sumLoss, sumJitter, sumStable float64
	var totalStallDuration, longestStall float64
	var minSpd float64 = math.MaxFloat64
	var validCount, failCount int
	var speeds, rtts, jitters []float64

	for i := len(r.Samples) - 1; i >= 0; i-- {
		s := r.Samples[i]
		if s.Timestamp.Before(cutoff) {
			break
		}
		if !s.Success {
			failCount++
			continue
		}
		validCount++
		sumSpeed += s.Speed
		speeds = append(speeds, s.Speed)
		if s.MinSpeed < minSpd {
			minSpd = s.MinSpeed
		}
		sumRTT += s.RTT
		rtts = append(rtts, s.RTT)
		sumLoss += s.PacketLoss
		sumJitter += s.Jitter
		jitters = append(jitters, s.Jitter)
		sumStable += s.Stability

		totalStallDuration += s.TotalStallDuration
		if s.TotalStallDuration > longestStall {
			longestStall = s.TotalStallDuration
		}
	}

	total := validCount + failCount
	ws := WindowStats{Duration: d.String(), Count: total}
	if total == 0 {
		ws.Confidence = 0.0
		return ws
	}

	ws.Confidence = r.CalcConfidence(now)

	ws.FailRate = float64(failCount) / float64(total)
	if validCount > 0 {
		vc := float64(validCount)
		ws.AvgSpeed = math.Round((sumSpeed/vc)*10) / 10
		if minSpd != math.MaxFloat64 {
			ws.MinSpeed = math.Round(minSpd*10) / 10
		}
		ws.AvgRTT = math.Round((sumRTT/vc)*10) / 10
		ws.AvgLoss = math.Round((sumLoss/vc)*1000) / 1000
		ws.AvgJitter = math.Round((sumJitter/vc)*10) / 10
		ws.AvgStability = math.Round((sumStable/vc)*10) / 10
		ws.TotalStallDuration = math.Round(totalStallDuration*10) / 10
		ws.LongestStall = math.Round(longestStall*10) / 10
		if d.Seconds() > 0 {
			ws.StallRate = math.Min(1.0, totalStallDuration/d.Seconds())
		}

		sort.Float64s(speeds)
		ws.P10Speed = math.Round(calcPercentile(speeds, 0.10)*10) / 10
		ws.MedianSpeed = math.Round(calcPercentile(speeds, 0.50)*10) / 10

		sort.Float64s(rtts)
		ws.P95RTT = math.Round(calcPercentile(rtts, 0.95)*10) / 10

		sort.Float64s(jitters)
		ws.P95Jitter = math.Round(calcPercentile(jitters, 0.95)*10) / 10
	}
	return ws
}

// PeakHourPenalty returns penalty points for this route at the given hour based on historical failure/speed drops.
func (r *RouteRecord) PeakHourPenalty(h int) float64 {
	hs := r.PeakHours[h]
	if hs.Count < 3 {
		return 0.0
	}
	penalty := 0.0
	if hs.FailRate > 0.20 {
		penalty += hs.FailRate * 30.0
	}
	if hs.AvgLoss > 0.10 {
		penalty += hs.AvgLoss * 40.0
	}
	if hs.AvgJitter > 20.0 {
		penalty += (hs.AvgJitter - 20.0) * 0.5
	}
	if hs.StallRate > 0.05 {
		penalty += hs.StallRate * 30.0
	}
	return math.Min(penalty, 40.0)
}

// RouteStore manages all active, standby, candidate, and failed routes in memory.
type RouteStore struct {
	mu     sync.RWMutex
	routes map[string]*RouteRecord // keyed by route IP or ID
}

var GlobalRouteStore = NewRouteStore()

func NewRouteStore() *RouteStore {
	return &RouteStore{
		routes: make(map[string]*RouteRecord),
	}
}

func (s *RouteStore) UpsertRoute(m RouteMetrics) *RouteRecord {
	s.mu.Lock()
	defer s.mu.Unlock()

	rec, exists := s.routes[m.IP]
	if !exists {
		rec = NewRouteRecord(m)
		s.routes[m.IP] = rec
		s.routes[m.ID] = rec
		return rec
	}

	id, prevTier, prevDur := rec.Metrics.ID, rec.Metrics.Tier, rec.Metrics.DurationSeconds
	rec.Metrics = m
	if id != "" {
		rec.Metrics.ID = id
	}
	if m.Tier == "" {
		rec.Metrics.Tier = prevTier
	}
	if m.DurationSeconds == 0 {
		rec.Metrics.DurationSeconds = prevDur
	}

	return rec
}

func (s *RouteStore) RecordProbeResult(m RouteMetrics, success bool) {
	s.mu.Lock()
	defer s.mu.Unlock()

	rec, exists := s.routes[m.IP]
	if !exists {
		rec = NewRouteRecord(m)
		s.routes[m.IP] = rec
		s.routes[m.ID] = rec
	}

	sample := MeasurementSample{
		Timestamp:          m.LastTested,
		Speed:              m.SingleSpeed,
		P10Speed:           m.P10Speed,
		MedianSpeed:        m.MedianSpeed,
		MinSpeed:           m.MinSpeed,
		RTT:                m.RTT,
		PacketLoss:         m.PacketLoss,
		Jitter:             m.Jitter,
		Stability:          m.Stability,
		StallCount:         m.StallCount,
		TotalStallDuration: m.TotalStallDuration,
		ZeroSpeedIntervals: m.ZeroSpeedIntervals,
		DurationSeconds:    m.DurationSeconds,
		Success:            success,
	}
	if sample.Speed <= 0 {
		sample.Speed = m.DownloadSpeed
	}
	if sample.P10Speed <= 0 && sample.Speed > 0 {
		sample.P10Speed = m.MinSpeed
	}
	if sample.MedianSpeed <= 0 && sample.Speed > 0 {
		sample.MedianSpeed = sample.Speed
	}
	if sample.Timestamp.IsZero() {
		sample.Timestamp = time.Now()
	}

	// 1. Capture baseline P10 BEFORE adding current sample to EWMA / History
	// This ensures sudden speed drops are accurately measured rather than immediately smoothed out.
	baselineP10 := rec.EWMA.LongSnapshot().P10Speed
	if baselineP10 <= 0 {
		baselineP10 = rec.EWMA.LongSnapshot().Speed
	}
	m.BaselineP10 = baselineP10

	// Pre-calculate SpeedDropPercent against uncorrupted baseline
	effSpeed := sample.P10Speed
	if effSpeed <= 0 && sample.MinSpeed > 0 {
		effSpeed = sample.MinSpeed
	}
	if effSpeed <= 0 {
		effSpeed = sample.Speed
	}
	if baselineP10 > 2.0 && effSpeed >= 0 {
		drop := (1.0 - (effSpeed / baselineP10)) * 100.0
		if drop > 0 {
			m.SpeedDropPercent = math.Round(drop*10) / 10
		} else {
			m.SpeedDropPercent = 0
		}
	} else {
		m.SpeedDropPercent = 0
	}

	// 2. Update health status using uncorrupted baseline
	if success {
		m.LastSuccess = sample.Timestamp
	} else if !rec.Metrics.LastSuccess.IsZero() {
		m.LastSuccess = rec.Metrics.LastSuccess
	}
	m.UpdateHealth(success, baselineP10)

	// 3. Now add sample to history and update EWMA
	rec.AddSample(sample)

	// Update EWMA snapshot
	snap := rec.EWMA.ShortSnapshot()
	m.EWMA = &snap

	// Evaluate confidence based on time duration + count + success rate + recency
	m.Confidence = rec.CalcConfidence(sample.Timestamp)
	if len(rec.Samples) > 0 {
		m.ObservationDuration = rec.Samples[len(rec.Samples)-1].Timestamp.Sub(rec.Samples[0].Timestamp).Seconds()
	}

	// Stale route check
	now := sample.Timestamp
	if now.IsZero() {
		now = time.Now()
	}
	if !m.LastTested.IsZero() {
		if m.Tier == TierActive && now.Sub(m.LastTested) > 5*time.Minute {
			m.IsStale = true
		} else if m.Tier != TierActive && now.Sub(m.LastTested) > 15*time.Minute {
			m.IsStale = true
		} else {
			m.IsStale = false
		}
	}
	if m.IsStale {
		m.Confidence *= 0.50
	}

	// Update current hour's PeakHourScore
	h := sample.Timestamp.Hour()
	m.PeakHourScore = rec.PeakHours[h].PeakHourScore

	// Evaluate multi-horizon scores
	penalty := rec.PeakHourPenalty(h)
	GlobalScoreEngine.EvaluateRoute(&m, snap, rec.EWMA.LongSnapshot(), penalty)
	if m.IsStale {
		m.FinalScore *= 0.50
	}

	// Assign grade and recommendation
	m.StabilityGrade = m.DetermineStabilityGrade()
	recType, reasons := m.GenerateRecommendation()
	m.Recommendation = recType
	m.RecommendationReasons = reasons

	// Commit updated metrics into record
	rec.Metrics = m

	// Automatically evaluate candidate promotion and degraded route demotion
	s.evaluateTierTransitionsLocked(sample.Timestamp)
}

func (s *RouteStore) Get(idOrIP string) (*RouteRecord, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	rec, ok := s.routes[idOrIP]
	return rec, ok
}

// GetMetrics returns a thread-safe snapshot copy of RouteMetrics, preventing pointer leakage.
func (s *RouteStore) GetMetrics(idOrIP string) (RouteMetrics, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	rec, ok := s.routes[idOrIP]
	if !ok || rec == nil {
		return RouteMetrics{}, false
	}
	m := rec.Metrics
	if m.RecommendationReasons != nil {
		reasons := make([]string, len(m.RecommendationReasons))
		copy(reasons, m.RecommendationReasons)
		m.RecommendationReasons = reasons
	}
	if m.EWMA != nil {
		snap := *m.EWMA
		m.EWMA = &snap
	}
	return m, true
}

// GetEWMASnapshots returns thread-safe short and long EWMA snapshots for a route.
func (s *RouteStore) GetEWMASnapshots(idOrIP string) (EWMASnapshot, EWMASnapshot, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	rec, ok := s.routes[idOrIP]
	if !ok || rec == nil || rec.EWMA == nil {
		return EWMASnapshot{}, EWMASnapshot{}, false
	}
	return rec.EWMA.ShortSnapshot(), rec.EWMA.LongSnapshot(), true
}

// GetSamples returns a thread-safe copy of historical measurement samples.
func (s *RouteStore) GetSamples(idOrIP string) []MeasurementSample {
	s.mu.RLock()
	defer s.mu.RUnlock()
	rec, ok := s.routes[idOrIP]
	if !ok || rec == nil {
		return nil
	}
	samples := make([]MeasurementSample, len(rec.Samples))
	copy(samples, rec.Samples)
	return samples
}

// UpdateRouteColo safely updates the Colo for an existing route under lock if it was previously empty.
func (s *RouteStore) UpdateRouteColo(ip, colo string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()

	rec, ok := s.routes[ip]
	if !ok || rec == nil {
		return false
	}
	if rec.Metrics.Colo == "" && colo != "" {
		rec.Metrics.Colo = colo
		return true
	}
	return false
}

// getAllLocked returns all unique RouteMetrics without acquiring locks (call while holding mu).
func (s *RouteStore) getAllLocked() []RouteMetrics {
	seen := make(map[string]bool)
	var list []RouteMetrics
	now := time.Now()
	for _, rec := range s.routes {
		if !seen[rec.Metrics.IP] {
			seen[rec.Metrics.IP] = true
			m := rec.Metrics
			if !m.LastTested.IsZero() {
				if m.Tier == TierActive && now.Sub(m.LastTested) > 5*time.Minute {
					m.IsStale = true
				} else if m.Tier != TierActive && now.Sub(m.LastTested) > 15*time.Minute {
					m.IsStale = true
				}
			}
			list = append(list, m)
		}
	}
	return list
}

func (s *RouteStore) GetAll() []RouteMetrics {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.getAllLocked()
}

// isCurrentProfileGOWAYWSS checks if the active probe profile in GlobalProbeScheduler is GOWAY-WSS
// or CUSTOM with protocol "wss".
func isCurrentProfileGOWAYWSS() bool {
	if GlobalProbeScheduler == nil {
		return false
	}
	cfg := GlobalProbeScheduler.GetConfig()
	return cfg.Profile.Type == ProfileGOWAYWSS || (cfg.Profile.Type == ProfileCustom && cfg.Profile.Protocol == "wss")
}

// GetBest selects routes optimizing for stability > peak speed, with multi-level tie-breaking.
func (s *RouteStore) GetBest(limit int, colo string) []RouteMetrics {
	s.mu.RLock()
	all := s.getAllLocked()
	s.mu.RUnlock()

	mode := GlobalScoreEngine.GetMode()
	now := time.Now()
	curHour := now.Hour()
	isPeakTime := (mode == ModePeak) || (curHour >= 19 && curHour <= 23)
	isGOWAYWSS := isCurrentProfileGOWAYWSS()

	type candidateScore struct {
		m              RouteMetrics
		effectiveScore float64
	}

	var scored []candidateScore
	for _, m := range all {
		if colo != "" && m.Colo != colo {
			continue
		}

		// Stale route protection:
		// If untested for > 60 minutes, exclude from GetBest() completely.
		timeSinceTest := now.Sub(m.LastTested)
		if !m.LastTested.IsZero() && timeSinceTest > 60*time.Minute {
			continue
		}

		// 1. Exclude FAILED and FAILING routes
		if m.Health == HealthFailed || m.Health == HealthFailing {
			continue
		}

		// GOWAY-WSS hard compatibility gate:
		// In GOWAY-WSS mode, routes incompatible with WSS handshake must be excluded completely.
		if isGOWAYWSS && !m.GOWAYWSSCompatible {
			continue
		}

		effective := m.FinalScore

		// Stale route penalization: untested > 5m for active or > 15m for others
		if m.IsStale || (!m.LastTested.IsZero() && ((m.Tier == TierActive && timeSinceTest > 5*time.Minute) || (m.Tier != TierActive && timeSinceTest > 15*time.Minute))) {
			m.IsStale = true
			effective *= 0.50
			m.Confidence *= 0.50
		}

		// 2. RECOVERING routes downweighted by 30%
		if m.Health == HealthRecovering {
			effective *= 0.70
		}

		// 3. DEGRADED routes downweighted by 25%
		if m.Health == HealthDegraded {
			effective *= 0.75
		}

		// 4. Low confidence penalty (ensure unverified routes don't outrank proven nodes)
		conf := m.Confidence
		if conf < 10.0 {
			conf = 10.0
		}
		effective *= (0.50 + 0.50*(conf/100.0))

		// 5. Peak Hour mode prioritization
		if isPeakTime && m.PeakHourScore > 0 {
			effective = effective*0.65 + m.PeakHourScore*0.35
		}

		scored = append(scored, candidateScore{m: m, effectiveScore: effective})
	}

	// Multi-level sorting:
	// 1. EffectiveScore descending
	// 2. Tie-break: higher P10Speed
	// 3. Tie-break: lower Jitter
	// 4. Tie-break: lower PacketLoss
	// 5. Tie-break: lower RTT
	sort.Slice(scored, func(i, j int) bool {
		diff := scored[i].effectiveScore - scored[j].effectiveScore
		if math.Abs(diff) > 0.5 {
			return scored[i].effectiveScore > scored[j].effectiveScore
		}
		// Tie-break 1: P10 Speed
		if math.Abs(scored[i].m.P10Speed-scored[j].m.P10Speed) > 0.2 {
			return scored[i].m.P10Speed > scored[j].m.P10Speed
		}
		// Tie-break 2: Jitter
		if math.Abs(scored[i].m.Jitter-scored[j].m.Jitter) > 1.0 {
			return scored[i].m.Jitter < scored[j].m.Jitter
		}
		// Tie-break 3: Packet Loss
		if math.Abs(scored[i].m.PacketLoss-scored[j].m.PacketLoss) > 0.01 {
			return scored[i].m.PacketLoss < scored[j].m.PacketLoss
		}
		// Tie-break 4: TCPLatency / RTT
		return scored[i].m.RTT < scored[j].m.RTT
	})

	var result []RouteMetrics
	for _, sc := range scored {
		result = append(result, sc.m)
	}

	if limit > 0 && len(result) > limit {
		result = result[:limit]
	}
	return result
}

func (s *RouteStore) SetTier(idOrIP string, tier RouteTier) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	rec, ok := s.routes[idOrIP]
	if !ok {
		return false
	}
	rec.Metrics.Tier = tier
	return true
}

func (s *RouteStore) GetHistoryWindows(idOrIP string) map[string]WindowStats {
	s.mu.RLock()
	defer s.mu.RUnlock()
	rec, ok := s.routes[idOrIP]
	if !ok {
		return nil
	}
	now := time.Now()
	return map[string]WindowStats{
		"5m":  rec.CalcWindowStats(5*time.Minute, now),
		"15m": rec.CalcWindowStats(15*time.Minute, now),
		"1h":  rec.CalcWindowStats(1*time.Hour, now),
		"6h":  rec.CalcWindowStats(6*time.Hour, now),
		"24h": rec.CalcWindowStats(24*time.Hour, now),
	}
}

func (s *RouteStore) GetPeakHours(idOrIP string) [24]HourStats {
	s.mu.RLock()
	defer s.mu.RUnlock()
	rec, ok := s.routes[idOrIP]
	if !ok {
		return [24]HourStats{}
	}
	return rec.PeakHours
}

// EvaluateTierTransitions evaluates promotion, demotion, and pruning across all managed routes.
func (s *RouteStore) EvaluateTierTransitions(now time.Time) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.evaluateTierTransitionsLocked(now)
}

func (s *RouteStore) evaluateTierTransitionsLocked(now time.Time) {
	if now.IsZero() {
		now = time.Now()
	}

	isGOWAYWSS := isCurrentProfileGOWAYWSS()

	seen := make(map[string]bool)
	var records []*RouteRecord
	for _, rec := range s.routes {
		if rec != nil && !seen[rec.Metrics.IP] {
			seen[rec.Metrics.IP] = true
			records = append(records, rec)
		}
	}

	// 1. Long-term failed route pruning and initial tier categorization:
	var activeRec *RouteRecord
	var standbyRecs []*RouteRecord
	var candidateRecs []*RouteRecord

	for _, rec := range records {
		m := &rec.Metrics
		// Prune if Health == HealthFailed, ConsecutiveFails >= 10, and untested for > 2 hours
		if m.Health == HealthFailed && m.ConsecutiveFails >= 10 && !m.LastTested.IsZero() && now.Sub(m.LastTested) > 2*time.Hour {
			delete(s.routes, m.IP)
			delete(s.routes, m.ID)
			continue
		}

		switch m.Tier {
		case TierActive:
			activeRec = rec
		case TierStandby:
			standbyRecs = append(standbyRecs, rec)
		case TierCandidate:
			candidateRecs = append(candidateRecs, rec)
		}
	}

	// Ensure each route transitions at most once per evaluation cycle
	transitioned := make(map[string]bool)

	// 2. Demotion: Active -> Standby
	if activeRec != nil {
		m := &activeRec.Metrics
		if m.Health == HealthDegraded || m.Health == HealthFailing || m.Health == HealthFailed || m.SpeedDropPercent >= 35.0 || m.ConsecutiveFails >= 2 || (isGOWAYWSS && !m.GOWAYWSSCompatible) {
			m.Tier = TierStandby
			transitioned[m.IP] = true
			standbyRecs = append(standbyRecs, activeRec)
			activeRec = nil
		}
	}

	// 3. Demotion: Standby -> Candidate
	var remainingStandbys []*RouteRecord
	for _, rec := range standbyRecs {
		if transitioned[rec.Metrics.IP] {
			remainingStandbys = append(remainingStandbys, rec)
			continue
		}
		m := &rec.Metrics
		if m.Health == HealthFailing || m.Health == HealthFailed || (m.ObservationDuration >= 300.0 && m.FinalScore < 50.0 && m.FinalScore > 0) || m.ConsecutiveFails >= 3 {
			m.Tier = TierCandidate
			transitioned[m.IP] = true
			candidateRecs = append(candidateRecs, rec)
		} else {
			remainingStandbys = append(remainingStandbys, rec)
		}
	}
	standbyRecs = remainingStandbys

	// 4. Demotion: Candidate -> Failed
	var remainingCandidates []*RouteRecord
	for _, rec := range candidateRecs {
		if transitioned[rec.Metrics.IP] {
			remainingCandidates = append(remainingCandidates, rec)
			continue
		}
		m := &rec.Metrics
		if m.Health == HealthFailed || m.ConsecutiveFails >= 5 {
			m.Tier = TierFailed
			transitioned[m.IP] = true
		} else {
			remainingCandidates = append(remainingCandidates, rec)
		}
	}
	candidateRecs = remainingCandidates

	// 5. Promotion: Candidate -> Standby
	// Requires:
	// - ObservationDuration >= 300s (5 min)
	// - len(Samples) >= 3
	// - Confidence >= 35.0
	// - Health == HealthHealthy
	// - FinalScore >= 70.0
	// - PacketLoss <= 0.05
	// - Jitter <= 25.0
	// - StallCount == 0
	// - GOWAY-WSS compatibility gate
	for _, rec := range candidateRecs {
		if transitioned[rec.Metrics.IP] {
			continue
		}
		m := &rec.Metrics
		wssGateOK := !isGOWAYWSS || (m.GOWAYWSSCompatible && (m.WSSSuccessRate == 0 || m.WSSSuccessRate >= 0.67))
		if m.ObservationDuration >= 300.0 && len(rec.Samples) >= 3 && m.Confidence >= 35.0 &&
			m.Health == HealthHealthy && m.FinalScore >= 70.0 && m.PacketLoss <= 0.05 &&
			m.Jitter <= 25.0 && m.StallCount == 0 && wssGateOK {
			m.Tier = TierStandby
			transitioned[m.IP] = true
			standbyRecs = append(standbyRecs, rec)
		}
	}

	// 6. Promotion: Standby -> Active
	// Eligible standby requires:
	// - Health == HealthHealthy
	// - Confidence >= 50.0
	// - FinalScore >= 70.0
	// - PacketLoss <= 0.02
	// - StallCount == 0
	// - GOWAY-WSS compatibility gate
	if activeRec == nil {
		var bestStandby *RouteRecord
		for _, rec := range standbyRecs {
			if transitioned[rec.Metrics.IP] {
				continue
			}
			m := &rec.Metrics
			wssGateOK := !isGOWAYWSS || (m.GOWAYWSSCompatible && (m.WSSSuccessRate == 0 || m.WSSSuccessRate >= 0.67))
			if m.Health == HealthHealthy && m.Confidence >= 50.0 && m.FinalScore >= 70.0 && m.PacketLoss <= 0.02 && m.StallCount == 0 && wssGateOK {
				if bestStandby == nil || m.FinalScore > bestStandby.Metrics.FinalScore {
					bestStandby = rec
				}
			}
		}
		if bestStandby != nil {
			bestStandby.Metrics.Tier = TierActive
			activeRec = bestStandby
		}
	} else {
		// Active exists: only replace if Standby significantly and consistently beats Active over long term
		// FinalScore >= active.FinalScore + 5.0 && Confidence >= 60.0 && P10Speed >= active.P10Speed && ObservationDuration >= 900s
		var bestChallenger *RouteRecord
		for _, rec := range standbyRecs {
			if transitioned[rec.Metrics.IP] {
				continue
			}
			m := &rec.Metrics
			wssGateOK := !isGOWAYWSS || (m.GOWAYWSSCompatible && (m.WSSSuccessRate == 0 || m.WSSSuccessRate >= 0.67))
			if m.Health == HealthHealthy && m.Confidence >= 60.0 && m.ObservationDuration >= 900.0 &&
				m.FinalScore >= activeRec.Metrics.FinalScore+5.0 && m.P10Speed >= activeRec.Metrics.P10Speed &&
				m.PacketLoss <= 0.02 && m.StallCount == 0 && wssGateOK {
				if bestChallenger == nil || m.FinalScore > bestChallenger.Metrics.FinalScore {
					bestChallenger = rec
				}
			}
		}
		if bestChallenger != nil {
			activeRec.Metrics.Tier = TierStandby
			bestChallenger.Metrics.Tier = TierActive
			activeRec = bestChallenger
		}
	}
}

// SnapshotContainer stores full state for robust serialization.
type SnapshotContainer struct {
	Version   string                  `json:"version"`
	Timestamp time.Time               `json:"timestamp"`
	Routes    map[string]*RouteRecord `json:"routes"`
}

// Clone returns a deep copy of the record safe to marshal outside the store lock.
// Caller must hold at least s.mu.RLock() so concurrent RecordProbeResult/Upsert
// (which hold s.mu.Lock()) cannot mutate rec while it is being copied.
func (r *RouteRecord) Clone() *RouteRecord {
	if r == nil {
		return nil
	}
	cp := &RouteRecord{
		Metrics:   r.Metrics,
		PeakHours: r.PeakHours,
		EWMA:      r.EWMA.Clone(),
	}
	if r.Samples != nil {
		cp.Samples = make([]MeasurementSample, len(r.Samples))
		copy(cp.Samples, r.Samples)
	}
	if r.Metrics.RecommendationReasons != nil {
		reasons := make([]string, len(r.Metrics.RecommendationReasons))
		copy(reasons, r.Metrics.RecommendationReasons)
		cp.Metrics.RecommendationReasons = reasons
	}
	if r.Metrics.EWMA != nil {
		snap := *r.Metrics.EWMA
		cp.Metrics.EWMA = &snap
	}
	return cp
}

// SaveSnapshot serializes full state to a JSON file atomically (Windows safe).
func (s *RouteStore) SaveSnapshot(path string) error {
	// Deep-copy under RLock so json.Marshal below never reads live records
	// concurrently mutated by RecordProbeResult/AddSample/Upsert.
	s.mu.RLock()
	uniqueRecords := make(map[string]*RouteRecord)
	for ip, rec := range s.routes {
		if rec != nil && rec.Metrics.IP == ip {
			uniqueRecords[ip] = rec.Clone()
		}
	}
	s.mu.RUnlock()

	container := SnapshotContainer{
		Version:   AppVersion,
		Timestamp: time.Now(),
		Routes:    uniqueRecords,
	}

	data, err := json.MarshalIndent(container, "", "  ")
	if err != nil {
		return err
	}

	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0644); err != nil {
		return err
	}

	// Atomic replace: on Windows remove target first if needed
	_ = os.Remove(path)
	return os.Rename(tmpPath, path)
}

// LoadSnapshot restores routes from a JSON snapshot file with version tolerance.
func (s *RouteStore) LoadSnapshot(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	// 1. Try modern v2.1.0 SnapshotContainer
	var container SnapshotContainer
	if err := json.Unmarshal(data, &container); err == nil && len(container.Routes) > 0 {
		s.mu.Lock()
		defer s.mu.Unlock()
		for ip, rec := range container.Routes {
			if rec != nil {
				if rec.EWMA == nil {
					rec.EWMA = NewRouteEWMATracker(0.30, 0.05)
				}
				if rec.Metrics.IP == "" {
					rec.Metrics.IP = ip
				}
				if rec.Metrics.ID == "" {
					rec.Metrics.ID = GenerateRouteID(rec.Metrics.IP, rec.Metrics.Port)
				}
				s.routes[ip] = rec
				s.routes[rec.Metrics.ID] = rec
			}
		}
		return nil
	}

	// 2. Try legacy v2.0 []RouteMetrics
	var legacyList []RouteMetrics
	if err := json.Unmarshal(data, &legacyList); err == nil {
		for _, m := range legacyList {
			s.UpsertRoute(m)
		}
		return nil
	}

	return err
}

