type cidrInfo struct {
	baseIP   uint32
	maxHost  int
	hostBits int
}

var cidrCache sync.Map

func parseCIDRCached(cidr string) *cidrInfo {
	if v, ok := cidrCache.Load(cidr); ok {
		if v == nil {
			return nil
		}
		return v.(*cidrInfo)
	}
	_, ipNet, err := net.ParseCIDR(cidr)
	if err != nil {
		return nil
	}
	ip4 := ipNet.IP.To4()
	if ip4 == nil {
		// IPv6 or non-IPv4 CIDR: do not panic, safely return nil
		return nil
	}
	ones, bits := ipNet.Mask.Size()
	hostBits := bits - ones
	if hostBits < 0 || hostBits > 32 {
		return nil
	}
	var info *cidrInfo
	if hostBits <= 2 {
		info = &cidrInfo{baseIP: binary.BigEndian.Uint32(ip4), maxHost: 0, hostBits: hostBits}
	} else {
		info = &cidrInfo{baseIP: binary.BigEndian.Uint32(ip4), maxHost: (1 << hostBits) - 2, hostBits: hostBits}
	}
	cidrCache.Store(cidr, info)
	return info
}

type NodeResult struct {
	IP                 string  `json:"ip"`
	Port               int     `json:"port"`
	TCPLatency         float64 `json:"tcp_latency"`
	DownloadSpeed      float64 `json:"download_speed"`
	SingleSpeed        float64 `json:"single_speed"`
	LoadLatency        float64 `json:"load_latency"`
	Colo               string  `json:"colo"`
	Score              float64 `json:"score"`
	Jitter             float64 `json:"jitter"`
	Stability          float64 `json:"stability"`
	MinSpeed           float64 `json:"min_speed"`
	P10Speed           float64 `json:"p10_speed"`
	MedianSpeed        float64 `json:"median_speed"`
	StallCount         int     `json:"stall_count"`
	TotalStallDuration float64 `json:"total_stall_duration,omitempty"`
	ZeroSpeedIntervals int     `json:"zero_speed_intervals"`
	PacketLoss         float64 `json:"packet_loss"`
	Recommendation     string  `json:"recommendation,omitempty"`
	// GOWAY WSS compatibility gate (ProfileGOWAYWSS)
	GOWAYWSSCompatible   bool    `json:"goway_wss_compatible,omitempty"`
	GOWAYWSSLatency      float64 `json:"goway_wss_latency,omitempty"`
	WSSJitter            float64 `json:"wss_jitter,omitempty"`
	WSSSuccessRate       float64 `json:"wss_success_rate,omitempty"`
	GOWAYWSSErrorStage   string  `json:"goway_wss_error_stage,omitempty"`
	GOWAYWSSHTTPStatus   int     `json:"goway_wss_http_status,omitempty"`
	GOWAYWSSErrorMessage string  `json:"goway_wss_error_message,omitempty"`
	GOWAYWSSSNISent      string  `json:"goway_wss_sni_sent,omitempty"`
	GOWAYWSSHostSent     string  `json:"goway_wss_host_sent,omitempty"`
	GOWAYWSSPathSent     string  `json:"goway_wss_path_sent,omitempty"`
}

func (n *NodeResult) CalcScore() {
	w := GlobalScoreEngine.ActiveWeights()
	effectiveSpeed := n.DownloadSpeed
	if n.SingleSpeed > 0 {
		effectiveSpeed = n.SingleSpeed
	}
	effectiveP10 := n.P10Speed
	if effectiveP10 <= 0 && effectiveSpeed > 0 {
		effectiveP10 = n.MinSpeed
	}
	score := GlobalScoreEngine.calcMetricScore(w, effectiveSpeed, effectiveP10, n.MinSpeed, n.TCPLatency, n.Jitter, n.PacketLoss, n.Stability, true, n.Colo)
	// 长连接严苛质量门控：严惩中途断流、高丢包、WSS 握手不稳及满载延迟暴涨（Bufferbloat）
	if n.StallCount > 0 {
		score -= float64(n.StallCount) * 12.0
	}
	if n.PacketLoss > 0.10 {
		score -= (n.PacketLoss - 0.10) * 35.0
	}
	score -= calcWSSSuccessPenalty(n.GOWAYWSSCompatible, n.WSSSuccessRate)
	if n.LoadLatency > 0 && n.TCPLatency > 0 && n.LoadLatency > n.TCPLatency*2.2+60.0 {
		bloatPenalty := math.Min(10.0, (n.LoadLatency-(n.TCPLatency*2.2+60.0))*0.04)
		score -= bloatPenalty
	}
	if score < 0 {
		score = 0
	}
	n.Score = math.Round(score*10) / 10
}

func randIPFromCIDR(cidr string) string {
	info := parseCIDRCached(cidr)
	if info == nil {
		return ""
	}
	if info.hostBits <= 2 {
		var buf [4]byte
		binary.BigEndian.PutUint32(buf[:], info.baseIP)
		return net.IP(buf[:]).String()
	}
	offset := rand.Intn(info.maxHost) + 1
	ip := info.baseIP + uint32(offset)
	var buf [4]byte
	binary.BigEndian.PutUint32(buf[:], ip)
	return net.IP(buf[:]).String()
}

// SpeedIntervalSample represents one discrete interval observation.
type SpeedIntervalSample struct {
	Timestamp       time.Time `json:"timestamp"`
	DeltaBytes      int64     `json:"delta_bytes"`
	DeltaDuration   float64   `json:"delta_duration"`
	IntervalSpeed   float64   `json:"interval_speed"`   // MB/s
	CumulativeSpeed float64   `json:"cumulative_speed"` // MB/s
	Elapsed         float64   `json:"elapsed"`          // seconds
	TotalBytes      int64     `json:"total_bytes"`
	IsStall         bool      `json:"is_stall"`
}

// SpeedMetrics contains comprehensive statistics derived from speed interval samples.
type SpeedMetrics struct {
	AverageSpeed           float64               `json:"avg_speed"`
	MedianSpeed            float64               `json:"median_speed"`
	P10Speed               float64               `json:"p10_speed"`
	P25Speed               float64               `json:"p25_speed"`
	MinSpeed               float64               `json:"min_speed"`
	MaxSpeed               float64               `json:"max_speed"`
	StdDev                 float64               `json:"std_dev"`
	CoefficientOfVariation float64               `json:"cv"`
	Stability              float64               `json:"stability"` // 0.0 - 100.0
	ZeroSpeedIntervals     int                   `json:"zero_speed_intervals"`
	StallCount             int                   `json:"stall_count"`
	TotalStallDuration     float64               `json:"total_stall_duration"`
	LongestStallDuration   float64               `json:"longest_stall_duration"`
	StallRate              float64               `json:"stall_rate"` // TotalStallDuration / TotalDuration
	LoadLatency            float64               `json:"load_latency,omitempty"`
	HTTPStatus             int                   `json:"http_status,omitempty"`
	Aborted403             bool                  `json:"aborted_403,omitempty"`
	Intervals              []SpeedIntervalSample `json:"intervals,omitempty"`
}

// calcPercentile computes the p-th percentile (p in [0.0, 1.0]) using linear interpolation on sorted data.
func calcPercentile(sortedVals []float64, p float64) float64 {
	if len(sortedVals) == 0 {
		return 0
	}
	if len(sortedVals) == 1 || p <= 0 {
		return sortedVals[0]
	}
	if p >= 1.0 {
		return sortedVals[len(sortedVals)-1]
	}
	idx := p * float64(len(sortedVals)-1)
	lower := int(math.Floor(idx))
	upper := int(math.Ceil(idx))
	if lower == upper {
		return sortedVals[lower]
	}
	weight := idx - float64(lower)
	return sortedVals[lower]*(1.0-weight) + sortedVals[upper]*weight
}

// CalcCompositeStability computes multi-dimensional stability (0 - 100):
// SpeedConsistency * 0.35 + FloorStability * 0.25 + NoStallRatio * 0.20 + LatencyConsistency * 0.10 + LossConsistency * 0.10
func CalcCompositeStability(sm *SpeedMetrics, tcpRTT, jitter, packetLoss float64) float64 {
	if sm == nil {
		return 0
	}

	// 1. SpeedConsistency: based on CV
	speedConsistency := 100.0 - sm.CoefficientOfVariation*100.0
	if speedConsistency < 0 {
		speedConsistency = 0
	} else if speedConsistency > 100.0 {
		speedConsistency = 100.0
	}

	// 2. FloorStability: P10 / AverageSpeed ratio (guarantees anti-buffering floor)
	floorStability := 0.0
	if sm.AverageSpeed > 0.001 {
		floorStability = (sm.P10Speed / sm.AverageSpeed) * 100.0
		if floorStability < 0 {
			floorStability = 0
		} else if floorStability > 100.0 {
			floorStability = 100.0
		}
	}

	// 3. NoStallRatio: ratio of non-stall duration
	noStallRatio := (1.0 - sm.StallRate) * 100.0
	if noStallRatio < 0 {
		noStallRatio = 0
	} else if noStallRatio > 100.0 {
		noStallRatio = 100.0
	}

	// 4. LatencyConsistency: jitter compared to RTT
	latencyConsistency := 100.0
	if tcpRTT > 0 {
		latencyConsistency = 100.0 - (jitter/(tcpRTT+1.0))*100.0
		if latencyConsistency < 0 {
			latencyConsistency = 0
		} else if latencyConsistency > 100.0 {
			latencyConsistency = 100.0
		}
	}

	// 5. LossConsistency: packet loss percentage
	lossConsistency := (1.0 - packetLoss) * 100.0
	if lossConsistency < 0 {
		lossConsistency = 0
	} else if lossConsistency > 100.0 {
		lossConsistency = 100.0
	}

	composite := speedConsistency*0.35 +
		floorStability*0.25 +
		noStallRatio*0.20 +
		latencyConsistency*0.10 +
		lossConsistency*0.10

	if math.IsNaN(composite) || math.IsInf(composite, 0) || composite < 0 {
		composite = 0
	} else if composite > 100.0 {
		composite = 100.0
	}
	return math.Round(composite*10) / 10
}

// ProcessIntervalSamples processes collected intervals into comprehensive SpeedMetrics.
// Crucially, zero speed intervals are NEVER discarded.
func ProcessIntervalSamples(intervals []SpeedIntervalSample, totalBytes int64, totalDuration float64, tcpRTT, jitter, packetLoss float64) SpeedMetrics {
	sm := SpeedMetrics{
		Intervals: intervals,
	}
	if totalDuration <= 0.01 {
		return sm
	}

	finalMB := float64(totalBytes) / 1024.0 / 1024.0
	sm.AverageSpeed = finalMB / totalDuration

	if len(intervals) == 0 {
		sm.MinSpeed = 0
		sm.MedianSpeed = sm.AverageSpeed
		sm.P10Speed = sm.AverageSpeed
		sm.P25Speed = sm.AverageSpeed
		sm.MaxSpeed = sm.AverageSpeed
		sm.Stability = CalcCompositeStability(&sm, tcpRTT, jitter, packetLoss)
		return sm
	}

	speeds := make([]float64, len(intervals))
	var sum float64
	minSpd := math.MaxFloat64
	maxSpd := 0.0

	curConsecutiveStalls := 0
	curConsecutiveStallDur := 0.0
	for i, it := range intervals {
		s := it.IntervalSpeed
		speeds[i] = s
		sum += s
		if s < minSpd {
			minSpd = s
		}
		if s > maxSpd {
			maxSpd = s
		}

		if it.IsStall {
			sm.ZeroSpeedIntervals++
			sm.TotalStallDuration += it.DeltaDuration
			curConsecutiveStalls++
			curConsecutiveStallDur += it.DeltaDuration
			if curConsecutiveStallDur > sm.LongestStallDuration {
				sm.LongestStallDuration = curConsecutiveStallDur
			}
		} else {
			if curConsecutiveStalls > 0 {
				sm.StallCount++
				curConsecutiveStalls = 0
				curConsecutiveStallDur = 0.0
			}
		}
	}
	if curConsecutiveStalls > 0 {
		sm.StallCount++
	}

	if totalDuration > 0 {
		sm.StallRate = sm.TotalStallDuration / totalDuration
		if sm.StallRate > 1.0 {
			sm.StallRate = 1.0
		}
	}

	if minSpd == math.MaxFloat64 {
		minSpd = 0
	}
	sm.MinSpeed = minSpd
	sm.MaxSpeed = maxSpd

	// Mean and CV over all intervals (including 0s)
	mean := sum / float64(len(speeds))
	if len(speeds) > 1 && mean > 0.001 {
		var variance float64
		for _, s := range speeds {
			diff := s - mean
			variance += diff * diff
		}
		variance /= float64(len(speeds))
		sm.StdDev = math.Sqrt(variance)
		sm.CoefficientOfVariation = sm.StdDev / mean
	} else if mean <= 0.001 {
		sm.CoefficientOfVariation = 1.0
	}

	// Percentiles on sorted copy
	sortedSpeeds := make([]float64, len(speeds))
	copy(sortedSpeeds, speeds)
	sort.Float64s(sortedSpeeds)

	sm.P10Speed = calcPercentile(sortedSpeeds, 0.10)
	sm.P25Speed = calcPercentile(sortedSpeeds, 0.25)
	sm.MedianSpeed = calcPercentile(sortedSpeeds, 0.50)

	sm.Stability = CalcCompositeStability(&sm, tcpRTT, jitter, packetLoss)
	return sm
}

var ipColoCache sync.Map

// SingleStreamTestDetailed runs true 1s interval sampling and returns full SpeedMetrics.
// 优化：将连接握手超时与实际下载流计时分离，支持慢速/断流节点提前中止（Early-Abort）。
func SingleStreamTestDetailed(ctx context.Context, target ResolvedProbeTarget, duration int,
	progressCallback func(LiveProgress), tcpRTT, jitter, packetLoss float64) SpeedMetrics {

	parsedURL, err := url.Parse(target.URL)
	if err != nil {
		return SpeedMetrics{}
	}

	client := makeHTTPClient(target.IP, target.Port, target.SNI)
	if tr, ok := client.Transport.(*http.Transport); ok {
		defer tr.CloseIdleConnections()
	}

	if duration < 1 {
		duration = 2
	}
	// 给予独立的 4 秒握手+首包缓冲时间，避免建连耗时吃掉实际下载时长
	totalTimeout := time.Duration(duration)*time.Second + 8*time.Second
	reqCtx, cancel := context.WithTimeout(ctx, totalTimeout)
	defer cancel()

	req, err := newCFRequestWithContext(reqCtx, "GET", target.URL)
	if err != nil {
		return SpeedMetrics{}
	}
	if strings.Contains(target.URL, "speed.cloudflare.com") {
		req.Host = "speed.cloudflare.com"
	} else {
		req.Host = target.Host
	}
	req.Header.Set("Connection", "keep-alive")

	if !strings.Contains(target.URL, "speed.cloudflare.com") {
		scheme := target.Protocol
		if scheme == "" {
			scheme = parsedURL.Scheme
		}
		if scheme == "" {
			scheme = "https"
		}
		baseURL := scheme + "://" + target.Host
		setCFHeadersForURL(req, baseURL)
	}

	// 限制连接与响应头 TTFB 必须在 3.5 秒内完成，超时直接淘汰
	headerTimer := time.AfterFunc(3500*time.Millisecond, func() {
		cancel()
	})
	resp, err := client.Do(req)
	headerTimer.Stop()
	if err != nil {
		return SpeedMetrics{}
	}
	defer resp.Body.Close()

	if resp.StatusCode >= 400 {
		return SpeedMetrics{
			HTTPStatus: resp.StatusCode,
			Aborted403: resp.StatusCode == http.StatusForbidden,
		}
	}

	// 从响应头提取 cf-ray 并写入缓存，省去后续重复请求 /cdn-cgi/trace
	if cfRay := resp.Header.Get("cf-ray"); cfRay != "" {
		if parts := strings.Split(cfRay, "-"); len(parts) >= 2 {
			colo := strings.ToUpper(parts[len(parts)-1])
			if colo != "" {
				ipColoCache.Store(target.IP, colo)
				GlobalRouteStore.UpdateRouteColo(target.IP, colo)
			}
		}
	}

	// 从真正收到响应体开始精确计时 duration 秒（预留 150ms 裕度确保第 duration 次 1s Ticker 完整触发）
	startGlobal := time.Now()
	streamTimer := time.AfterFunc(time.Duration(duration)*time.Second+400*time.Millisecond, func() {
		cancel()
	})
	defer streamTimer.Stop()

	var totalBytes int64
	sampleInterval := 1 * time.Second
	var intervals []SpeedIntervalSample
	var sampleMu sync.Mutex

	var loadLatMu sync.Mutex
	var loadLatSamples []float64
	var loadPingAttempted atomic.Int32
	var loadPingWG sync.WaitGroup
	var deadAborted atomic.Bool

	done := make(chan struct{})
	tickerDone := make(chan struct{})
	go func() {
		defer close(tickerDone)
		ticker := time.NewTicker(sampleInterval)
		defer ticker.Stop()
		prevBytes := int64(0)
		prevTime := startGlobal

		for {
			select {
			case now := <-ticker.C:
				curBytes := atomic.LoadInt64(&totalBytes)
				deltaBytes := curBytes - prevBytes
				dt := now.Sub(prevTime).Seconds()
				if dt > 0.05 {
					elapsed := now.Sub(startGlobal).Seconds()
					spd := (float64(deltaBytes) / 1024.0 / 1024.0) / dt
					cumSpd := (float64(curBytes) / 1024.0 / 1024.0) / elapsed
					isStall := (spd <= 0.01)

					sampleMu.Lock()
					intervals = append(intervals, SpeedIntervalSample{
						Timestamp:       now,
						DeltaBytes:      deltaBytes,
						DeltaDuration:   dt,
						IntervalSpeed:   spd,
						CumulativeSpeed: cumSpd,
						Elapsed:         elapsed,
						TotalBytes:      curBytes,
						IsStall:         isStall,
					})
					sampleCount := len(intervals)
					sampleMu.Unlock()

					prevBytes = curBytes
					prevTime = now

					// 在大流量下载进行到第 2 秒和第 5 秒时，并发实测满载延迟 (LoadLatency / Bufferbloat)
					if (sampleCount == 2 || sampleCount == 5) && sampleCount < duration {
						loadPingAttempted.Add(1)
						loadPingWG.Add(1)
						go func() {
							defer loadPingWG.Done()
							lat := TCPPing(target.IP, target.Port, 1000*time.Millisecond)
							if lat > 0 {
								loadLatMu.Lock()
								loadLatSamples = append(loadLatSamples, lat)
								loadLatMu.Unlock()
							}
						}()
					}

					if progressCallback != nil {
						shownElapsed := float64(sampleCount)
						progressCallback(LiveProgress{
							IP:       target.IP,
							Bytes:    curBytes,
							Speed:    cumSpd,
							Elapsed:  shownElapsed,
							Duration: float64(duration),
						})
					}

					// 已完整采满 duration 个 1 秒周期，立即结束当前节点下载流
					if sampleCount >= duration {
						cancel()
						return
					}

					// 仅当满 3 秒完全 0 字节（死连接）时才提前淘汰，有流量的节点一律跑满 8/8s
					if duration >= 4 && sampleCount >= 3 && curBytes == 0 {
						deadAborted.Store(true)
						cancel()
						return
					}
				}
			case <-reqCtx.Done():
				return
			case <-done:
				return
			}
		}
	}()

	bufPtr := downloadBufPool.Get().(*[]byte)
	buf := *bufPtr
	for {
		n, err := resp.Body.Read(buf)
		if n > 0 {
			atomic.AddInt64(&totalBytes, int64(n))
		}
		if err != nil {
			break
		}
	}
	downloadBufPool.Put(bufPtr)
	close(done)
	<-tickerDone
	loadPingWG.Wait()

	realTime := time.Since(startGlobal).Seconds()
	if realTime < 0.1 || deadAborted.Load() {
		return SpeedMetrics{}
	}

	finalBytes := atomic.LoadInt64(&totalBytes)
	sampleMu.Lock()
	if len(intervals) > 0 && len(intervals) < duration {
		lastIt := intervals[len(intervals)-1]
		remainDt := realTime - lastIt.Elapsed
		if remainDt >= 0.2 {
			remainBytes := finalBytes - lastIt.TotalBytes
			if remainBytes < 0 {
				remainBytes = 0
			}
			spd := (float64(remainBytes) / 1024.0 / 1024.0) / remainDt
			intervals = append(intervals, SpeedIntervalSample{
				Timestamp:       time.Now(),
				DeltaBytes:      remainBytes,
				DeltaDuration:   remainDt,
				IntervalSpeed:   spd,
				CumulativeSpeed: (float64(finalBytes) / 1024.0 / 1024.0) / realTime,
				Elapsed:         realTime,
				TotalBytes:      finalBytes,
				IsStall:         spd <= 0.01,
			})
		}
	} else if len(intervals) == 0 && realTime > 0.05 {
		spd := (float64(finalBytes) / 1024.0 / 1024.0) / realTime
		intervals = append(intervals, SpeedIntervalSample{
			Timestamp:       time.Now(),
			DeltaBytes:      finalBytes,
			DeltaDuration:   realTime,
			IntervalSpeed:   spd,
			CumulativeSpeed: spd,
			Elapsed:         realTime,
			TotalBytes:      finalBytes,
			IsStall:         spd <= 0.01,
		})
	}
	intervalsCopy := make([]SpeedIntervalSample, len(intervals))
	copy(intervalsCopy, intervals)
	sampleMu.Unlock()

	// TCP 慢启动（Slow-Start）去噪：若第 1 秒非断流但处于明显的窗口爬坡期，平滑其对稳态 P10/MinSpeed/CV 的失真影响
	if len(intervalsCopy) >= 4 && !intervalsCopy[0].IsStall && intervalsCopy[1].IntervalSpeed > 1.0 {
		if intervalsCopy[0].IntervalSpeed < intervalsCopy[1].IntervalSpeed*0.65 {
			intervalsCopy[0].IntervalSpeed = intervalsCopy[0].IntervalSpeed*0.30 + intervalsCopy[1].IntervalSpeed*0.70
		}
	}

	sm := ProcessIntervalSamples(intervalsCopy, finalBytes, realTime, tcpRTT, jitter, packetLoss)

	// 长连接后半程掉速检测（识别前几秒突发快、后半程被运营商 QoS 限速的假高速节点）
	if len(intervalsCopy) >= 5 {
		mid := (len(intervalsCopy) - 1) / 2
		if mid < 1 {
			mid = 1
		}
		var earlySum, lateSum float64
		earlyCnt, lateCnt := 0, 0
		for i := 1; i <= mid; i++ {
			earlySum += intervalsCopy[i].IntervalSpeed
			earlyCnt++
		}
		for i := mid + 1; i < len(intervalsCopy); i++ {
			lateSum += intervalsCopy[i].IntervalSpeed
			lateCnt++
		}
		if earlyCnt > 0 && lateCnt > 0 {
			earlyAvg := earlySum / float64(earlyCnt)
			lateAvg := lateSum / float64(lateCnt)
			if earlyAvg > 1.0 && lateAvg < earlyAvg*0.72 {
				decayRatio := (earlyAvg - lateAvg) / earlyAvg
				sm.Stability = math.Max(0, math.Round((sm.Stability-decayRatio*35.0)*10)/10)
			}
		}
	}

	// 汇总实测满载延迟 (LoadLatency)
	loadLatMu.Lock()
	if len(loadLatSamples) > 0 {
		var lSum float64
		for _, l := range loadLatSamples {
			lSum += l
		}
		sm.LoadLatency = math.Round((lSum/float64(len(loadLatSamples)))*10) / 10
	} else if loadPingAttempted.Load() > 0 && tcpRTT > 0 {
		// 满载期间连接探测全部超时，说明满载排队拥塞严重
		sm.LoadLatency = math.Round(math.Max(tcpRTT*3.0, 300.0)*10) / 10
	}
	loadLatMu.Unlock()

	return sm
}

func getRangeHostCount(r string) int64 {
	if !strings.Contains(r, "/") {
		ip := net.ParseIP(strings.TrimSpace(r))
		if ip == nil || ip.To4() == nil {
			return 0
		}
		return 1
	}
	_, ipNet, err := net.ParseCIDR(r)
	if err != nil || ipNet.IP.To4() == nil {
		return 0
	}
	ones, bits := ipNet.Mask.Size()
	hostBits := bits - ones
	if hostBits < 0 || hostBits > 32 {
		return 0
	}
	return int64(1) << uint(hostBits)
}

func enumerateCSubnets(cidr string) ([]uint32, *cidrInfo) {
	info := parseCIDRCached(cidr)
	if info == nil {
		return nil, nil
	}
	if info.hostBits <= 8 {
		return []uint32{info.baseIP}, info
	}
	numC := 1 << (info.hostBits - 8)
	subnets := make([]uint32, numC)
	for i := 0; i < numC; i++ {
		subnets[i] = info.baseIP + uint32(i<<8)
	}
	return subnets, info
}

func randHostInSubnet(subnetBase uint32, info *cidrInfo) string {
	var ip uint32
	if info.hostBits <= 2 {
		ip = subnetBase
	} else if info.hostBits <= 8 {
		offset := rand.Intn(info.maxHost) + 1
		ip = subnetBase + uint32(offset)
	} else {
		// Pick .1 .. .254 inside the /24 C-subnet
		offset := rand.Intn(254) + 1
		ip = subnetBase + uint32(offset)
	}
	var buf [4]byte
	binary.BigEndian.PutUint32(buf[:], ip)
	return net.IP(buf[:]).String()
}

// GenerateIPs generates candidate IPv4 addresses.
// When unique is true and maxScan <= 0 (or >= total C-subnets), it deterministically covers 100% of all /24 subnets.
func GenerateIPs(maxScan int, unique bool, ipFile string) []string {
	ranges := CloudflareIPv4Ranges
	if ipFile != "" {
		if content, err := os.ReadFile(ipFile); err == nil {
			lines := strings.Split(string(content), "\n")
			var fileRanges []string
			for _, line := range lines {
				line = strings.TrimSpace(line)
				if line != "" && !strings.HasPrefix(line, "#") {
					fileRanges = append(fileRanges, line)
				}
			}
			if len(fileRanges) > 0 {
				ranges = fileRanges
			}
		}
	}

	if unique {
		type cidrPool struct {
			info    *cidrInfo
			subnets []uint32
			weight  float64
		}
		var pools []*cidrPool
		var standaloneIPs []string
		seenStandalone := make(map[string]bool)
		totalCSubnets := 0

		for _, r := range ranges {
			r = strings.TrimSpace(r)
			if r == "" {
				continue
			}
			if !strings.Contains(r, "/") {
				ip := net.ParseIP(r)
				if ip != nil && ip.To4() != nil && !seenStandalone[r] {
					seenStandalone[r] = true
					standaloneIPs = append(standaloneIPs, ip.To4().String())
				}
				continue
			}
			subnets, info := enumerateCSubnets(r)
			if len(subnets) == 0 || info == nil {
				continue
			}
			rand.Shuffle(len(subnets), func(i, j int) { subnets[i], subnets[j] = subnets[j], subnets[i] })
			totalCSubnets += len(subnets)
			pools = append(pools, &cidrPool{
				info:    info,
				subnets: subnets,
				weight:  math.Sqrt(float64(len(subnets))),
			})
		}

		totalCapacity := len(standaloneIPs) + totalCSubnets
		if totalCapacity == 0 {
			return nil
		}

		// maxScan <= 0 means ALL /24 subnets
		if maxScan <= 0 || maxScan >= totalCapacity {
			seenC := make(map[uint32]bool, totalCapacity)
			ips := make([]string, 0, totalCapacity)
			for _, ipStr := range standaloneIPs {
				if parsed := net.ParseIP(ipStr).To4(); parsed != nil {
					cKey := binary.BigEndian.Uint32(parsed) & 0xFFFFFF00
					seenC[cKey] = true
					ips = append(ips, ipStr)
				}
			}
			for _, p := range pools {
				for _, sn := range p.subnets {
					cKey := sn & 0xFFFFFF00
					if p.info.hostBits >= 8 && seenC[cKey] {
						continue
					}
					seenC[cKey] = true
					ips = append(ips, randHostInSubnet(sn, p.info))
				}
			}
			rand.Shuffle(len(ips), func(i, j int) { ips[i], ips[j] = ips[j], ips[i] })
			return ips
		}

		seenC := make(map[uint32]bool, maxScan)
		ips := make([]string, 0, maxScan)

		for _, ipStr := range standaloneIPs {
			if len(ips) >= maxScan {
				break
			}
			if parsed := net.ParseIP(ipStr).To4(); parsed != nil {
				seenC[binary.BigEndian.Uint32(parsed)&0xFFFFFF00] = true
			}
			ips = append(ips, ipStr)
		}

		// Step 1: guarantee at least one /24 sample per CIDR pool
		popFromPool := func(p *cidrPool) (string, bool) {
			for len(p.subnets) > 0 {
				sn := p.subnets[len(p.subnets)-1]
				p.subnets = p.subnets[:len(p.subnets)-1]
				cKey := sn & 0xFFFFFF00
				if p.info.hostBits >= 8 && seenC[cKey] {
					continue
				}
				seenC[cKey] = true
				return randHostInSubnet(sn, p.info), true
			}
			return "", false
		}

		for _, p := range pools {
			if len(ips) >= maxScan {
				break
			}
			if ip, ok := popFromPool(p); ok {
				ips = append(ips, ip)
			}
		}

		// Step 2: collision-free weighted sampling without replacement from active pools
		active := make([]*cidrPool, 0, len(pools))
		var totalWeight float64
		for _, p := range pools {
			if len(p.subnets) > 0 {
				active = append(active, p)
				totalWeight += p.weight
			}
		}

		for len(ips) < maxScan && len(active) > 0 {
			pickIdx := len(active) - 1
			if totalWeight > 0 {
				val := rand.Float64() * totalWeight
				var running float64
				for idx, p := range active {
					running += p.weight
					if val < running {
						pickIdx = idx
						break
					}
				}
			} else {
				pickIdx = rand.Intn(len(active))
			}

			p := active[pickIdx]
			if ip, ok := popFromPool(p); ok {
				ips = append(ips, ip)
			}
			if len(p.subnets) == 0 {
				totalWeight -= p.weight
				active[pickIdx] = active[len(active)-1]
				active = active[:len(active)-1]
			}
		}

		rand.Shuffle(len(ips), func(i, j int) { ips[i], ips[j] = ips[j], ips[i] })
		return ips
	}

	if maxScan <= 0 {
		maxScan = 800
	}

	// Non-unique proportional sampling
	var totalWeight float64
	rangeWeights := make([]float64, len(ranges))
	validFlags := make([]bool, len(ranges))
	for i, r := range ranges {
		h := getRangeHostCount(r)
		if h <= 0 {
			continue
		}
		validFlags[i] = true
		cSubnets := math.Max(1.0, float64(h)/256.0)
		w := math.Sqrt(cSubnets)
		rangeWeights[i] = w
		totalWeight += w
	}
	if totalWeight <= 0 {
		return nil
	}

	var ips []string
	for i, r := range ranges {
		if !validFlags[i] {
			continue
		}
		w := rangeWeights[i]
		count := int((w / totalWeight) * float64(maxScan))
		if count < 1 {
			count = 1
		}
		if !strings.Contains(r, "/") {
			ips = append(ips, r)
			continue
		}
		for j := 0; j < count; j++ {
			ip := randIPFromCIDR(r)
			if ip != "" {
				ips = append(ips, ip)
			}
		}
	}
	rand.Shuffle(len(ips), func(i, j int) { ips[i], ips[j] = ips[j], ips[i] })
	if len(ips) > maxScan {
		ips = ips[:maxScan]
	}
	return ips
}

func TCPPing(ip string, port int, timeout time.Duration) float64 {
	start := time.Now()
	conn, err := net.DialTimeout("tcp", net.JoinHostPort(ip, fmt.Sprintf("%d", port)), timeout)
	if err != nil {
		return 0
	}
	conn.Close()
	lat := float64(time.Since(start).Microseconds()) / 1000.0
	if lat <= 0 {
		return 0.001
	}
	return lat
}

// measureTCPPingStats executes count TCP pings and returns average latency, jitter, packet loss, and whether minSuccess was met.
func measureTCPPingStats(ctx context.Context, ip string, port, count, minSuccess, maxFailures int, timeout time.Duration) (avgLat, jitter, loss float64, ok bool) {
	if count <= 0 {
		count = 3
	}
	if minSuccess <= 0 {
		minSuccess = 1
	}
	lats := make([]float64, 0, count)
	failures := 0
	for i := 0; i < count; i++ {
		if ctx != nil && ctx.Err() != nil {
			return 0, 0, 1.0, false
		}
		lat := TCPPing(ip, port, timeout)
		if lat > 0 {
			lats = append(lats, lat)
		} else {
			failures++
			if maxFailures > 0 && failures >= maxFailures {
				break
			}
		}
		if i < count-1 {
			select {
			case <-time.After(15 * time.Millisecond):
			case <-ctx.Done():
				return 0, 0, 1.0, false
			}
		}
	}
	if len(lats) < minSuccess {
		return 0, 0, float64(count-len(lats)) / float64(count), false
	}
	var sum float64
	for _, l := range lats {
		sum += l
	}
	avgLat = sum / float64(len(lats))
	if len(lats) > 1 {
		var variance float64
		for _, l := range lats {
			diff := l - avgLat
			variance += diff * diff
		}
		jitter = math.Sqrt(variance / float64(len(lats)))
	}
	loss = float64(count-len(lats)) / float64(count)
	return avgLat, jitter, loss, true
}

// WSSHandshakeResult records the outcome and diagnostics of a GOWAY WSS compatibility check.
type WSSHandshakeResult struct {
	Success      bool    `json:"success"`
	TCPSuccess   bool    `json:"tcp_success"`
	TLSHandshake bool    `json:"tls_handshake"`
	HTTPStatus   int     `json:"http_status"`
	Latency      float64 `json:"latency"`
	Colo         string  `json:"colo,omitempty"`
	ErrorStage   string  `json:"error_stage,omitempty"`
	ErrorMessage string  `json:"error_message,omitempty"`
	SNISent      string  `json:"sni_sent,omitempty"`
	HostSent     string  `json:"host_sent,omitempty"`
	PathSent     string  `json:"path_sent,omitempty"`
}

// WSSHandshakeCheckDetailed validates GOWAY WSS compatibility stage by stage:
// Config check -> TCP connect -> TLS handshake with SNI -> HTTP Upgrade with Host/Path -> HTTP 101 Switching Protocols.
func WSSHandshakeCheckDetailed(ip string, port int, sni string, host string, path string, timeout time.Duration) WSSHandshakeResult {
	return WSSHandshakeCheckContext(context.Background(), ip, port, sni, host, path, timeout)
}

// WSSHandshakeCheckContext validates GOWAY WSS compatibility stage by stage while respecting ctx cancellation.
func WSSHandshakeCheckContext(ctx context.Context, ip string, port int, sni string, host string, path string, timeout time.Duration) WSSHandshakeResult {
	res := WSSHandshakeResult{
		SNISent:  sni,
		HostSent: host,
		PathSent: path,
	}

	if ip == "" || port <= 0 || port > 65535 || strings.TrimSpace(sni) == "" || strings.TrimSpace(host) == "" || strings.TrimSpace(path) == "" {
		res.ErrorStage = "config"
		res.ErrorMessage = "missing required WSS parameter"
		return res
	}

	if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}
	res.PathSent = path

	if timeout <= 0 {
		timeout = 2500 * time.Millisecond
	}
	if ctx == nil {
		ctx = context.Background()
	}

	start := time.Now()
	deadline := start.Add(timeout)
	if ctxDeadline, ok := ctx.Deadline(); ok && ctxDeadline.Before(deadline) {
		deadline = ctxDeadline
	}

	addr := net.JoinHostPort(ip, strconv.Itoa(port))
	dialer := net.Dialer{Timeout: timeout}
	conn, err := dialer.DialContext(ctx, "tcp", addr)
	if err != nil {
		res.ErrorStage = "tcp"
		res.ErrorMessage = err.Error()
		return res
	}
	defer conn.Close()
	res.TCPSuccess = true

	tlsConf := &tls.Config{
		InsecureSkipVerify: true,
		ServerName:         sni,
		NextProtos:         []string{"http/1.1"},
	}
	tlsConn := tls.Client(conn, tlsConf)
	if err := tlsConn.SetDeadline(deadline); err != nil {
		res.ErrorStage = "tls"
		res.ErrorMessage = err.Error()
		return res
	}
	if err := tlsConn.HandshakeContext(ctx); err != nil {
		res.ErrorStage = "tls"
		res.ErrorMessage = err.Error()
		return res
	}
	res.TLSHandshake = true

	req := fmt.Sprintf("GET %s HTTP/1.1\r\n", path) +
		fmt.Sprintf("Host: %s\r\n", host) +
		"Upgrade: websocket\r\n" +
		"Connection: Upgrade\r\n" +
		"Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n" +
		"Sec-WebSocket-Version: 13\r\n" +
		"User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36\r\n" +
		"\r\n"

	if _, err := tlsConn.Write([]byte(req)); err != nil {
		res.ErrorStage = "http"
		res.ErrorMessage = fmt.Sprintf("failed to send HTTP upgrade request: %v", err)
		return res
	}

	reader := bufio.NewReader(tlsConn)
	statusLine, err := reader.ReadString('\n')
	if err != nil {
		res.ErrorStage = "http"
		res.ErrorMessage = fmt.Sprintf("failed to read HTTP status line: %v", err)
		return res
	}

	res.Latency = float64(time.Since(start).Microseconds()) / 1000.0
	if res.Latency <= 0 {
		res.Latency = 0.001
	}

	trimmed := strings.TrimRight(statusLine, "\r\n")
	parts := strings.SplitN(trimmed, " ", 3)
	if len(parts) < 2 {
		res.ErrorStage = "status"
		res.ErrorMessage = fmt.Sprintf("malformed HTTP status line: %q", trimmed)
		return res
	}

	statusCode, err := strconv.Atoi(parts[1])
	if err != nil {
		res.ErrorStage = "status"
		res.ErrorMessage = fmt.Sprintf("invalid HTTP status code %q in status line: %q", parts[1], trimmed)
		return res
	}
	res.HTTPStatus = statusCode

	if statusCode == 101 {
		res.Success = true
		// 顺带从缓冲区读取响应头中的 cf-ray 机房代码，零额外网络耗时
		for i := 0; i < 20; i++ {
			hdrLine, hErr := reader.ReadString('\n')
			if hErr != nil || hdrLine == "\r\n" || hdrLine == "\n" {
				break
			}
			if strings.HasPrefix(strings.ToLower(hdrLine), "cf-ray:") {
				val := strings.TrimSpace(hdrLine[7:])
				if cParts := strings.Split(val, "-"); len(cParts) >= 2 {
					res.Colo = strings.ToUpper(cParts[len(cParts)-1])
					if res.Colo != "" {
						ipColoCache.Store(ip, res.Colo)
					}
				}
			}
		}
		return res
	}

	res.ErrorStage = "status"
	res.ErrorMessage = fmt.Sprintf("expected HTTP 101, got status %d (%s)", statusCode, trimmed)
	return res
}

// MeasureWSSStability runs multiple zero-bandwidth GOWAY WSS 101 handshake probes
// to measure end-to-end CF-edge -> VPS backhaul latency, jitter, and handshake success rate.
func MeasureWSSStability(ctx context.Context, ip string, port int, sni, host, path string, rounds int, timeout time.Duration) (avgLatency float64, jitter float64, successRate float64, colo string) {
	if rounds <= 0 {
		rounds = 3
	}
	if timeout <= 0 {
		timeout = 2200 * time.Millisecond
	}
	if ctx == nil {
		ctx = context.Background()
	}
	var latencies []float64
	okCount := 0
	for i := 0; i < rounds; i++ {
		if ctx.Err() != nil {
			break
		}
		res := WSSHandshakeCheckContext(ctx, ip, port, sni, host, path, timeout)
		if res.Colo != "" && colo == "" {
			colo = res.Colo
		}
		if res.Success && res.HTTPStatus == 101 {
			okCount++
			latencies = append(latencies, res.Latency)
		}
		if i < rounds-1 {
			select {
			case <-ctx.Done():
				break
			case <-time.After(30 * time.Millisecond):
			}
		}
	}
	successRate = float64(okCount) / float64(rounds)
	if len(latencies) == 0 {
		return 0, 0, successRate, colo
	}
	var sum float64
	for _, l := range latencies {
		sum += l
	}
	avgLatency = sum / float64(len(latencies))
	if len(latencies) > 1 {
		var variance float64
		for _, l := range latencies {
			d := l - avgLatency
			variance += d * d
		}
		jitter = math.Sqrt(variance / float64(len(latencies)))
	}
	return avgLatency, jitter, successRate, colo
}

// HTTPSConnectivityCheck performs low-bandwidth L2 HTTPS/TLS reachability verification,
// measuring TTFB, validating HTTP status code (< 400), and extracting CDN Colo.
func HTTPSConnectivityCheck(ctx context.Context, ip string, port int, sni string, host string, testURL string, timeout time.Duration) (bool, float64, int, string, error) {
	if timeout <= 0 {
		timeout = 2500 * time.Millisecond
	}
	reqCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	// 对官方测速地址使用极轻量的 __down?bytes=0 探活，避免下载大包或 HEAD 405 二次握手
	probeURL := testURL
	if strings.Contains(testURL, "speed.cloudflare.com/__down") {
		probeURL = "https://speed.cloudflare.com/__down?bytes=0"
	}

	parsedURL, err := url.Parse(probeURL)
	if err != nil {
		return false, 0, 0, "", fmt.Errorf("invalid test URL: %w", err)
	}
	if host == "" {
		host = parsedURL.Hostname()
	}
	if sni == "" {
		sni = host
	}

	client := makeHTTPClient(ip, port, sni)
	if tr, ok := client.Transport.(*http.Transport); ok {
		defer tr.CloseIdleConnections()
	}

	req, err := http.NewRequestWithContext(reqCtx, "GET", probeURL, nil)
	if err != nil {
		return false, 0, 0, "", err
	}
	req.Host = host
	req.Header.Set("Connection", "close")

	if strings.Contains(probeURL, "speed.cloudflare.com") {
		setCFHeaders(req)
	} else {
		scheme := parsedURL.Scheme
		if scheme == "" {
			scheme = "https"
		}
		baseURL := scheme + "://" + host
		if parsedURL.Port() != "" {
			baseURL += ":" + parsedURL.Port()
		}
		setCFHeadersForURL(req, baseURL)
		req.Header.Set("Range", "bytes=0-1023")
	}

	t0 := time.Now()
	resp, err := client.Do(req)
	if err != nil {
		return false, 0, 0, "", err
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1024))

	ttfb := float64(time.Since(t0).Microseconds()) / 1000.0
	statusCode := resp.StatusCode
	colo := ""

	cfRay := resp.Header.Get("cf-ray")
	if cfRay != "" {
		parts := strings.Split(cfRay, "-")
		if len(parts) >= 2 {
			colo = strings.ToUpper(parts[len(parts)-1])
			if colo != "" {
				ipColoCache.Store(ip, colo)
			}
		}
	}

	// 严格拦截 403 Forbidden、400、429、5xx 等所有异常或拦截状态码（仅放行 2xx/3xx）
	if statusCode >= 400 || statusCode < 200 {
		return false, ttfb, statusCode, colo, fmt.Errorf("HTTP %d", statusCode)
	}

	return true, ttfb, statusCode, colo, nil
}

var coloRe = regexp.MustCompile(`colo=([A-Z]+)`)

var sharedTLSConfig = &tls.Config{InsecureSkipVerify: true}

func makeTLSConfig(sni string) *tls.Config {
	if sni == "" {
		return sharedTLSConfig
	}
	return &tls.Config{
		InsecureSkipVerify: true,
		ServerName:         sni,
	}
}

var downloadBufPool = sync.Pool{
	New: func() interface{} {
		b := make([]byte, 262144) // 256KB
		return &b
	},
}

func init() {
	for _, cidr := range CloudflareIPv4Ranges {
		parseCIDRCached(cidr)
	}
}

// makeHTTPClient creates an HTTP client that force-dials to the specified CF IP.
func makeHTTPClient(ip string, port int, sni string) *http.Client {
	addr := net.JoinHostPort(ip, strconv.Itoa(port))
	dialer := &net.Dialer{
		Timeout:   3 * time.Second,
		KeepAlive: 30 * time.Second,
	}
	tr := &http.Transport{
		TLSClientConfig:     makeTLSConfig(sni),
		TLSHandshakeTimeout: 3 * time.Second,
		MaxIdleConnsPerHost: 4,
		DialContext: func(ctx context.Context, network, _ string) (net.Conn, error) {
			return dialer.DialContext(ctx, "tcp", addr)
		},
	}
	return &http.Client{Transport: tr}
}

func setCFHeaders(req *http.Request) {
	setCFHeadersForURL(req, "https://speed.cloudflare.com")
}

func setCFHeadersForURL(req *http.Request, baseURL string) {
	req.Header.Set("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36")
	req.Header.Set("Accept", "*/*")
	req.Header.Set("Accept-Language", "zh-CN,zh;q=0.9,en;q=0.8")
	req.Header.Set("Referer", baseURL+"/")
	req.Header.Set("Origin", baseURL)
	req.Header.Set("Sec-Ch-Ua", `"Not_A Brand";v="8", "Chromium";v="120", "Google Chrome";v="120"`)
	req.Header.Set("Sec-Ch-Ua-Mobile", "?0")
	req.Header.Set("Sec-Ch-Ua-Platform", `"Windows"`)
	req.Header.Set("Sec-Fetch-Dest", "empty")
	req.Header.Set("Sec-Fetch-Mode", "cors")
	req.Header.Set("Sec-Fetch-Site", "same-origin")
}

func newCFRequestWithContext(ctx context.Context, method, urlStr string) (*http.Request, error) {
	req, err := http.NewRequestWithContext(ctx, method, urlStr, nil)
	if err != nil {
		return nil, err
	}
	setCFHeaders(req)
	return req, nil
}

func GetColo(ip string, port int) string {
	return GetColoWithContext(context.Background(), ip, port)
}

func GetColoWithContext(ctx context.Context, ip string, port int) string {
	client := makeHTTPClient(ip, port, "")
	if tr, ok := client.Transport.(*http.Transport); ok {
		defer tr.CloseIdleConnections()
	}
	reqCtx, cancel := context.WithTimeout(ctx, 4*time.Second)
	defer cancel()

	req, err := newCFRequestWithContext(reqCtx, "GET", "https://speed.cloudflare.com/cdn-cgi/trace")
	if err != nil {
		return "ERR"
	}

	resp, err := client.Do(req)
	if err != nil {
		return "ERR"
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "UNK"
	}
	if match := coloRe.FindSubmatch(body); match != nil {
		return string(match[1])
	}
	return "UNK"
}

// LiveProgress holds real-time download progress for a single IP.
type LiveProgress struct {
	IP       string  `json:"ip"`
	Bytes    int64   `json:"bytes"`
	Speed    float64 `json:"speed"` // MB/s
	Elapsed  float64 `json:"elapsed"`
	Duration float64 `json:"duration"`
}

// LightweightHTTPProbeResult contains the outcome of an L3 low-bandwidth HTTP/HTTPS probe.
type LightweightHTTPProbeResult struct {
	Success    bool    `json:"success"`
	StatusCode int     `json:"status_code"`
	TTFB       float64 `json:"ttfb_ms"`
	Speed      float64 `json:"speed_mb"`
	BytesRead  int64   `json:"bytes_read"`
	Colo       string  `json:"colo"`
	Error      string  `json:"error,omitempty"`
}

// LightweightHTTPProbeTarget performs a minimal-overhead HTTP check driven strictly by ResolvedProbeTarget.
func LightweightHTTPProbeTarget(ctx context.Context, target ResolvedProbeTarget) LightweightHTTPProbeResult {
	res := LightweightHTTPProbeResult{}
	client := makeHTTPClient(target.IP, target.Port, target.SNI)
	if tr, ok := client.Transport.(*http.Transport); ok {
		defer tr.CloseIdleConnections()
	}

	// For Cloudflare official speed test, request a small 100KB chunk instead of 500MB
	probeURL := target.URL
	if strings.Contains(target.URL, "speed.cloudflare.com/__down") {
		probeURL = "https://speed.cloudflare.com/__down?bytes=100000"
	}

	reqCtx, cancel := context.WithTimeout(ctx, 4*time.Second)
	defer cancel()

	req, err := http.NewRequestWithContext(reqCtx, "GET", probeURL, nil)
	if err != nil {
		res.Error = err.Error()
		return res
	}
	req.Host = target.Host
	req.Header.Set("Connection", "close")

	if strings.Contains(target.URL, "speed.cloudflare.com") {
		setCFHeaders(req)
	} else {
		parsedURL, err := url.Parse(target.URL)
		scheme := target.Protocol
		if scheme == "" && err == nil && parsedURL.Scheme != "" {
			scheme = parsedURL.Scheme
		}
		if scheme == "" {
			scheme = "https"
		}
		baseURL := scheme + "://" + target.Host
		setCFHeadersForURL(req, baseURL)
		req.Header.Set("Range", "bytes=0-102399")
	}

	t0 := time.Now()
	resp, err := client.Do(req)
	if err != nil {
		res.Error = err.Error()
		return res
	}
	defer resp.Body.Close()

	res.TTFB = float64(time.Since(t0).Microseconds()) / 1000.0
	res.StatusCode = resp.StatusCode

	// Extract Colo from cf-ray header if present
	cfRay := resp.Header.Get("cf-ray")
	if cfRay != "" {
		parts := strings.Split(cfRay, "-")
		if len(parts) >= 2 {
			res.Colo = strings.ToUpper(parts[len(parts)-1])
		}
	}

	if resp.StatusCode >= 400 {
		res.Error = fmt.Sprintf("HTTP %d", resp.StatusCode)
		return res
	}

	// Read small body limited to 256KB reusing downloadBufPool
	lr := io.LimitReader(resp.Body, 256*1024)
	bufPtr := downloadBufPool.Get().(*[]byte)
	buf := (*bufPtr)[:32*1024]
	var bytesRead int64
	for {
		n, rErr := lr.Read(buf)
		if n > 0 {
			bytesRead += int64(n)
		}
		if rErr != nil {
			break
		}
	}
	downloadBufPool.Put(bufPtr)
	totalDuration := time.Since(t0).Seconds()
	res.BytesRead = bytesRead
	if totalDuration > 0.001 {
		res.Speed = (float64(bytesRead) / 1024.0 / 1024.0) / totalDuration
	}
	res.Success = true
	return res
}

// ============================================================================
// SECTION: LAYERED PROBING & SCHEDULER (from probe.go)
// ============================================================================
type ProbeProfileType string

const (
	ProfileCFST     ProbeProfileType = "CFST"
	ProfileGOWAYWSS ProbeProfileType = "GOWAY-WSS"
	ProfileCustom   ProbeProfileType = "CUSTOM"
)

// ProbeProfile defines target parameters for versatile network quality testing (CFST, GOWAY-WSS, CUSTOM).
type ProbeProfile struct {
	Type     ProbeProfileType `json:"type"`
	IP       string           `json:"ip,omitempty"`
	Port     int              `json:"port"`
	SNI      string           `json:"sni"`
	Host     string           `json:"host"`
	Path     string           `json:"path"`
	TestURL  string           `json:"test_url"`
	Protocol string           `json:"protocol"` // e.g. "https", "wss"
}

// NewProfileCFST returns Cloudflare Official probe profile (default).
func NewProfileCFST() ProbeProfile {
	return ProbeProfile{
		Type:     ProfileCFST,
		Port:     443,
		SNI:      "speed.cloudflare.com",
		Host:     "speed.cloudflare.com",
		Path:     "/__down",
		TestURL:  "https://speed.cloudflare.com/__down?bytes=1000000000",
		Protocol: "https",
	}
}

// NewProfileGOWAYWSS returns GOWAY WSS Handshake probe profile.
func NewProfileGOWAYWSS(host, path, sni string, port int) ProbeProfile {
	if port <= 0 {
		port = 443
	}
	if path == "" {
		path = "/pyway"
	}
	return ProbeProfile{
		Type:     ProfileGOWAYWSS,
		Port:     port,
		SNI:      sni,
		Host:     host,
		Path:     path,
		TestURL:  "https://speed.cloudflare.com/__down?bytes=1000000000",
		Protocol: "wss",
	}
}

// NewProfileCustom returns custom user-configured VPS URL probe profile.
func NewProfileCustom(customURL, sni string, port int) ProbeProfile {
	path := "/"
	protocol := "https"
	hostname := sni
	if customURL != "" {
		if u, err := url.Parse(customURL); err == nil {
			if u.Hostname() != "" {
				hostname = u.Hostname()
			}
			if u.Port() != "" {
				if p, err := strconv.Atoi(u.Port()); err == nil && p > 0 {
					port = p
				}
			}
			if u.RequestURI() != "" {
				path = u.RequestURI()
			}
			if u.Scheme != "" {
				protocol = u.Scheme
			}
		}
	}
	if port <= 0 {
		if protocol == "http" {
			port = 80
		} else {
			port = 443
		}
	}
	if sni == "" {
		sni = hostname
	}
	if strings.Contains(sni, ":") {
		sni = strings.Split(sni, ":")[0]
	}

	host := hostname
	if port != 443 && port != 80 && hostname != "" && !strings.Contains(host, ":") {
		host = fmt.Sprintf("%s:%d", hostname, port)
	}

	return ProbeProfile{
		Type:     ProfileCustom,
		Port:     port,
		SNI:      sni,
		Host:     host,
		Path:     path,
		TestURL:  customURL,
		Protocol: protocol,
	}
}

// ResolvedProbeTarget defines a normalized and unified target descriptor
// ensuring all probe layers (L1~L4) execute with strictly consistent parameters.
type ResolvedProbeTarget struct {
	ProfileType ProbeProfileType `json:"profile_type"`
	IP          string           `json:"ip"`
	Port        int              `json:"port"`
	SNI         string           `json:"sni"`
	Host        string           `json:"host"`
	Path        string           `json:"path"`
	URL         string           `json:"url"`
	Protocol    string           `json:"protocol"`
}

// NormalizeProbeConfig reconciles cfg.Profile as the single source of truth,
// ensuring legacy fields (URL, SNI, WSSHost, Port) stay in sync and isolating WSS in CFST mode.
func NormalizeProbeConfig(cfg *ProbeConfig) {
	if cfg == nil {
		return
	}

	if cfg.Profile.Type == "" {
		cfg.Profile = NewProfileCFST()
	}

	switch cfg.Profile.Type {
	case ProfileCFST:
		if cfg.Profile.TestURL == "" {
			cfg.Profile.TestURL = "https://speed.cloudflare.com/__down?bytes=1000000000"
		}
		if cfg.Profile.SNI == "" {
			cfg.Profile.SNI = "speed.cloudflare.com"
		}
		if cfg.Profile.Host == "" {
			cfg.Profile.Host = cfg.Profile.SNI
		}
		if cfg.Profile.Path == "" {
			cfg.Profile.Path = "/__down"
		}
		if cfg.Profile.Protocol == "" {
			cfg.Profile.Protocol = "https"
		}
		if cfg.Profile.Port <= 0 {
			cfg.Profile.Port = 443
		}
		// In CFST mode, WSSHost must NOT participate
		cfg.WSSHost = ""

	case ProfileGOWAYWSS:
		if cfg.Profile.Path == "" {
			cfg.Profile.Path = "/pyway"
		}
		if cfg.Profile.Protocol == "" {
			cfg.Profile.Protocol = "wss"
		}
		if cfg.Profile.Port <= 0 {
			cfg.Profile.Port = 443
		}
		if cfg.Profile.TestURL == "" {
			cfg.Profile.TestURL = "https://speed.cloudflare.com/__down?bytes=1000000000"
		}
		if cfg.Profile.SNI == "" {
			cfg.Profile.SNI = cfg.Profile.Host
		}
		if cfg.Profile.Host == "" {
			cfg.Profile.Host = cfg.Profile.SNI
		}
		cfg.WSSHost = cfg.Profile.Host

	case ProfileCustom:
		if cfg.Profile.TestURL != "" {
			if u, err := url.Parse(cfg.Profile.TestURL); err == nil && u.Hostname() != "" {
				if u.Port() != "" {
					if p, err := strconv.Atoi(u.Port()); err == nil && p > 0 {
						cfg.Profile.Port = p
					}
				}
				if cfg.Profile.Host == "" {
					cfg.Profile.Host = u.Hostname()
				}
				if cfg.Profile.SNI == "" {
					cfg.Profile.SNI = u.Hostname()
				}
				if cfg.Profile.Path == "" {
					cfg.Profile.Path = u.RequestURI()
				}
				if cfg.Profile.Protocol == "" && u.Scheme != "" {
					cfg.Profile.Protocol = u.Scheme
				}
			}
		}
		if cfg.Profile.Port <= 0 {
			if cfg.Profile.Protocol == "http" {
				cfg.Profile.Port = 80
			} else {
				cfg.Profile.Port = 443
			}
		}
		if cfg.Profile.Protocol == "" {
			cfg.Profile.Protocol = "https"
		}
		if cfg.Profile.Path == "" {
			cfg.Profile.Path = "/"
		}
		if strings.Contains(cfg.Profile.SNI, ":") {
			cfg.Profile.SNI = strings.Split(cfg.Profile.SNI, ":")[0]
		}
		if cfg.Profile.Port != 443 && cfg.Profile.Port != 80 && cfg.Profile.Host != "" && !strings.Contains(cfg.Profile.Host, ":") {
			cfg.Profile.Host = fmt.Sprintf("%s:%d", cfg.Profile.Host, cfg.Profile.Port)
		}
		if cfg.Profile.Protocol == "wss" {
			cfg.WSSHost = cfg.Profile.Host
		} else {
			cfg.WSSHost = ""
		}
	}

	// Synchronize legacy fields from Profile (Profile is the single source of truth!)
	cfg.URL = cfg.Profile.TestURL
	cfg.SNI = cfg.Profile.SNI
	cfg.Port = cfg.Profile.Port

	if cfg.L3ProbeCycle < 1 {
		cfg.L3ProbeCycle = 3
	}
	if cfg.FullSpeedCycle < 1 {
		cfg.FullSpeedCycle = 60
	}
	cfg.SpeedTestCycle = cfg.FullSpeedCycle
	if cfg.MaxSpeedTests < 1 {
		cfg.MaxSpeedTests = 1
	}
	if cfg.MaxConcurrent < 1 {
		cfg.MaxConcurrent = 2
	}
	if cfg.DiscoveryInterval <= 0 {
		cfg.DiscoveryInterval = 60 * time.Minute
	}
	if cfg.DiscoveryScanCount <= 0 {
		cfg.DiscoveryScanCount = 200
	}
}

// ResolveProbeTarget returns a ResolvedProbeTarget for an IP/port based strictly on cfg.Profile.
func ResolveProbeTarget(cfg ProbeConfig, ip string, port int) ResolvedProbeTarget {
	NormalizeProbeConfig(&cfg)
	targetPort := port
	if cfg.Profile.Type == ProfileGOWAYWSS && cfg.Profile.Port > 0 {
		targetPort = cfg.Profile.Port
	} else if targetPort <= 0 {
		targetPort = cfg.Profile.Port
	}
	if targetPort <= 0 {
		targetPort = 443
	}

	host := cfg.Profile.Host
	if cfg.Profile.Type == ProfileCustom {
		if targetPort != 443 && targetPort != 80 && host != "" && !strings.Contains(host, ":") {
			host = fmt.Sprintf("%s:%d", host, targetPort)
		}
	}

	sni := cfg.Profile.SNI
	if strings.Contains(sni, ":") {
		sni = strings.Split(sni, ":")[0]
	}

	return ResolvedProbeTarget{
		ProfileType: cfg.Profile.Type,
		IP:          ip,
		Port:        targetPort,
		SNI:         sni,
		Host:        host,
		Path:        cfg.Profile.Path,
		URL:         cfg.Profile.TestURL,
		Protocol:    cfg.Profile.Protocol,
	}
}

// ResolveSpeedTargetForProbe returns the ResolvedProbeTarget for L3/L4 throughput probing.
// When probing GOWAY-WSS (or WSS without a custom downloadable file URL) or using the built-in
// speed.cloudflare.com URL, SNI/Host/URL are switched to Cloudflare's speed-test domain so
// HTTP downloads never hit the user's VPS domain (which has no download file and would 403/404).
func ResolveSpeedTargetForProbe(cfg ProbeConfig, ip string, port int) ResolvedProbeTarget {
	NormalizeProbeConfig(&cfg)
	prof := cfg.Profile
	if prof.Type == ProfileGOWAYWSS || (prof.Type == ProfileCustom && strings.EqualFold(prof.Protocol, "wss")) || !isCustomURL(prof.TestURL) {
		cfProf := NewProfileCFST()
		if port > 0 {
			cfProf.Port = port
		} else if prof.Port > 0 {
			cfProf.Port = prof.Port
		}
		return ResolveProbeTarget(ProbeConfig{Profile: cfProf}, ip, cfProf.Port)
	}
	return ResolveProbeTarget(cfg, ip, port)
}

// ProbeConfig holds parameters controlling tiered background probing.
type ProbeConfig struct {
	Profile            ProbeProfile  `json:"profile"`
	ActiveInterval     time.Duration `json:"active_interval"`      // High frequency for active routes
	StandbyInterval    time.Duration `json:"standby_interval"`     // Medium frequency for standby routes
	CandidateInterval  time.Duration `json:"candidate_interval"`   // Low frequency for candidate pool
	FailedInterval     time.Duration `json:"failed_interval"`      // Periodic recovery checks for failed routes
	MaxConcurrent      int           `json:"max_concurrent"`       // Concurrency limit for background ping/wss
	MaxSpeedTests      int           `json:"max_speed_tests"`      // Strict limit (usually 1) for concurrent speed tests
	QuickDuration      int           `json:"quick_duration"`       // Duration in seconds for L3 quick speed test
	FullDuration       int           `json:"full_duration"`        // Duration in seconds for L4 full speed test
	L3ProbeCycle       int           `json:"l3_probe_cycle"`       // Lightweight HTTP check every N cycles (e.g. 3)
	FullSpeedCycle     int           `json:"full_speed_cycle"`     // Full speed test calibration cycle (e.g. 60)
	SpeedTestCycle     int           `json:"speed_test_cycle"`     // Legacy alias for FullSpeedCycle
	DiscoveryEnabled   bool          `json:"discovery_enabled"`    // Periodic background Cloudflare IP discovery
	DiscoveryInterval  time.Duration `json:"discovery_interval"`   // Interval between discovery passes (default 60m)
	DiscoveryScanCount int           `json:"discovery_scan_count"` // Number of random IPs scanned per pass (default 200)
	IPFile             string        `json:"ip_file,omitempty"`
	WSSHost            string        `json:"wss_host"`
	SNI                string        `json:"sni"`
	URL                string        `json:"url"`
	Port               int           `json:"port"`
}

func DefaultProbeConfig() ProbeConfig {
	prof := NewProfileCFST()
	cfg := ProbeConfig{
		Profile:            prof,
		ActiveInterval:     10 * time.Second,
		StandbyInterval:    30 * time.Second,
		CandidateInterval:  180 * time.Second,
		FailedInterval:     60 * time.Second,
		MaxConcurrent:      4,
		MaxSpeedTests:      1,
		QuickDuration:      3,
		FullDuration:       10,
		L3ProbeCycle:       3,  // L3 lightweight 100KB probe every 3 cycles (~30s on Active)
		FullSpeedCycle:     60, // L4 full speed calibration every 60 cycles (~10m on Active)
		SpeedTestCycle:     60,
		DiscoveryEnabled:   true,
		DiscoveryInterval:  60 * time.Minute,
		DiscoveryScanCount: 200,
		WSSHost:            "", // isolated from CFST mode!
		SNI:                prof.SNI,
		URL:                prof.TestURL,
		Port:               prof.Port,
	}
	NormalizeProbeConfig(&cfg)
	return cfg
}

// LayeredProbeResult contains metrics produced by a multi-layer probe pass.
type LayeredProbeResult struct {
	Success              bool
	RTT                  float64
	PacketLoss           float64
	Jitter               float64
	HandshakeSuccess     bool
	GOWAYWSSCompatible   bool
	GOWAYWSSLatency      float64
	WSSJitter            float64
	WSSSuccessRate       float64
	GOWAYWSSErrorStage   string
	GOWAYWSSHTTPStatus   int
	GOWAYWSSErrorMessage string
	GOWAYWSSSNISent      string
	GOWAYWSSHostSent     string
	GOWAYWSSPathSent     string
	HTTPStatus           int
	SingleSpeed          float64
	DownloadSpeed        float64
	MinSpeed             float64
	P10Speed             float64
	MedianSpeed          float64
	Stability            float64
	CV                   float64
	StallCount           int
	ZeroSpeedIntervals   int
	TotalStallDuration   float64
	LongestStallDuration float64
	StallRate            float64
	LoadLatency          float64
	Colo                 string
	Error                string
	L3Executed           bool
	L4Executed           bool
}

// ProbeScheduler runs layered active background testing on managed routes.
type ProbeScheduler struct {
	mu               sync.RWMutex
	store            *RouteStore
	cfg              ProbeConfig
	speedSem         chan struct{} // limits concurrent bandwidth-heavy speed tests
	probeSem         chan struct{} // limits lightweight concurrent pings/handshakes
	cycleCount       sync.Map      // route IP -> int64 cycle count
	inFlight         sync.Map      // route IP -> struct{} per-IP probe concurrency de-duplication
	running          atomic.Bool
	stopCh           chan struct{}
	probeTrigger     chan string
	probeExec        func(ctx context.Context, target ResolvedProbeTarget, cfg ProbeConfig, runL3 bool, runFullSpeed bool) LayeredProbeResult
	nowFunc          func() time.Time
	onStartGoroutine func()
	onExitGoroutine  func()
}

var GlobalProbeScheduler = NewProbeScheduler(GlobalRouteStore, DefaultProbeConfig())

func NewProbeScheduler(store *RouteStore, cfg ProbeConfig) *ProbeScheduler {
	NormalizeProbeConfig(&cfg)
	return &ProbeScheduler{
		store:        store,
		cfg:          cfg,
		speedSem:     make(chan struct{}, cfg.MaxSpeedTests),
		probeSem:     make(chan struct{}, cfg.MaxConcurrent),
		stopCh:       make(chan struct{}),
		probeTrigger: make(chan string, 100),
	}
}

func (ps *ProbeScheduler) UpdateConfig(cfg ProbeConfig) {
	NormalizeProbeConfig(&cfg)
	ps.mu.Lock()
	defer ps.mu.Unlock()
	ps.cfg = cfg
}

func (ps *ProbeScheduler) GetConfig() ProbeConfig {
	ps.mu.RLock()
	defer ps.mu.RUnlock()
	return ps.cfg
}

// ExecuteLayeredProbe executes L1 to L5 sequentially on an IP, strictly driven by cfg.Profile via ResolvedProbeTarget.
func (ps *ProbeScheduler) ExecuteLayeredProbe(ctx context.Context, ip string, port int, runL3 bool, runFullSpeed bool) LayeredProbeResult {
	cfg := ps.GetConfig()
	target := ResolveProbeTarget(cfg, ip, port)
	return ps.ExecuteLayeredProbeWithSnapshot(ctx, target, cfg, runL3, runFullSpeed)
}

// ExecuteLayeredProbeWithSnapshot executes L1 to L5 sequentially with a fixed target and config snapshot.
func (ps *ProbeScheduler) ExecuteLayeredProbeWithSnapshot(ctx context.Context, target ResolvedProbeTarget, cfg ProbeConfig, runL3 bool, runFullSpeed bool) LayeredProbeResult {
	res := LayeredProbeResult{Success: false}

	// -------------------------------------------------------------
	// Layer 1: TCP Ping (5 pings, 带 Fail-Fast 机制)
	// -------------------------------------------------------------
	pingCount := 5
	lats := make([]float64, 0, pingCount)
	failures := 0
	for i := 0; i < pingCount; i++ {
		if ctx.Err() != nil {
			res.Error = "Context cancelled"
			return res
		}
		lat := TCPPing(target.IP, target.Port, 1200*time.Millisecond)
		if lat > 0 {
			lats = append(lats, lat)
		} else {
			failures++
			if failures >= 3 {
				break // 丢包率已达 60% 淘汰阈值，立即中止无需继续等待
			}
		}
		if i < pingCount-1 {
			time.Sleep(20 * time.Millisecond)
		}
	}

	if len(lats) == 0 {
		res.Error = "All TCP pings timed out"
		res.PacketLoss = 1.0
		return res
	}

	res.PacketLoss = float64(pingCount-len(lats)) / float64(pingCount)
	var sum float64
	for _, l := range lats {
		sum += l
	}
	res.RTT = sum / float64(len(lats))

	if len(lats) > 1 {
		var variance float64
		for _, l := range lats {
			diff := l - res.RTT
			variance += diff * diff
		}
		res.Jitter = math.Sqrt(variance / float64(len(lats)))
	}

	if res.PacketLoss >= 0.60 {
		res.Error = "Severe packet loss on Layer 1"
		return res
	}

	// -------------------------------------------------------------
	// Layer 2: L2 Connectivity Check (Profile-Driven)
	// -------------------------------------------------------------
	switch target.ProfileType {
	case ProfileCFST:
		ok, ttfb, statusCode, colo, err := HTTPSConnectivityCheck(ctx, target.IP, target.Port, target.SNI, target.Host, target.URL, 2500*time.Millisecond)
		res.GOWAYWSSCompatible = false
		res.HTTPStatus = statusCode
		if !ok {
			res.HandshakeSuccess = false
			if statusCode == 403 {
				res.Error = "HTTPS connectivity check returned HTTP 403 Forbidden"
			} else if err != nil {
				res.Error = "HTTPS connectivity check failed: " + err.Error()
			} else {
				res.Error = fmt.Sprintf("HTTPS connectivity check failed (HTTP %d)", statusCode)
			}
			return res
		}
		res.HandshakeSuccess = true
		if colo != "" {
			res.Colo = colo
		}
		if ttfb > 0 {
			res.LoadLatency = ttfb
		}

	case ProfileGOWAYWSS:
		wssRes := WSSHandshakeCheckContext(ctx, target.IP, target.Port, target.SNI, target.Host, target.Path, 2500*time.Millisecond)
		res.GOWAYWSSCompatible = wssRes.Success
		res.GOWAYWSSLatency = wssRes.Latency
		res.GOWAYWSSErrorStage = wssRes.ErrorStage
		res.GOWAYWSSHTTPStatus = wssRes.HTTPStatus
		res.HTTPStatus = wssRes.HTTPStatus
		res.GOWAYWSSErrorMessage = wssRes.ErrorMessage
		res.GOWAYWSSSNISent = wssRes.SNISent
		res.GOWAYWSSHostSent = wssRes.HostSent
		res.GOWAYWSSPathSent = wssRes.PathSent
		if wssRes.Colo != "" {
			res.Colo = wssRes.Colo
		}
		if !wssRes.Success {
			res.HandshakeSuccess = false
			res.Error = fmt.Sprintf("GOWAY WSS handshake failed (%s: %s)", wssRes.ErrorStage, wssRes.ErrorMessage)
			return res
		}
		res.HandshakeSuccess = true
		res.WSSSuccessRate = 1.0

	case ProfileCustom:
		if target.Protocol == "wss" {
			wssRes := WSSHandshakeCheckContext(ctx, target.IP, target.Port, target.SNI, target.Host, target.Path, 2500*time.Millisecond)
			res.GOWAYWSSCompatible = wssRes.Success
			res.GOWAYWSSLatency = wssRes.Latency
			res.GOWAYWSSErrorStage = wssRes.ErrorStage
			res.GOWAYWSSHTTPStatus = wssRes.HTTPStatus
			res.HTTPStatus = wssRes.HTTPStatus
			res.GOWAYWSSErrorMessage = wssRes.ErrorMessage
			res.GOWAYWSSSNISent = wssRes.SNISent
			res.GOWAYWSSHostSent = wssRes.HostSent
			res.GOWAYWSSPathSent = wssRes.PathSent
			if wssRes.Colo != "" {
				res.Colo = wssRes.Colo
			}
			if !wssRes.Success {
				res.HandshakeSuccess = false
				res.Error = fmt.Sprintf("Custom WSS handshake failed (%s: %s)", wssRes.ErrorStage, wssRes.ErrorMessage)
				return res
			}
			res.HandshakeSuccess = true
			res.WSSSuccessRate = 1.0
		} else {
			ok, ttfb, statusCode, colo, err := HTTPSConnectivityCheck(ctx, target.IP, target.Port, target.SNI, target.Host, target.URL, 2500*time.Millisecond)
			res.GOWAYWSSCompatible = false
			res.HTTPStatus = statusCode
			if !ok {
				res.HandshakeSuccess = false
				if statusCode == 403 {
					res.Error = "Custom HTTP(S) check returned HTTP 403 Forbidden"
				} else if err != nil {
					res.Error = "Custom HTTP(S) check failed: " + err.Error()
				} else {
					res.Error = fmt.Sprintf("Custom HTTP(S) check failed (HTTP %d)", statusCode)
				}
				return res
			}
			res.HandshakeSuccess = true
			if colo != "" {
				res.Colo = colo
			}
			if ttfb > 0 {
				res.LoadLatency = ttfb
			}
		}
	}

	speedTarget := ResolveSpeedTargetForProbe(cfg, target.IP, target.Port)

	// -------------------------------------------------------------
	// Layer 3: Lightweight HTTP / HTTPS Probe (~100KB payload)
	// -------------------------------------------------------------
	if runL3 && !runFullSpeed {
		l3Res := LightweightHTTPProbeTarget(ctx, speedTarget)
		if !l3Res.Success {
			res.Error = "L3 HTTP probe failed: " + l3Res.Error
			return res
		}
		res.SingleSpeed = l3Res.Speed
		res.DownloadSpeed = l3Res.Speed
		if l3Res.Colo != "" && res.Colo == "" {
			res.Colo = l3Res.Colo
		}
		if l3Res.TTFB > 0 {
			res.LoadLatency = l3Res.TTFB
		}
		res.L3Executed = true
	}

	// -------------------------------------------------------------
	// Layer 4: Full Speed Test (Bandwidth-throttled calibration)
	// -------------------------------------------------------------
	if runFullSpeed {
		if target.ProfileType == ProfileGOWAYWSS || (target.ProfileType == ProfileCustom && strings.EqualFold(target.Protocol, "wss")) {
			avgWSS, jitWSS, rateWSS, wColo := MeasureWSSStability(ctx, target.IP, target.Port, target.SNI, target.Host, target.Path, 3, 2200*time.Millisecond)
			if avgWSS > 0 {
				res.GOWAYWSSLatency = avgWSS
			}
			res.WSSJitter = jitWSS
			res.WSSSuccessRate = rateWSS
			if wColo != "" && res.Colo == "" {
				res.Colo = wColo
			}
		}

		select {
		case ps.speedSem <- struct{}{}:
			defer func() { <-ps.speedSem }()
		case <-ctx.Done():
			res.Error = "Cancelled waiting for speed test slot"
			return res
		}

		duration := cfg.FullDuration
		if duration < 2 {
			duration = 5
		}

		sm := SingleStreamTestDetailed(ctx, speedTarget, duration, nil, res.RTT, res.Jitter, res.PacketLoss)
		res.SingleSpeed = sm.AverageSpeed
		res.DownloadSpeed = sm.AverageSpeed
		res.MinSpeed = sm.MinSpeed
		res.P10Speed = sm.P10Speed
		res.MedianSpeed = sm.MedianSpeed
		res.Stability = sm.Stability
		res.CV = sm.CoefficientOfVariation
		res.StallCount = sm.StallCount
		res.ZeroSpeedIntervals = sm.ZeroSpeedIntervals
		res.TotalStallDuration = sm.TotalStallDuration
		res.LongestStallDuration = sm.LongestStallDuration
		res.StallRate = sm.StallRate
		if sm.HTTPStatus > 0 {
			res.HTTPStatus = sm.HTTPStatus
		}
		res.L4Executed = true

		if sm.Aborted403 || sm.HTTPStatus == 403 {
			res.Error = "HTTP 403 Forbidden during speed test"
			return res
		}
		if sm.AverageSpeed <= 0 && sm.MinSpeed <= 0 {
			res.Error = "Speed test returned 0 MB/s"
			return res
		}

		if res.Colo == "" {
			if v, ok := ipColoCache.Load(speedTarget.IP); ok && v.(string) != "" {
				res.Colo = v.(string)
			} else if strings.Contains(speedTarget.URL, "speed.cloudflare.com") {
				if c := GetColo(speedTarget.IP, speedTarget.Port); c != "ERR" && c != "UNK" {
					res.Colo = c
					ipColoCache.Store(speedTarget.IP, c)
				}
			}
		}

		if res.LoadLatency <= 0 {
			res.LoadLatency = res.RTT
		}
	}

	res.Success = true
	return res
}

// ProbeOnce executes a probe pass for a single route and updates the store.
func (ps *ProbeScheduler) incCycle(ip string) int64 {
	val, _ := ps.cycleCount.LoadOrStore(ip, int64(0))
	cycle := val.(int64) + 1
	ps.cycleCount.Store(ip, cycle)
	return cycle
}

func (ps *ProbeScheduler) ProbeOnce(ctx context.Context, ip string, forceSpeed bool) (*RouteMetrics, error) {
	// 1. In-flight per-IP probe de-duplication:
	// Only one ProbeOnce can run per IP at any time.
	if _, loaded := ps.inFlight.LoadOrStore(ip, struct{}{}); loaded {
		if m, exists := ps.store.GetMetrics(ip); exists {
			snapshot := m
			return &snapshot, nil
		}
		return nil, fmt.Errorf("probe already in progress for %s", ip)
	}
	defer ps.inFlight.Delete(ip)

	// 2. Atomic configuration snapshot: single synchronized read, preventing torn or mixed state
	cfg := ps.GetConfig()

	port := cfg.Port
	if cfg.Profile.Type == ProfileGOWAYWSS && cfg.Profile.Port > 0 {
		port = cfg.Profile.Port
	}
	tier := TierCandidate
	existingColo := ""
	recM, exists := ps.store.GetMetrics(ip)
	if exists {
		if recM.Port > 0 && cfg.Profile.Type != ProfileGOWAYWSS {
			port = recM.Port
		}
		tier = recM.Tier
		existingColo = recM.Colo
	}

	// 3. Determine if speed test is scheduled using snapshot cfg
	cycle := ps.incCycle(ip)

	runL3 := false
	runFullSpeed := false
	if forceSpeed {
		runL3 = true
		runFullSpeed = true
	} else {
		l3Cycle := cfg.L3ProbeCycle
		if l3Cycle < 1 {
			l3Cycle = 3
		}
		fullCycle := cfg.FullSpeedCycle
		if fullCycle < 1 {
			fullCycle = 60
		}

		switch tier {
		case TierActive:
			// Active route: L1/L2 every cycle (10s)
			// L3 lightweight 100KB check every L3ProbeCycle (default 3 cycles = ~30s)
			if cycle == 1 || cycle%int64(l3Cycle) == 0 {
				runL3 = true
			}
			// L4 full speed calibration only every FullSpeedCycle (default 60 cycles = ~10m)
			if cycle%int64(fullCycle) == 0 {
				runFullSpeed = true
			}
		case TierStandby:
			// Standby route: lower frequency
			if cycle == 1 || cycle%int64(l3Cycle*2) == 0 {
				runL3 = true
			}
			if cycle%int64(fullCycle*2) == 0 {
				runFullSpeed = true
			}
		case TierCandidate:
			// Candidate: low frequency L3, plus L4 calibration when no P10 speed exists yet
			// so genuinely fast nodes can earn L4 metrics and cross promotion thresholds.
			if cycle == 1 || cycle%int64(l3Cycle*4) == 0 {
				runL3 = true
			}
			if (!exists || recM.P10Speed <= 0) && (cycle == 2 || cycle%int64(l3Cycle*8) == 0) {
				runFullSpeed = true
			}
		case TierFailed:
			// Failed routes: ONLY L1/L2 recovery checks, ZERO speed tests!
			runL3 = false
			runFullSpeed = false
		}
	}

	target := ResolveProbeTarget(cfg, ip, port)
	var result LayeredProbeResult
	if ps.probeExec != nil {
		result = ps.probeExec(ctx, target, cfg, runL3, runFullSpeed)
	} else {
		result = ps.ExecuteLayeredProbeWithSnapshot(ctx, target, cfg, runL3, runFullSpeed)
	}

	durationSec := 0.0
	if runFullSpeed {
		d := cfg.FullDuration
		if d < 2 {
			d = 5
		}
		durationSec = float64(d)
	} else if runL3 {
		durationSec = 1.0
	}

	now := time.Now()
	if ps.nowFunc != nil {
		now = ps.nowFunc()
	}
	m := RouteMetrics{
		ID:                   GenerateRouteID(ip, port),
		IP:                   ip,
		Port:                 port,
		Colo:                 result.Colo,
		Tier:                 tier,
		RTT:                  result.RTT,
		PacketLoss:           result.PacketLoss,
		Jitter:               result.Jitter,
		HandshakeSuccess:     result.HandshakeSuccess,
		GOWAYWSSCompatible:   result.GOWAYWSSCompatible,
		GOWAYWSSLatency:      result.GOWAYWSSLatency,
		WSSJitter:            result.WSSJitter,
		WSSSuccessRate:       result.WSSSuccessRate,
		GOWAYWSSErrorStage:   result.GOWAYWSSErrorStage,
		GOWAYWSSHTTPStatus:   result.GOWAYWSSHTTPStatus,
		GOWAYWSSErrorMessage: result.GOWAYWSSErrorMessage,
		GOWAYWSSSNISent:      result.GOWAYWSSSNISent,
		GOWAYWSSHostSent:     result.GOWAYWSSHostSent,
		GOWAYWSSPathSent:     result.GOWAYWSSPathSent,
		DownloadSpeed:        result.SingleSpeed,
		SingleSpeed:          result.SingleSpeed,
		P10Speed:             result.P10Speed,
		MedianSpeed:          result.MedianSpeed,
		MinSpeed:             result.MinSpeed,
		Stability:            result.Stability,
		CV:                   result.CV,
		StallCount:           result.StallCount,
		ZeroSpeedIntervals:   result.ZeroSpeedIntervals,
		TotalStallDuration:   result.TotalStallDuration,
		LongestStallDuration: result.LongestStallDuration,
		StallRate:            result.StallRate,
		DurationSeconds:      durationSec,
		LoadLatency:          result.LoadLatency,
		LastTested:           now,
		Timestamp:            now,
		ConsecutiveFails:     0,
		ConsecutiveSuccess:   0,
	}

	if m.Colo == "" {
		m.Colo = existingColo
	}
	if exists {
		m.ConsecutiveFails = recM.ConsecutiveFails
		m.ConsecutiveSuccess = recM.ConsecutiveSuccess
		m.ConsecutiveDegraded = recM.ConsecutiveDegraded
		m.Health = recM.Health
		if m.WSSSuccessRate <= 0 && recM.WSSSuccessRate > 0 {
			m.WSSJitter = recM.WSSJitter
			m.WSSSuccessRate = recM.WSSSuccessRate
		}
		// If full speed test wasn't run on this cycle, handle speeds
		if !runFullSpeed {
			if runL3 {
				// L3 updated single speed / download speed from real lightweight HTTP probe
				m.DownloadSpeed = result.SingleSpeed
				m.SingleSpeed = result.SingleSpeed
				if result.LoadLatency > 0 {
					m.LoadLatency = result.LoadLatency
				} else {
					m.LoadLatency = recM.LoadLatency
				}
				// Preserve existing P10/Median/Min/Stability/CV/Stall from previous history
				m.P10Speed = recM.P10Speed
				m.MedianSpeed = recM.MedianSpeed
				m.MinSpeed = recM.MinSpeed
				m.Stability = recM.Stability
				m.CV = recM.CV
				m.StallCount = recM.StallCount
				m.ZeroSpeedIntervals = recM.ZeroSpeedIntervals
				m.TotalStallDuration = recM.TotalStallDuration
				m.LongestStallDuration = recM.LongestStallDuration
				m.StallRate = recM.StallRate
			} else {
				m.DownloadSpeed = recM.DownloadSpeed
				m.SingleSpeed = recM.SingleSpeed
				m.P10Speed = recM.P10Speed
				m.MedianSpeed = recM.MedianSpeed
				m.MinSpeed = recM.MinSpeed
				m.Stability = recM.Stability
				m.CV = recM.CV
				m.StallCount = recM.StallCount
				m.ZeroSpeedIntervals = recM.ZeroSpeedIntervals
				m.TotalStallDuration = recM.TotalStallDuration
				m.LongestStallDuration = recM.LongestStallDuration
				m.StallRate = recM.StallRate
				m.LoadLatency = recM.LoadLatency
			}
		}
	}

	ps.store.RecordProbeResult(m, result.Success)
	if updated, exists := ps.store.GetMetrics(ip); exists {
		snapshot := updated
		return &snapshot, nil
	}
	snapshot := m
	return &snapshot, nil
}

// Start launches the background probing daemon.
func (ps *ProbeScheduler) Start(ctx context.Context) {
	ps.mu.Lock()
	if ps.running.Load() {
		ps.mu.Unlock()
		return // already running
	}
	ps.running.Store(true)
	stopCh := make(chan struct{})
	ps.stopCh = stopCh
	ps.mu.Unlock()

	go func(myStopCh chan struct{}, myCtx context.Context) {
		if ps.onStartGoroutine != nil {
			ps.onStartGoroutine()
		}
		defer func() {
			if ps.onExitGoroutine != nil {
				ps.onExitGoroutine()
			}
		}()

		ticker := time.NewTicker(2 * time.Second)
		defer ticker.Stop()

		for {
			select {
			case <-myStopCh:
				return
			case <-myCtx.Done():
				// Only clear running state if this generation is still current.
				// Prevents a stale ctx-cancel from clobbering a newer Start().
				ps.mu.Lock()
				if ps.stopCh == myStopCh {
					ps.running.Store(false)
					ps.stopCh = nil
				}
				ps.mu.Unlock()
				return
			case ip := <-ps.probeTrigger:
				go func(targetIP string) {
					ps.ProbeOnce(myCtx, targetIP, true)
				}(ip)
			case now := <-ticker.C:
				ps.evaluateAndSchedule(myCtx, now)
			}
		}
	}(stopCh, ctx)
}

// Stop cleanly terminates the probe scheduler.
func (ps *ProbeScheduler) Stop() {
	ps.mu.Lock()
	defer ps.mu.Unlock()
	if ps.running.Swap(false) {
		if ps.stopCh != nil {
			close(ps.stopCh)
			ps.stopCh = nil
		}
	}
}

func routeTierPriority(t RouteTier) int {
	switch t {
	case TierActive:
		return 0
	case TierStandby:
		return 1
	case TierCandidate:
		return 2
	case TierFailed:
		return 3
	default:
		return 4
	}
}

// evaluateAndSchedule scans all routes in store and schedules probes based on their tier priority and interval.
func (ps *ProbeScheduler) evaluateAndSchedule(ctx context.Context, now time.Time) {
	cfg := ps.GetConfig()
	routes := ps.store.GetAll()

	var due []RouteMetrics
	for _, r := range routes {
		var interval time.Duration
		switch r.Tier {
		case TierActive:
			interval = cfg.ActiveInterval
		case TierStandby:
			interval = cfg.StandbyInterval
		case TierFailed:
			interval = cfg.FailedInterval
		default: // Candidate
			interval = cfg.CandidateInterval
		}

		if interval <= 0 {
			continue
		}

		if r.LastTested.IsZero() || now.Sub(r.LastTested) >= interval {
			// In-flight check: skip if probe is already running on this IP
			if _, inFlight := ps.inFlight.Load(r.IP); inFlight {
				continue
			}
			due = append(due, r)
		}
	}

	// Prioritize ACTIVE > STANDBY > CANDIDATE > FAILED, then least recently tested
	// so newly discovered candidates cannot starve active route monitoring.
	sort.Slice(due, func(i, j int) bool {
		pi := routeTierPriority(due[i].Tier)
		pj := routeTierPriority(due[j].Tier)
		if pi != pj {
			return pi < pj
		}
		if due[i].LastTested.IsZero() != due[j].LastTested.IsZero() {
			return due[i].LastTested.IsZero()
		}
		return due[i].LastTested.Before(due[j].LastTested)
	})

	for _, r := range due {
		// Acquire concurrency slot
		select {
		case ps.probeSem <- struct{}{}:
			go func(routeIP string) {
				defer func() { <-ps.probeSem }()
				ps.ProbeOnce(ctx, routeIP, false)
			}(r.IP)
		default:
			// Work queue full, lower-priority/remaining routes defer to next tick
		}
	}

	// Periodically evaluate tier promotions and demotions across all managed routes
	ps.store.EvaluateTierTransitions(now)
}

// ============================================================================
// SECTION: CONTINUOUS CLOUDFLARE DISCOVERY (from discovery.go)
// ============================================================================
// DiscoveryStatus exposes the runtime state and results of the continuous discovery engine.
type DiscoveryStatus struct {
	Enabled         bool      `json:"enabled"`
	IntervalSec     int       `json:"interval_sec"`
	LastRun         time.Time `json:"last_run"`
	LastDurationSec float64   `json:"last_duration_sec"`
	Scanned         int       `json:"scanned"`
	TCPValid        int       `json:"tcp_valid"`
	HTTPSValid      int       `json:"https_valid"`
	NewCandidates   int       `json:"new_candidates"`
	ExistingRoutes  int       `json:"existing_routes"`
}

// DiscoveryManager orchestrates periodic background discovery of Cloudflare edge IPs.
type DiscoveryManager struct {
	mu               sync.RWMutex
	status           DiscoveryStatus
	store            *RouteStore
	sched            *ProbeScheduler
	running          atomic.Bool
	inProgress       atomic.Bool
	stopCh           chan struct{}
	scanFunc         func(ctx context.Context, ips []string, port int, concurrent int, profile ProbeProfile, progress func(done, total, valid int)) ([]NodeResult, int, int)
	ipProvider       func() []string
	onStartGoroutine func()
	onExitGoroutine  func()
}

var GlobalDiscoveryManager = NewDiscoveryManager(GlobalRouteStore, GlobalProbeScheduler)

func NewDiscoveryManager(store *RouteStore, sched *ProbeScheduler) *DiscoveryManager {
	return &DiscoveryManager{
		store:  store,
		sched:  sched,
		stopCh: make(chan struct{}),
		status: DiscoveryStatus{
			Enabled:     true,
			IntervalSec: 3600,
		},
	}
}

// GetStatus returns a snapshot of current discovery status.
func (dm *DiscoveryManager) GetStatus() DiscoveryStatus {
	dm.mu.RLock()
	defer dm.mu.RUnlock()
	st := dm.status
	cfg := dm.sched.GetConfig()
	st.Enabled = cfg.DiscoveryEnabled
	st.IntervalSec = int(cfg.DiscoveryInterval.Seconds())
	return st
}

// Start launches the continuous background discovery worker.
func (dm *DiscoveryManager) Start(ctx context.Context) {
	dm.mu.Lock()
	if dm.running.Load() {
		dm.mu.Unlock()
		return // already running
	}
	dm.running.Store(true)
	stopCh := make(chan struct{})
	dm.stopCh = stopCh
	dm.mu.Unlock()

	// 1. Trigger immediate initial discovery pass asynchronously on startup
	go func(myCtx context.Context) {
		if myCtx.Err() != nil {
			return
		}
		cfg := dm.sched.GetConfig()
		if cfg.DiscoveryEnabled {
			_, _ = dm.RunOnce(myCtx)
		}
	}(ctx)

	// 2. Periodic background discovery loop
	go func(myStopCh chan struct{}, myCtx context.Context) {
		if dm.onStartGoroutine != nil {
			dm.onStartGoroutine()
		}
		defer func() {
			if dm.onExitGoroutine != nil {
				dm.onExitGoroutine()
			}
		}()

		cfg := dm.sched.GetConfig()
		interval := cfg.DiscoveryInterval
		if interval <= 0 {
			interval = 60 * time.Minute
		}

		ticker := time.NewTicker(interval)
		defer ticker.Stop()

		for {
			select {
			case <-myStopCh:
				return
			case <-myCtx.Done():
				// Only clear running state if this generation is still current.
				// Prevents a stale ctx-cancel from clobbering a newer Start().
				dm.mu.Lock()
				if dm.stopCh == myStopCh {
					dm.running.Store(false)
					dm.stopCh = nil
				}
				dm.mu.Unlock()
				return
			case <-ticker.C:
				cfg := dm.sched.GetConfig()
				if !cfg.DiscoveryEnabled {
					continue
				}
				_, _ = dm.RunOnce(myCtx)
				// Re-align ticker if interval changed
				if cfg.DiscoveryInterval > 0 && cfg.DiscoveryInterval != interval {
					interval = cfg.DiscoveryInterval
					ticker.Reset(interval)
				}
			}
		}
	}(stopCh, ctx)
}

// Stop cleanly halts the background discovery worker.
func (dm *DiscoveryManager) Stop() {
	dm.mu.Lock()
	defer dm.mu.Unlock()
	if dm.running.Swap(false) {
		if dm.stopCh != nil {
			close(dm.stopCh)
			dm.stopCh = nil
		}
	}
}

// RunOnce performs a single low-bandwidth discovery pass across Cloudflare IP space.
func (dm *DiscoveryManager) RunOnce(ctx context.Context) (DiscoveryStatus, error) {
	if !dm.inProgress.CompareAndSwap(false, true) {
		return dm.GetStatus(), fmt.Errorf("discovery already in progress")
	}
	defer dm.inProgress.Store(false)

	start := time.Now()
	cfg := dm.sched.GetConfig()

	scanCount := cfg.DiscoveryScanCount
	if scanCount <= 0 {
		scanCount = 200
	}

	var ips []string
	if dm.ipProvider != nil {
		ips = dm.ipProvider()
	} else {
		ips = GenerateIPs(scanCount, true, cfg.IPFile)
	}
	if len(ips) == 0 {
		return dm.GetStatus(), fmt.Errorf("no candidate IPs generated for discovery")
	}

	fmt.Printf("\n[Discovery]\nScanning %d Cloudflare IPs...\n", len(ips))

	scanConcurrency := 50
	if cfg.MaxConcurrent > 50 {
		scanConcurrency = cfg.MaxConcurrent
	}

	scanFn := dm.scanFunc
	if scanFn == nil {
		scanFn = ScanRoutesWithProfileDetailed
	}

	validNodes, tcpValid, httpsValid := scanFn(ctx, ips, cfg.Port, scanConcurrency, cfg.Profile, nil)

	newCandidates := 0
	existingRoutes := 0
	var bestNewCandidate *RouteMetrics

	isGOWAYWSS := cfg.Profile.Type == ProfileGOWAYWSS || (cfg.Profile.Type == ProfileCustom && cfg.Profile.Protocol == "wss")

	scannedIPs := make(map[string]struct{}, len(ips))
	for _, ip := range ips {
		ip = strings.TrimSpace(ip)
		if ip != "" {
			scannedIPs[ip] = struct{}{}
		}
	}

	validNodeIPs := make(map[string]struct{}, len(validNodes))
	for _, node := range validNodes {
		if strings.TrimSpace(node.IP) != "" {
			validNodeIPs[node.IP] = struct{}{}
		}
	}

	for _, node := range validNodes {
		// Strict GOWAY-WSS compatibility gate:
		// When profile is GOWAY-WSS, ONLY nodes with GOWAYWSSCompatible == true can enter or remain as valid candidates.
		// Nodes returning HTTP 200, 403, 404, 502 or with failed WSS handshakes are strictly rejected.
		if isGOWAYWSS && !node.GOWAYWSSCompatible {
			if rm, exists := dm.store.GetMetrics(node.IP); exists {
				// Existing route failed WSS check in this round: record failure so it cannot bypass as valid candidate
				rm.GOWAYWSSCompatible = false
				rm.HandshakeSuccess = false
				rm.GOWAYWSSLatency = node.GOWAYWSSLatency
				rm.GOWAYWSSErrorStage = node.GOWAYWSSErrorStage
				rm.GOWAYWSSHTTPStatus = node.GOWAYWSSHTTPStatus
				rm.GOWAYWSSErrorMessage = node.GOWAYWSSErrorMessage
				rm.GOWAYWSSSNISent = node.GOWAYWSSSNISent
				rm.GOWAYWSSHostSent = node.GOWAYWSSHostSent
				rm.GOWAYWSSPathSent = node.GOWAYWSSPathSent
				dm.store.RecordProbeResult(rm, false)
			}
			continue
		}

		if rm, exists := dm.store.GetMetrics(node.IP); exists {
			// Existing route: preserve all historical samples, EWMA, and stability scores
			existingRoutes++
			if node.Colo != "" {
				dm.store.UpdateRouteColo(node.IP, node.Colo)
			}
			if isGOWAYWSS {
				rm.GOWAYWSSCompatible = true
				rm.HandshakeSuccess = true
				rm.GOWAYWSSLatency = node.GOWAYWSSLatency
				rm.GOWAYWSSErrorStage = node.GOWAYWSSErrorStage
				rm.GOWAYWSSHTTPStatus = node.GOWAYWSSHTTPStatus
				rm.GOWAYWSSErrorMessage = node.GOWAYWSSErrorMessage
				rm.GOWAYWSSSNISent = node.GOWAYWSSSNISent
				rm.GOWAYWSSHostSent = node.GOWAYWSSHostSent
				rm.GOWAYWSSPathSent = node.GOWAYWSSPathSent
				dm.store.UpsertRoute(rm)
			}
		} else {
			// New route: strictly enter as TierCandidate
			newCandidates++
			rm := FromNodeResult(node, TierCandidate)
			if isGOWAYWSS {
				rm.GOWAYWSSCompatible = true
				rm.HandshakeSuccess = true
				rm.GOWAYWSSLatency = node.GOWAYWSSLatency
				rm.GOWAYWSSErrorStage = node.GOWAYWSSErrorStage
				rm.GOWAYWSSHTTPStatus = node.GOWAYWSSHTTPStatus
				rm.GOWAYWSSErrorMessage = node.GOWAYWSSErrorMessage
				rm.GOWAYWSSSNISent = node.GOWAYWSSSNISent
				rm.GOWAYWSSHostSent = node.GOWAYWSSHostSent
				rm.GOWAYWSSPathSent = node.GOWAYWSSPathSent
			} else {
				rm.GOWAYWSSCompatible = false
			}
			dm.store.UpsertRoute(*rm)

			if bestNewCandidate == nil || rm.FinalScore > bestNewCandidate.FinalScore || (rm.FinalScore == bestNewCandidate.FinalScore && rm.RTT < bestNewCandidate.RTT) {
				bestNewCandidate = rm
			}
		}
	}

	if isGOWAYWSS {
		for ip := range scannedIPs {
			if _, valid := validNodeIPs[ip]; valid {
				continue
			}

			rm, exists := dm.store.GetMetrics(ip)
			if !exists {
				continue
			}

			// 本轮 scanner 没有返回该节点，
			// 说明它没有通过当前 GOWAY-WSS Gate。
			rm.GOWAYWSSCompatible = false
			rm.HandshakeSuccess = false

			// 清除本轮无法得到的成功状态。
			// 不要保留旧的 WSS=true。
			rm.GOWAYWSSLatency = 0
			rm.GOWAYWSSHTTPStatus = 0

			if rm.GOWAYWSSErrorStage == "" {
				rm.GOWAYWSSErrorStage = "wss_gate"
			}

			if rm.GOWAYWSSErrorMessage == "" {
				rm.GOWAYWSSErrorMessage = "node failed GOWAY-WSS compatibility gate"
			}

			dm.store.RecordProbeResult(rm, false)
		}
	}

	durationSec := math.Round(time.Since(start).Seconds()*10) / 10

	dm.mu.Lock()
	dm.status = DiscoveryStatus{
		Enabled:         cfg.DiscoveryEnabled,
		IntervalSec:     int(cfg.DiscoveryInterval.Seconds()),
		LastRun:         start,
		LastDurationSec: durationSec,
		Scanned:         len(ips),
		TCPValid:        tcpValid,
		HTTPSValid:      httpsValid,
		NewCandidates:   newCandidates,
		ExistingRoutes:  existingRoutes,
	}
	resStatus := dm.status
	dm.mu.Unlock()

	fmt.Println("[Discovery]")
	fmt.Printf("TCP valid: %d\n", tcpValid)
	fmt.Printf("HTTPS valid: %d\n", httpsValid)
	fmt.Printf("New candidates: %d\n", newCandidates)
	fmt.Printf("Existing routes: %d\n", existingRoutes)

	if bestNewCandidate != nil {
		fmt.Println("[Discovery]")
		fmt.Println("Best candidate:")
		fmt.Println(bestNewCandidate.IP)
		fmt.Printf("Score: %.1f\n", bestNewCandidate.FinalScore)
		fmt.Printf("P10: %.1f MB/s\n", bestNewCandidate.P10Speed)
		fmt.Printf("Stability: %.1f\n", bestNewCandidate.Stability)
	}

	return resStatus, nil
}

