type Config struct {
	IPFile          string
	Port            int
	MaxScan         int
	TopN            int
	DLConc          int
	DownloadNum     int
	Duration        int
	StopThreshold   float64
	Unique          bool
	Output          string
	ScanConcurrent  int
	WebPort         string
	WebMode         bool
	URL             string
	Skip429         bool
	QuickDuration   int
	SkipLoadLatency bool // auto-set for custom URL mode
	FilterMode      string
	SNI             string
	WSSHost         string
	WSSPath         string
	Profile         string // "CFST" (default), "GOWAY-WSS", "CUSTOM"
	GowayTarget     string // Shorthand: domain[:port][/path]
	Preset          string // "fast" / "standard" / "deep"
	Yes             bool   // Non-interactive confirmation
	AllSubnets      bool   // Force 100% /24 subnet coverage

	// Route Quality Probe daemon options
	DaemonMode         bool
	APIAddr            string
	ActiveInterval     int    // seconds
	StandbyInterval    int    // seconds
	CandidateInterval  int    // seconds
	FailedInterval     int    // seconds
	ScoreMode          string // "normal" or "peak"
	StateFile          string // path to state snapshot json
	DiscoveryEnabled   bool   // periodic continuous discovery in background
	DiscoveryInterval  int    // seconds between discovery passes (default 3600)
	DiscoveryScanCount int    // random IPs scanned per pass (default 200)
}

func DefaultConfig() Config {
	return Config{
		Port:               443,
		MaxScan:            0,    // 0 + Unique=true => 扫描 100% 全量 /24 网段（约 5,900+ 个）
		TopN:               30,   // 优选前 30 个进入深度测速
		DLConc:             1,    // 单线程独占带宽精确测速，杜绝多连接争抢导致 P10 与稳定性失真
		DownloadNum:        10,   // 输出前 10 个高质量长连接节点
		Duration:           8,    // 每个测 8 秒，充分检验稳态吞吐与后半程抗限速能力
		StopThreshold:      0,    // 0 = 不提前中断，确保全局真正最快/最高吞吐的节点胜出
		Unique:             true, // 每个 /24 C段只取 1 个 IP，避免同网段重复浪费时间
		Output:             "result_colo.csv",
		ScanConcurrent:     400, // 高并发全网段快速扫描
		WebPort:            "9876",
		URL:                "https://speed.cloudflare.com/__down?bytes=1000000000", // 1GB 上限防止高速线路提前下完
		Skip429:            true,
		QuickDuration:      2, // 预筛 2 秒快速淘汰慢/限速节点
		FilterMode:         "speed",
		WSSHost:            "",
		WSSPath:            "/pyway",
		Profile:            "CFST",
		Preset:             "standard",
		DaemonMode:         false,
		APIAddr:            "127.0.0.1:9876",
		ActiveInterval:     10,
		StandbyInterval:    30,
		CandidateInterval:  180,
		FailedInterval:     60,
		ScoreMode:          "normal",
		StateFile:          "cfst_state.json",
		DiscoveryEnabled:   true,
		DiscoveryInterval:  3600,
		DiscoveryScanCount: 200,
	}
}

// applyPreset adjusts scan parameters according to named presets ("fast", "standard", "deep")
// without clobbering user's GOWAY/target choices.
func applyPreset(cfg *Config) {
	if cfg == nil {
		return
	}
	switch strings.ToLower(strings.TrimSpace(cfg.Preset)) {
	case "fast":
		cfg.MaxScan = 800
		cfg.TopN = 15
		cfg.DownloadNum = 6
		cfg.Duration = 5
		cfg.QuickDuration = 2
		cfg.ScanConcurrent = 400
		cfg.Unique = true
	case "standard", "":
		// Respect AllSubnets / default standard settings
		if cfg.Preset == "standard" {
			cfg.MaxScan = 0
			cfg.TopN = 30
			cfg.DownloadNum = 10
			cfg.Duration = 8
			cfg.QuickDuration = 2
			cfg.ScanConcurrent = 400
			cfg.Unique = true
		}
	case "deep":
		cfg.MaxScan = 0
		cfg.TopN = 50
		cfg.DownloadNum = 15
		cfg.Duration = 12
		cfg.QuickDuration = 3
		cfg.ScanConcurrent = 500
		cfg.Unique = true
	}
}

func presetQuickPoolSize(cfg Config) int {
	pool := 160
	switch strings.ToLower(strings.TrimSpace(cfg.Preset)) {
	case "fast":
		pool = 60
	case "deep":
		pool = 320
	}
	if cfg.TopN*2 > pool {
		pool = cfg.TopN * 2
	}
	return pool
}

// GetProbeProfile returns the effective ProbeProfile derived strictly from Config.
func (cfg Config) GetProbeProfile() ProbeProfile {
	resolveGowayFields(&cfg)
	switch strings.ToUpper(strings.TrimSpace(cfg.Profile)) {
	case "GOWAY-WSS", "GOWAY_WSS", "WSS":
		return NewProfileGOWAYWSS(cfg.WSSHost, cfg.WSSPath, cfg.SNI, cfg.Port)
	case "CUSTOM":
		return NewProfileCustom(cfg.URL, cfg.SNI, cfg.Port)
	default:
		prof := NewProfileCFST()
		if cfg.Port > 0 {
			prof.Port = cfg.Port
		}
		if strings.TrimSpace(cfg.SNI) != "" {
			prof.SNI = strings.TrimSpace(cfg.SNI)
			prof.Host = prof.SNI
		}
		return prof
	}
}

func isCustomURL(urlStr string) bool {
	return !strings.Contains(urlStr, "speed.cloudflare.com/__down")
}

// ScanRoutesWithProfile runs profile-driven candidate discovery.
// - ProfileCFST: TCP Ping + HTTPSConnectivityCheck (strictly NO WSS, NEVER calls WSSHandshakeCheck).
// - ProfileGOWAYWSS: TCP Ping + WSSHandshakeCheck (using Profile.Host, Profile.SNI, Profile.Path).
// - ProfileCustom: TCP Ping + (HTTPSConnectivityCheck if http/https, WSSHandshakeCheck if wss).
func ScanRoutesWithProfile(ctx context.Context, ips []string, port int, concurrency int, profile ProbeProfile, progressCallback func(done, total, valid int)) []NodeResult {
	nodes, _, _ := ScanRoutesWithProfileDetailed(ctx, ips, port, concurrency, profile, progressCallback)
	return nodes
}

func subnet24Key(ip string) string {
	parsed := net.ParseIP(strings.TrimSpace(ip))
	if parsed == nil {
		return ""
	}
	v4 := parsed.To4()
	if v4 == nil {
		return ""
	}
	return fmt.Sprintf("%d.%d.%d.0/24", v4[0], v4[1], v4[2])
}

func prefix20Key(ip string) string {
	parsed := net.ParseIP(strings.TrimSpace(ip))
	if parsed == nil {
		return ip
	}
	v4 := parsed.To4()
	if v4 == nil {
		return ip
	}
	return fmt.Sprintf("%d.%d.%d.0/20", v4[0], v4[1], v4[2]&0xF0)
}

// selectDiverseCandidates selects up to maxPool candidates stratified by (Colo, /20) buckets
// using round-robin ordered by latency/jitter/loss key, preventing a single throttled low-RTT /16
// or Colo from crowding out faster clusters.
func selectDiverseCandidates(nodes []NodeResult, maxPool int) []NodeResult {
	sorted := make([]NodeResult, len(nodes))
	copy(sorted, nodes)
	sort.Slice(sorted, func(i, j int) bool {
		return routePreRankKey(sorted[i]) < routePreRankKey(sorted[j])
	})
	if maxPool <= 0 || len(sorted) <= maxPool {
		return sorted
	}

	type bucket struct {
		key   string
		items []NodeResult
	}
	bucketMap := make(map[string]*bucket)
	for _, n := range sorted {
		colo := strings.ToUpper(strings.TrimSpace(n.Colo))
		if colo == "" || colo == "ERR" || colo == "UNK" {
			colo = "UNK"
		}
		bKey := colo + "|" + prefix20Key(n.IP)
		b, ok := bucketMap[bKey]
		if !ok {
			b = &bucket{key: bKey}
			bucketMap[bKey] = b
		}
		b.items = append(b.items, n)
	}

	buckets := make([]*bucket, 0, len(bucketMap))
	for _, b := range bucketMap {
		buckets = append(buckets, b)
	}
	sort.Slice(buckets, func(i, j int) bool {
		ki := routePreRankKey(buckets[i].items[0])
		kj := routePreRankKey(buckets[j].items[0])
		if ki != kj {
			return ki < kj
		}
		return buckets[i].key < buckets[j].key
	})

	selected := make([]NodeResult, 0, maxPool)
	cursor := make([]int, len(buckets))
	for len(selected) < maxPool {
		progressed := false
		for bi, b := range buckets {
			if cursor[bi] < len(b.items) {
				selected = append(selected, b.items[cursor[bi]])
				cursor[bi]++
				progressed = true
				if len(selected) >= maxPool {
					break
				}
			}
		}
		if !progressed {
			break
		}
	}
	return selected
}

// ScanRoutesWithProfileDetailed runs profile-driven candidate discovery and returns valid nodes along with TCP valid and L2 valid counts.
func ScanRoutesWithProfileDetailed(ctx context.Context, ips []string, port int, concurrency int, profile ProbeProfile, progressCallback func(done, total, valid int)) ([]NodeResult, int, int) {
	if profile.Type == "" {
		profile = NewProfileCFST()
	}
	targetPort := port
	if targetPort <= 0 {
		targetPort = profile.Port
	}
	if targetPort <= 0 {
		targetPort = 443
	}

	var validNodes []NodeResult
	var mu sync.Mutex
	var subnet403Mu sync.Mutex
	subnet403Counts := make(map[string]int)
	const subnet403Limit = 2

	isSubnet403Blocked := func(sub string) bool {
		if sub == "" {
			return false
		}
		subnet403Mu.Lock()
		c := subnet403Counts[sub]
		subnet403Mu.Unlock()
		return c >= subnet403Limit
	}
	recordSubnet403 := func(sub string) {
		if sub == "" {
			return
		}
		subnet403Mu.Lock()
		subnet403Counts[sub]++
		subnet403Mu.Unlock()
	}

	var done, validCount, tcpValidCount, l2ValidCount atomic.Int32
	total := len(ips)

	if concurrency < 1 {
		concurrency = 1
	}
	sem := make(chan struct{}, concurrency)
	var wg sync.WaitGroup

	for _, ip := range ips {
		if ctx.Err() != nil {
			break
		}
		wg.Add(1)
		select {
		case sem <- struct{}{}:
		case <-ctx.Done():
			wg.Done()
			continue
		}

		go func(ip string) {
			defer wg.Done()
			defer func() { <-sem }()

			if ctx.Err() != nil {
				return
			}

			subKey := subnet24Key(ip)
			if isSubnet403Blocked(subKey) {
				d := done.Add(1)
				if progressCallback != nil && (d%10 == 0 || d == int32(total)) {
					progressCallback(int(d), total, int(validCount.Load()))
				}
				return
			}

			// Layer 1: TCP Ping (3 次采样 + 累计失败 2 次即刻 Fail-Fast 淘汰)
			avgLat, jitter, loss, tcpOK := measureTCPPingStats(ctx, ip, targetPort, 3, 2, 2, 1000*time.Millisecond)
			if ctx.Err() != nil {
				return
			}

			d := done.Add(1)
			if !tcpOK {
				if progressCallback != nil && (d%10 == 0 || d == int32(total)) {
					progressCallback(int(d), total, int(validCount.Load()))
				}
				return
			}

			tcpValidCount.Add(1)

			// Layer 2: Profile-driven check (excluding real HTTP 403s)
			// 保持 TCPLatency 为纯净的 TCP RTT，不混入应用层 TTFB/WSS 延迟，以保证 Bufferbloat 基准与延迟分准确
			var detectedColo string
			var wssRes WSSHandshakeResult
			switch profile.Type {
			case ProfileCFST:
				checkURL := profile.TestURL
				checkHost := profile.Host
				checkSNI := profile.SNI
				if checkSNI != "" && checkSNI != "speed.cloudflare.com" {
					checkHost = checkSNI
					checkURL = "https://" + checkSNI + "/"
				}
				ok, _, statusCode, colo, err := HTTPSConnectivityCheck(ctx, ip, targetPort, checkSNI, checkHost, checkURL, 2200*time.Millisecond)
				if statusCode == 403 {
					recordSubnet403(subKey)
				}
				if !ok || err != nil || statusCode == 403 {
					if progressCallback != nil && (d%10 == 0 || d == int32(total)) {
						progressCallback(int(d), total, int(validCount.Load()))
					}
					return
				}
				detectedColo = colo

			case ProfileGOWAYWSS:
				wssRes = WSSHandshakeCheckContext(ctx, ip, targetPort, profile.SNI, profile.Host, profile.Path, 2500*time.Millisecond)
				if wssRes.HTTPStatus == 403 {
					recordSubnet403(subKey)
				}
				if !wssRes.Success {
					if progressCallback != nil && (d%10 == 0 || d == int32(total)) {
						progressCallback(int(d), total, int(validCount.Load()))
					}
					return
				}
				detectedColo = wssRes.Colo

			case ProfileCustom:
				if profile.Protocol == "wss" {
					wssRes = WSSHandshakeCheckContext(ctx, ip, targetPort, profile.SNI, profile.Host, profile.Path, 2500*time.Millisecond)
					if wssRes.HTTPStatus == 403 {
						recordSubnet403(subKey)
					}
					if !wssRes.Success {
						if progressCallback != nil && (d%10 == 0 || d == int32(total)) {
							progressCallback(int(d), total, int(validCount.Load()))
						}
						return
					}
					detectedColo = wssRes.Colo
				} else {
					ok, _, statusCode, colo, err := HTTPSConnectivityCheck(ctx, ip, targetPort, profile.SNI, profile.Host, profile.TestURL, 2500*time.Millisecond)
					if statusCode == 403 {
						recordSubnet403(subKey)
					}
					if !ok || err != nil || statusCode == 403 {
						if progressCallback != nil && (d%10 == 0 || d == int32(total)) {
							progressCallback(int(d), total, int(validCount.Load()))
						}
						return
					}
					detectedColo = colo
				}
			}

			l2ValidCount.Add(1)

			node := NodeResult{
				IP:         ip,
				Port:       targetPort,
				TCPLatency: avgLat,
				Jitter:     jitter,
				PacketLoss: loss,
				Colo:       detectedColo,
			}
			if profile.Type == ProfileGOWAYWSS || (profile.Type == ProfileCustom && profile.Protocol == "wss") {
				node.GOWAYWSSCompatible = wssRes.Success
				node.GOWAYWSSLatency = wssRes.Latency
				node.GOWAYWSSErrorStage = wssRes.ErrorStage
				node.GOWAYWSSHTTPStatus = wssRes.HTTPStatus
				node.GOWAYWSSErrorMessage = wssRes.ErrorMessage
				node.GOWAYWSSSNISent = wssRes.SNISent
				node.GOWAYWSSHostSent = wssRes.HostSent
				node.GOWAYWSSPathSent = wssRes.PathSent
			}

			mu.Lock()
			validNodes = append(validNodes, node)
			mu.Unlock()
			validCount.Add(1)

			if progressCallback != nil && (d%10 == 0 || d == int32(total)) {
				progressCallback(int(d), total, int(validCount.Load()))
			}
		}(ip)
	}
	wg.Wait()
	return validNodes, int(tcpValidCount.Load()), int(l2ValidCount.Load())
}

// routePreRankKey 综合空载延迟、抖动与丢包率计算初筛代价（越低越优，确保 0 丢包、低抖动节点优先入围）
func routePreRankKey(n NodeResult) float64 {
	effectiveLat := n.TCPLatency
	if n.GOWAYWSSLatency > 0 {
		effectiveLat = n.TCPLatency*0.7 + (n.GOWAYWSSLatency/2.0)*0.3
	}
	return effectiveLat + n.Jitter*2.5 + n.PacketLoss*180.0
}

// avgLatency returns the average TCPLatency of a node slice.
func avgLatency(nodes []NodeResult) float64 {
	if len(nodes) == 0 {
		return math.MaxFloat64
	}
	var sum float64
	for _, n := range nodes {
		sum += n.TCPLatency
	}
	return sum / float64(len(nodes))
}

// selectBestColo picks the Colo with the LOWEST average TCP latency.
// This is the correct criterion — not node count.
func selectBestColo(coloGroups map[string][]NodeResult) string {
	const minNodes = 3
	best := ""
	bestLat := math.MaxFloat64

	// First pass: colos with enough nodes for statistical confidence
	for colo, nodes := range coloGroups {
		if len(nodes) < minNodes {
			continue
		}
		if avg := avgLatency(nodes); avg < bestLat {
			bestLat = avg
			best = colo
		}
	}
	// Fallback: any colo
	if best == "" {
		for colo, nodes := range coloGroups {
			if avg := avgLatency(nodes); avg < bestLat {
				bestLat = avg
				best = colo
			}
		}
	}
	return best
}

// detectColoBatch concurrently queries the Colo for each candidate.
// Returns the best Colo (by lowest avg latency) and the full coloGroups map.
func detectColoBatch(ctx context.Context, candidates []NodeResult, port int, concurrency int,
	progressCallback func(done, total int)) (bestColo string, coloGroups map[string][]NodeResult) {

	var wg sync.WaitGroup
	var done atomic.Int32
	total := len(candidates)
	sem := make(chan struct{}, concurrency)

	for i := range candidates {
		if ctx.Err() != nil {
			break
		}
		wg.Add(1)
		select {
		case sem <- struct{}{}:
		case <-ctx.Done():
			wg.Done()
			continue
		}
		go func(idx int) {
			defer wg.Done()
			defer func() { <-sem }()
			if ctx.Err() != nil {
				return
			}
			candidates[idx].Colo = GetColoWithContext(ctx, candidates[idx].IP, port)
			d := done.Add(1)
			if progressCallback != nil && (d%20 == 0 || d == int32(total)) {
				progressCallback(int(d), total)
			}
		}(i)
	}
	wg.Wait()

	coloGroups = make(map[string][]NodeResult)
	for _, c := range candidates {
		if c.Colo != "ERR" && c.Colo != "UNK" && c.Colo != "" {
			coloGroups[c.Colo] = append(coloGroups[c.Colo], c)
		}
	}

	bestColo = selectBestColo(coloGroups)
	return bestColo, coloGroups
}

// resolveSpeedTestTarget returns the target used for the HTTP download-speed phase.
func resolveSpeedTestTarget(cfg Config, ip string) ResolvedProbeTarget {
	profile := cfg.GetProbeProfile()
	isWSS := profile.Type == ProfileGOWAYWSS || (profile.Type == ProfileCustom && strings.EqualFold(profile.Protocol, "wss"))
	// 只要测速 URL 是官方 speed.cloudflare.com，测速阶段必须将 SNI 和 Host 切回 speed.cloudflare.com，防止因自定义 SNI 与 Host 不匹配触发 403
	if isWSS || !isCustomURL(cfg.URL) {
		profile = NewProfileCFST()
		if cfg.Port > 0 {
			profile.Port = cfg.Port
		}
	}
	return ResolveProbeTarget(
		ProbeConfig{Profile: profile},
		ip,
		profile.Port,
	)
}

// runQuickFilter runs short download tests against cfg.URL to rank candidates by speed.
// Used as a pre-filter in custom URL mode instead of Colo detection.
func runQuickFilter(ctx context.Context, candidates []NodeResult, cfg Config, topN int,
	progressCallback func(done, total int)) []NodeResult {

	numWorkers := cfg.DLConc
	if numWorkers < 1 {
		numWorkers = 1
	}

	type quickResult struct {
		idx         int
		speed       float64
		p10         float64
		minSpeed    float64
		stability   float64
		loadLatency float64
		stalls      int
		aborted403  bool
	}
	results := make([]quickResult, len(candidates))
	var doneCount atomic.Int32

	sem := make(chan struct{}, numWorkers)
	var wg sync.WaitGroup

	for i, cand := range candidates {
		if ctx.Err() != nil {
			break
		}
		wg.Add(1)
		select {
		case sem <- struct{}{}:
		case <-ctx.Done():
			wg.Done()
			continue
		}
		go func(idx int, c NodeResult) {
			defer wg.Done()
			defer func() { <-sem }()
			if ctx.Err() != nil {
				return
			}
			target := resolveSpeedTestTarget(cfg, c.IP)
			sm := SingleStreamTestDetailed(ctx, target, cfg.QuickDuration, nil, c.TCPLatency, c.Jitter, c.PacketLoss)
			results[idx] = quickResult{
				idx:         idx,
				speed:       sm.AverageSpeed,
				p10:         sm.P10Speed,
				minSpeed:    sm.MinSpeed,
				stability:   sm.Stability,
				loadLatency: sm.LoadLatency,
				stalls:      sm.StallCount,
				aborted403:  sm.Aborted403 || sm.HTTPStatus == 403,
			}
			d := doneCount.Add(1)
			if progressCallback != nil {
				progressCallback(int(d), len(candidates))
			}
		}(i, cand)
	}
	wg.Wait()

	// 综合预筛均速、P10 下限速度与稳定性排序，直接淘汰断流与 HTTP 403 节点（绝不回填死节点）
	sort.Slice(results, func(i, j int) bool {
		scoreI := results[i].speed*0.50 + results[i].p10*0.35 + (results[i].stability/10.0)*0.15 - float64(results[i].stalls)*5.0
		scoreJ := results[j].speed*0.50 + results[j].p10*0.35 + (results[j].stability/10.0)*0.15 - float64(results[j].stalls)*5.0
		return scoreI > scoreJ
	})

	var filtered []NodeResult
	for _, r := range results {
		if r.aborted403 || r.speed <= 0 {
			continue
		}
		c := candidates[r.idx]
		c.SingleSpeed = r.speed
		c.DownloadSpeed = r.speed
		if r.p10 > 0 {
			c.P10Speed = r.p10
		}
		if r.minSpeed > 0 {
			c.MinSpeed = r.minSpeed
		}
		if r.stability > 0 {
			c.Stability = r.stability
		}
		if r.loadLatency > 0 {
			c.LoadLatency = r.loadLatency
		}
		if c.Colo == "" {
			if v, ok := ipColoCache.Load(c.IP); ok && v.(string) != "" {
				c.Colo = v.(string)
			}
		}
		filtered = append(filtered, c)
		if len(filtered) >= topN {
			break
		}
	}
	return filtered
}

// runParallelDownloadTest runs the full download test on candidates.
func runParallelDownloadTest(ctx context.Context, candidates []NodeResult, cfg Config,
	progressRow func(res NodeResult),
	progressStatus func(msg string),
	progressLive func(LiveProgress),
	fastExitHost func()) []NodeResult {

	numWorkers := cfg.DLConc
	if numWorkers < 1 {
		numWorkers = 1
	}
	if numWorkers > len(candidates) {
		numWorkers = len(candidates)
	}

	// 可随时取消的子 Context：一旦测满 DownloadNum 或触发 Fast-Exit，立即中断其他正在下载的连接
	testCtx, testCancel := context.WithCancel(ctx)
	defer testCancel()

	origProfile := cfg.GetProbeProfile()
	isWSSProfile := origProfile.Type == ProfileGOWAYWSS || (origProfile.Type == ProfileCustom && strings.EqualFold(origProfile.Protocol, "wss"))

	var results []NodeResult
	var mu sync.Mutex
	var totalTested atomic.Int32
	var totalSkipped atomic.Int32
	var total403 atomic.Int32

	resultCh := make(chan NodeResult, numWorkers*2)
	doneCh := make(chan struct{})
	var doneOnce sync.Once
	closeDone := func() {
		doneOnce.Do(func() {
			close(doneCh)
			testCancel()
		})
	}

	go func() {
		for res := range resultCh {
			mu.Lock()
			results = append(results, res)
			n := len(results)
			mu.Unlock()
			if progressRow != nil {
				progressRow(res)
			}
			if cfg.StopThreshold > 0 && res.DownloadSpeed >= cfg.StopThreshold && res.StallCount == 0 && res.Stability >= 60 {
				if fastExitHost != nil {
					fastExitHost()
				}
				closeDone()
				return
			}
			if n >= cfg.DownloadNum {
				closeDone()
				return
			}
		}
		closeDone()
	}()

	var wg sync.WaitGroup
	var nextIdx atomic.Int32
	for w := 0; w < numWorkers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			workerCooldownMs := 50

			for {
				select {
				case <-doneCh:
					return
				case <-testCtx.Done():
					return
				default:
				}

				idx := int(nextIdx.Add(1) - 1)
				if idx >= len(candidates) {
					return
				}
				cand := candidates[idx]

				if workerCooldownMs > 0 && idx > 0 {
					select {
					case <-time.After(time.Duration(workerCooldownMs) * time.Millisecond):
					case <-testCtx.Done():
						return
					case <-doneCh:
						return
					}
				}

				t := totalTested.Add(1)
				if progressStatus != nil {
					progressStatus(fmt.Sprintf("Testing [%d/%d] %s (429:%d, 403:%d)",
						t, len(candidates), cand.IP, int(totalSkipped.Load()), int(total403.Load())))
				}

				candTarget := resolveSpeedTestTarget(cfg, cand.IP)
				sm := SingleStreamTestDetailed(testCtx, candTarget, cfg.Duration, progressLive, cand.TCPLatency, cand.Jitter, cand.PacketLoss)

				// 若因其他协程已完成任务或用户停止触发了 testCancel，直接丢弃被中途截断的半截采样并退出
				if testCtx.Err() != nil {
					return
				}

				if sm.Aborted403 || sm.HTTPStatus == 403 {
					// 真实 HTTP 403 Forbidden：不是 429 限流，不退避休眠，立即剔除并切换下一个节点
					total403.Add(1)
					workerCooldownMs = 0
					continue
				}

				if sm.AverageSpeed == 0 && sm.MinSpeed == 0 && sm.Stability == 0 {
					totalSkipped.Add(1)
					workerCooldownMs = min(workerCooldownMs*2+200, 3000)
					if cfg.Skip429 {
						continue
					}
					cand.DownloadSpeed = 0
					cand.Colo = "429"
					cand.Score = 0
					select {
					case resultCh <- cand:
					case <-doneCh:
						return
					}
				} else {
					workerCooldownMs = 50
					// 优先复用探活或测速响应头中已提取的 Colo，避免重复请求 /cdn-cgi/trace 和 ERR 覆盖 Bug
					if cand.Colo == "" || cand.Colo == "UNK" || cand.Colo == "ERR" {
						if v, ok := ipColoCache.Load(cand.IP); ok && v.(string) != "" {
							cand.Colo = v.(string)
						} else if rm, ok := GlobalRouteStore.GetMetrics(cand.IP); ok && rm.Colo != "" {
							cand.Colo = rm.Colo
						} else if candTarget.ProfileType == ProfileCFST && strings.Contains(candTarget.URL, "speed.cloudflare.com") {
							if c := GetColo(cand.IP, cfg.Port); c != "ERR" && c != "UNK" {
								cand.Colo = c
								ipColoCache.Store(cand.IP, c)
							}
						}
					}
					if sm.LoadLatency > 0 {
						cand.LoadLatency = sm.LoadLatency
					} else if cand.LoadLatency <= 0 {
						cand.LoadLatency = cand.TCPLatency
					}

					// GOWAY-WSS 零流量端到端二次复检（3轮 WSS 101 握手）测量回源真实延迟、抖动与成功率
					if isWSSProfile {
						avgWSS, jitWSS, rateWSS, wColo := MeasureWSSStability(testCtx, cand.IP, origProfile.Port, origProfile.SNI, origProfile.Host, origProfile.Path, 3, 2200*time.Millisecond)
						if testCtx.Err() != nil {
							return
						}
						if rateWSS <= 0 {
							total403.Add(1)
							workerCooldownMs = 0
							continue
						}
						cand.GOWAYWSSCompatible = true
						cand.WSSSuccessRate = rateWSS
						cand.WSSJitter = jitWSS
						if avgWSS > 0 {
							cand.GOWAYWSSLatency = avgWSS
						}
						if wColo != "" && (cand.Colo == "" || cand.Colo == "ERR" || cand.Colo == "UNK") {
							cand.Colo = wColo
						}
					}

					// 对最终入围下载的候选节点补跑 5 轮 TCP Ping 复核，消除 L1 3 次粗测的偶发超时导致的 33% 离散假丢包
					pingPort := cand.Port
					if pingPort <= 0 {
						pingPort = cfg.Port
					}
					if avgLat, jit, loss, ok := measureTCPPingStats(testCtx, cand.IP, pingPort, 5, 1, 0, 1000*time.Millisecond); ok {
						cand.TCPLatency = avgLat
						cand.Jitter = jit
						cand.PacketLoss = loss
						sm.Stability = CalcCompositeStability(&sm, cand.TCPLatency, cand.Jitter, cand.PacketLoss)
					}
					if testCtx.Err() != nil {
						return
					}

					cand.DownloadSpeed = sm.AverageSpeed
					cand.SingleSpeed = sm.AverageSpeed
					cand.P10Speed = sm.P10Speed
					cand.MedianSpeed = sm.MedianSpeed
					cand.MinSpeed = sm.MinSpeed
					cand.Stability = sm.Stability
					cand.StallCount = sm.StallCount
					cand.TotalStallDuration = sm.TotalStallDuration
					cand.ZeroSpeedIntervals = sm.ZeroSpeedIntervals
					cand.CalcScore()
					cand.Recommendation = string(FromNodeResult(cand, TierCandidate).Recommendation)

					select {
					case resultCh <- cand:
					case <-doneCh:
						return
					}

				}
			}
		}()
	}

	wg.Wait()
	close(resultCh)
	<-doneCh

	// 多级决胜排序：WSS握手健康优先 -> 总分接近时，WSS成功率 -> 0断流0丢包 -> P10下限速度 -> 稳定性 -> 均速 -> 满载/WSS延迟
	sort.Slice(results, func(i, j int) bool {
		wssHealthyI := results[i].WSSSuccessRate == 0 || results[i].WSSSuccessRate >= 0.67
		wssHealthyJ := results[j].WSSSuccessRate == 0 || results[j].WSSSuccessRate >= 0.67
		if wssHealthyI != wssHealthyJ {
			return wssHealthyI
		}
		diff := results[i].Score - results[j].Score
		if math.Abs(diff) > 1.5 {
			return results[i].Score > results[j].Score
		}
		if math.Abs(results[i].WSSSuccessRate-results[j].WSSSuccessRate) > 0.05 {
			return results[i].WSSSuccessRate > results[j].WSSSuccessRate
		}
		cleanI := results[i].StallCount == 0 && results[i].PacketLoss == 0
		cleanJ := results[j].StallCount == 0 && results[j].PacketLoss == 0
		if cleanI != cleanJ {
			return cleanI
		}
		if math.Abs(results[i].P10Speed-results[j].P10Speed) > 0.5 {
			return results[i].P10Speed > results[j].P10Speed
		}
		if math.Abs(results[i].Stability-results[j].Stability) > 2.0 {
			return results[i].Stability > results[j].Stability
		}
		if math.Abs(results[i].DownloadSpeed-results[j].DownloadSpeed) > 0.5 {
			return results[i].DownloadSpeed > results[j].DownloadSpeed
		}
		if results[i].GOWAYWSSLatency > 0 && results[j].GOWAYWSSLatency > 0 && math.Abs(results[i].GOWAYWSSLatency-results[j].GOWAYWSSLatency) > 10.0 {
			return results[i].GOWAYWSSLatency < results[j].GOWAYWSSLatency
		}
		return results[i].LoadLatency < results[j].LoadLatency
	})
	return results
}

func RunCLI(cfg Config) {
	resolveGowayFields(&cfg)
	profile := cfg.GetProbeProfile()
	fmt.Printf("Cloudflare SpeedTest v%s (Route Quality Probe - Go Edition)\n", AppVersion)
	if profile.Type == ProfileGOWAYWSS {
		fmt.Printf("🔗 Profile: GOWAY-WSS | Host: %s | SNI: %s | Path: %s | Port: %d\n", profile.Host, profile.SNI, profile.Path, profile.Port)
		fmt.Println("   Dual-Check: GOWAY WSS 101 zero-traffic handshake + speed.cloudflare.com throughput")
	} else {
		fmt.Printf("🌐 Profile: %s | SNI: %s | Port: %d\n", profile.Type, profile.SNI, profile.Port)
	}

	ips := GenerateIPs(cfg.MaxScan, cfg.Unique, cfg.IPFile)
	scopeLabel := fmt.Sprintf("%d IPs", len(ips))
	if cfg.MaxScan <= 0 && cfg.Unique && cfg.IPFile == "" {
		scopeLabel = fmt.Sprintf("%d IPs (100%% /24 subnets)", len(ips))
	}
	fmt.Printf("🔍 Scanning %s (concurrency: %d)...\n\n", scopeLabel, cfg.ScanConcurrent)

	ctx := context.Background()

	validNodes := ScanRoutesWithProfile(ctx, ips, cfg.Port, cfg.ScanConcurrent, profile, func(done, total, valid int) {
		fmt.Printf("\r  Process: %d/%d | Valid: %d", done, total, valid)
	})
	fmt.Println()

	if len(validNodes) == 0 {
		fmt.Println("[!] No valid IPs found (all failed connectivity/WSS 101 check or returned HTTP 403).")
		return
	}

	sort.Slice(validNodes, func(i, j int) bool {
		return routePreRankKey(validNodes[i]) < routePreRankKey(validNodes[j])
	})

	candidates := validNodes

	if isCustomURL(cfg.URL) {
		cfg.SkipLoadLatency = true
		cfg.StopThreshold = 0 // disable fast-exit
		if cfg.FilterMode == "multi-colo" {
			fmt.Println("[!] Multi-Colo filtering is not supported in custom URL mode. Falling back to speed pre-filter.")
			cfg.FilterMode = "speed"
		}
	}

	switch cfg.FilterMode {
	case "speed":
		// Stratified sampling across (Colo, /20) buckets so low-RTT throttled clusters
		// do not crowd out high-throughput clusters during quick pre-filtering.
		poolSize := presetQuickPoolSize(cfg)
		quickPool := selectDiverseCandidates(candidates, poolSize)
		quickCfg := cfg
		quickCfg.DLConc = 3 // 限制预筛并发为 3，防止多连接同时下载撑爆本地路由队列造成假丢包

		fmt.Printf("\n⚡ Speed Pre-filter mode (%ds quick test on %d stratified candidates from %d valid, %d workers)...\n",
			cfg.QuickDuration, len(quickPool), len(candidates), quickCfg.DLConc)

		candidates = runQuickFilter(ctx, quickPool, quickCfg, cfg.TopN, func(d, t int) {
			fmt.Printf("\r  Pre-filter: %d/%d", d, t)
		})
		fmt.Printf("\n  → %d candidates selected for full test\n", len(candidates))

	case "multi-colo":
		if len(candidates) > cfg.TopN {
			candidates = candidates[:cfg.TopN]
		}

		fmt.Printf("\n🔍 Detecting Colo for %d candidates...\n", len(candidates))
		_, coloGroups := detectColoBatch(ctx, candidates, cfg.Port, cfg.ScanConcurrent, func(done, total int) {
			fmt.Printf("\r  Colo detection: %d/%d", done, total)
		})
		fmt.Println()

		if len(coloGroups) > 0 {
			type coloStat struct {
				name  string
				count int
				avgMs float64
			}
			var stats []coloStat
			for colo, nodes := range coloGroups {
				stats = append(stats, coloStat{colo, len(nodes), avgLatency(nodes)})
			}
			sort.Slice(stats, func(i, j int) bool { return stats[i].avgMs < stats[j].avgMs })

			fmt.Println("  Colo average latencies (lowest to highest):")
			for idx, s := range stats {
				marker := "  "
				if idx < 3 {
					marker = "★ "
				}
				fmt.Printf("  %s%-6s  %4d nodes  avg %.1fms\n", marker, s.name, s.count, s.avgMs)
			}

			var multiColoCandidates []NodeResult
			numColos := 3
			if len(stats) < numColos {
				numColos = len(stats)
			}
			for i := 0; i < numColos; i++ {
				multiColoCandidates = append(multiColoCandidates, coloGroups[stats[i].name]...)
			}
			candidates = multiColoCandidates
			fmt.Printf("  → %d candidates selected from top %d Colos\n", len(candidates), numColos)
		} else {
			fmt.Println("  [!] No valid Colo detected, testing all candidates")
		}

	default: // "none" or fallback
		if len(candidates) > cfg.TopN {
			candidates = candidates[:cfg.TopN]
		}
		fmt.Printf("\n🚀 Skipping candidate filtering. Testing top %d candidates directly.\n", len(candidates))
	}

	if len(candidates) == 0 {
		fmt.Println("[!] No candidates selected for testing.")
		return
	}

	fmt.Printf("\n🚀 Download Test (%ds duration, %d parallel)\n", cfg.Duration, cfg.DLConc)
	if cfg.SkipLoadLatency {
		fmt.Printf("%-16s %-6s %-9s %-9s %-6s %-12s %-11s %-11s %-8s %-6s\n",
			"IP", "Colo", "Latency", "Jitter", "Loss", "Speed", "P10", "MinSpd", "Stable", "Score")
		fmt.Println("-------------------------------------------------------------------------------------------------------")
	} else {
		fmt.Printf("%-16s %-6s %-9s %-9s %-6s %-12s %-11s %-11s %-9s %-8s %-6s\n",
			"IP", "Colo", "Latency", "Jitter", "Loss", "Speed", "P10", "MinSpd", "LoadLat", "Stable", "Score")
		fmt.Println("--------------------------------------------------------------------------------------------------------------------")
	}

	results := runParallelDownloadTest(ctx, candidates, cfg, func(res NodeResult) {
		if res.Colo != "429" || !cfg.Skip429 {
			fmt.Printf("\r%-140s\r", "")
			if cfg.SkipLoadLatency {
				fmt.Printf("%-16s %-6s %6.1fms  %5.1fms  %4.0f%%  %5.2f MB/s  %5.2f MB/s  %5.2f MB/s  %4.0f%%   %5.1f\n",
					res.IP, res.Colo, res.TCPLatency, res.Jitter, res.PacketLoss*100,
					res.DownloadSpeed, res.P10Speed, res.MinSpeed, res.Stability, res.Score)
			} else {
				fmt.Printf("%-16s %-6s %6.1fms  %5.1fms  %4.0f%%  %5.2f MB/s  %5.2f MB/s  %5.2f MB/s  %6.1fms  %4.0f%%   %5.1f\n",
					res.IP, res.Colo, res.TCPLatency, res.Jitter, res.PacketLoss*100,
					res.DownloadSpeed, res.P10Speed, res.MinSpeed, res.LoadLatency, res.Stability, res.Score)
			}
		}
	}, nil, func(p LiveProgress) {
		fmt.Printf("\r  📥 %-16s %6.1f MB  %6.2f MB/s  %4.0f/%ds    ",
			p.IP, float64(p.Bytes)/1024/1024, p.Speed, p.Elapsed, int(p.Duration))
	}, func() {
		fmt.Println("\n⚡ Fast-exit triggered.")
	})

	if len(results) == 0 {
		fmt.Println("\n[!] All tested IPs failed or were rate-limited.")
		return
	}

	for i, res := range results {
		tier := TierCandidate
		switch routeRole(i) {
		case "ACTIVE":
			tier = TierActive
		case "STANDBY":
			tier = TierStandby
		}
		rm := FromNodeResult(res, tier)
		GlobalRouteStore.UpsertRoute(*rm)
	}

	printFinalRouteSelection(results, cfg)

	saveCSV(cfg.Output, results)
	fmt.Printf("\n💾 Saved to: %s\n", cfg.Output)
	if cfg.StateFile != "" {
		_ = GlobalRouteStore.SaveSnapshot(cfg.StateFile)
		fmt.Printf("💾 Saved route state to: %s\n", cfg.StateFile)
	}

}

func routeRole(index int) string {
	switch {
	case index == 0:
		return "ACTIVE"
	case index <= 2:
		return "STANDBY"
	default:
		return "CANDIDATE"
	}
}

func printFinalRouteSelection(results []NodeResult, cfg Config) {
	if len(results) == 0 {
		return
	}
	best := results[0]
	profile := cfg.GetProbeProfile()
	fmt.Println()
	fmt.Println("════════════════════════════════════════════════════════════")
	fmt.Printf("✅ %s Best Route\n", profile.Type)
	fmt.Println("════════════════════════════════════════════════════════════")
	fmt.Printf("IP: %s\n", best.IP)
	fmt.Printf("Colo: %s\n", best.Colo)
	fmt.Printf("Latency: %.1f ms\n", best.TCPLatency)
	fmt.Printf("Jitter: %.1f ms\n", best.Jitter)
	fmt.Printf("Loss: %.0f%%\n", best.PacketLoss*100)
	fmt.Printf("Speed: %.2f MB/s\n", best.DownloadSpeed)
	fmt.Printf("P10: %.2f MB/s\n", best.P10Speed)
	fmt.Printf("MinSpd: %.2f MB/s\n", best.MinSpeed)
	fmt.Printf("Stable: %.0f%%\n", best.Stability)
	fmt.Printf("Score: %.1f\n", best.Score)

	isGOWAYWSS := profile.Type == ProfileGOWAYWSS
	if isGOWAYWSS {
		fmt.Println("WSS: PASS (HTTP 101)")
		if best.GOWAYWSSLatency > 0 {
			fmt.Printf("WSS RTT: %.1f ms | WSS Jitter: %.1f ms | WSS Rate: %.0f%%\n",
				best.GOWAYWSSLatency, best.WSSJitter, best.WSSSuccessRate*100)
		}
		fmt.Printf("SNI: %s\n", profile.SNI)
		fmt.Printf("Host: %s\n", profile.Host)
		fmt.Printf("Path: %s\n", profile.Path)
		fmt.Printf("Port: %d\n", profile.Port)
	}
	fmt.Println("Role: ACTIVE")
	fmt.Println("════════════════════════════════════════════════════════════")

	if len(results) > 1 {
		fmt.Println()
		fmt.Println("Standby Routes:")
		limit := 2
		if len(results)-1 < limit {
			limit = len(results) - 1
		}
		for i := 1; i <= limit; i++ {
			r := results[i]
			if isGOWAYWSS && r.GOWAYWSSLatency > 0 {
				fmt.Printf(
					"  #%d %-15s %-6s Speed %.2f MB/s (P10 %.2f)  WSS %.1fms (±%.1f)  Score %.1f\n",
					i, r.IP, r.Colo, r.DownloadSpeed, r.P10Speed, r.GOWAYWSSLatency, r.WSSJitter, r.Score,
				)
			} else {
				fmt.Printf(
					"  #%d %-15s %-6s Speed %.2f MB/s  Score %.1f\n",
					i, r.IP, r.Colo, r.DownloadSpeed, r.Score,
				)
			}
		}
	}

	if isGOWAYWSS {
		fmt.Println("\n🚀 GOWAY Ready Top IPs (copy to your client):")
		topK := 3
		if len(results) < topK {
			topK = len(results)
		}
		for i := 0; i < topK; i++ {
			r := results[i]
			fmt.Printf("  [%d] %s:%d  (Colo:%s Speed:%.2f MB/s WSS:%.1fms SNI:%s Host:%s Path:%s)\n",
				i+1, r.IP, profile.Port, r.Colo, r.DownloadSpeed, r.GOWAYWSSLatency, profile.SNI, profile.Host, profile.Path)
		}
	}
	fmt.Println()
}

func saveCSV(path string, results []NodeResult) {
	f, err := os.Create(path)
	if err != nil {
		fmt.Println("Error saving CSV:", err)
		return
	}
	defer f.Close()

	f.Write([]byte{0xEF, 0xBB, 0xBF}) // UTF-8 BOM
	w := csv.NewWriter(f)
	defer w.Flush()

	w.Write([]string{"Role", "IP", "Colo", "Latency", "Jitter", "Loss", "SgSpeed_MB", "Speed_MB", "P10Speed_MB", "MinSpeed_MB", "LoadLatency", "Stability", "Stalls", "WSSLatency", "WSSJitter", "WSSSuccessRate", "Score"})
	for i, r := range results {
		w.Write([]string{
			routeRole(i),
			r.IP, r.Colo,
			fmt.Sprintf("%.1f", r.TCPLatency),
			fmt.Sprintf("%.1f", r.Jitter),
			fmt.Sprintf("%.0f%%", r.PacketLoss*100),
			fmt.Sprintf("%.2f", r.SingleSpeed),
			fmt.Sprintf("%.2f", r.DownloadSpeed),
			fmt.Sprintf("%.2f", r.P10Speed),
			fmt.Sprintf("%.2f", r.MinSpeed),
			fmt.Sprintf("%.1f", r.LoadLatency),
			fmt.Sprintf("%.0f", r.Stability),
			fmt.Sprintf("%d", r.StallCount),
			fmt.Sprintf("%.1f", r.GOWAYWSSLatency),
			fmt.Sprintf("%.1f", r.WSSJitter),
			fmt.Sprintf("%.0f%%", r.WSSSuccessRate*100),
			fmt.Sprintf("%.1f", r.Score),
		})
	}
}

// ============================================================================
// SECTION: REST API HANDLERS (from api.go)
// ============================================================================
var appStartTime = time.Now()

// RegisterAPIRoutes mounts GoPass-facing REST API endpoints onto the HTTP mux.
func RegisterAPIRoutes(mux *http.ServeMux) {
	mux.HandleFunc("/api/health", handleAPIHealth)
	mux.HandleFunc("/api/routes", handleAPIRoutes)
	mux.HandleFunc("/api/routes/best", handleAPIBestRoutes)
	mux.HandleFunc("/api/routes/metrics", handleAPIMetricsSummary)
	mux.HandleFunc("/api/routes/tier", handleAPIRouteTier)
	mux.HandleFunc("/api/discovery/status", handleAPIDiscoveryStatus)
	mux.HandleFunc("/api/probe", handleAPIProbe)
	mux.HandleFunc("/api/config", handleAPIConfig)
}

func init() {
	RegisterAPIRoutes(http.DefaultServeMux)
}

func writeJSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(data)
}

func handleAPIHealth(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	all := GlobalRouteStore.GetAll()
	var healthyCount, activeCount, standbyCount int
	for _, m := range all {
		if m.Health == HealthHealthy {
			healthyCount++
		}
		if m.Tier == TierActive {
			activeCount++
		} else if m.Tier == TierStandby {
			standbyCount++
		}
	}

	cfg := GlobalProbeScheduler.GetConfig()
	writeJSON(w, http.StatusOK, map[string]interface{}{
		"status":         "ok",
		"service":        "CFST Route Quality Probe",
		"version":        "v" + AppVersion,
		"uptime_seconds": int64(time.Since(appStartTime).Seconds()),
		"score_mode":     GlobalScoreEngine.GetMode(),
		"profile":        cfg.Profile.Type,
		"profile_type":   cfg.Profile.Type,
		"test_url":       cfg.Profile.TestURL,
		"sni":            cfg.Profile.SNI,
		"host":           cfg.Profile.Host,
		"path":           cfg.Profile.Path,
		"protocol":       cfg.Profile.Protocol,
		"total_routes":   len(all),
		"healthy_routes": healthyCount,
		"active_routes":  activeCount,
		"standby_routes": standbyCount,
		"timestamp":      time.Now().Format(time.RFC3339),
	})
}

func handleAPIRoutes(w http.ResponseWriter, r *http.Request) {
	path := strings.TrimPrefix(r.URL.Path, "/api/routes")
	path = strings.TrimPrefix(path, "/")

	// Sub-route handling: /api/routes/{ip}/[history|peak|samples]
	if path != "" && path != "best" && path != "metrics" && path != "tier" {
		parts := strings.Split(path, "/")
		ip := parts[0]
		sub := ""
		if len(parts) > 1 {
			sub = parts[1]
		}

		if _, exists := GlobalRouteStore.Get(ip); !exists {
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "Route not found"})
			return
		}

		switch sub {
		case "history":
			windows := GlobalRouteStore.GetHistoryWindows(ip)
			writeJSON(w, http.StatusOK, windows)
			return
		case "peak":
			peakHours := GlobalRouteStore.GetPeakHours(ip)
			writeJSON(w, http.StatusOK, peakHours)
			return
		case "samples":
			samples := GlobalRouteStore.GetSamples(ip)
			writeJSON(w, http.StatusOK, samples)
			return
		default:
			handleAPIRouteDetail(w, r, ip)
			return
		}
	}

	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	q := r.URL.Query()
	colo := strings.ToUpper(q.Get("colo"))
	tier := RouteTier(strings.ToUpper(q.Get("tier")))
	health := RouteHealth(strings.ToUpper(q.Get("health")))
	limitStr := q.Get("limit")

	all := GlobalRouteStore.GetAll()
	var filtered []RouteMetrics
	for _, m := range all {
		if colo != "" && m.Colo != colo {
			continue
		}
		if tier != "" && m.Tier != tier {
			continue
		}
		if health != "" && m.Health != health {
			continue
		}
		filtered = append(filtered, m)
	}

	if limitStr != "" {
		if limit, err := strconv.Atoi(limitStr); err == nil && limit > 0 && len(filtered) > limit {
			filtered = filtered[:limit]
		}
	}

	if filtered == nil {
		filtered = []RouteMetrics{}
	}
	writeJSON(w, http.StatusOK, filtered)
}

func handleAPIBestRoutes(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	q := r.URL.Query()
	limit := 5
	if l := q.Get("limit"); l != "" {
		if parsed, err := strconv.Atoi(l); err == nil && parsed > 0 {
			limit = parsed
		}
	}
	colo := strings.ToUpper(q.Get("colo"))

	best := GlobalRouteStore.GetBest(limit, colo)
	if best == nil {
		best = []RouteMetrics{}
	}
	writeJSON(w, http.StatusOK, best)
}

type SpeedSummary struct {
	Avg    float64 `json:"avg"`
	Median float64 `json:"median"`
	P10    float64 `json:"p10"`
	Min    float64 `json:"min"`
}

type StallSummary struct {
	Count         int     `json:"count"`
	Rate          float64 `json:"rate"`
	TotalDuration float64 `json:"total_duration"`
}

// Lightweight metrics summary for fast GoPass controller polling
type RouteMetricSummary struct {
	ID             string              `json:"id"`
	IP             string              `json:"ip"`
	Port           int                 `json:"port"`
	Colo           string              `json:"colo"`
	Tier           RouteTier           `json:"tier"`
	Health         RouteHealth         `json:"health"`
	StabilityGrade StabilityGrade      `json:"stability_grade"`
	Recommendation RouteRecommendation `json:"recommendation"`
	Reasons        []string            `json:"reasons,omitempty"`
	RTT            float64             `json:"rtt"`
	PacketLoss     float64             `json:"packet_loss"`
	Jitter         float64             `json:"jitter"`
	SingleSpeed    float64             `json:"single_speed"`
	MinSpeed       float64             `json:"min_speed"`
	P10Speed       float64             `json:"p10_speed"`
	Confidence     float64             `json:"confidence"`
	PeakHourScore  float64             `json:"peak_hour_score"`
	FinalScore     float64             `json:"final_score"`
	Speed          SpeedSummary        `json:"speed"`
	Stalls         StallSummary        `json:"stalls"`
	Timestamp      time.Time           `json:"timestamp"`
}

func handleAPIMetricsSummary(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	all := GlobalRouteStore.GetAll()
	summaries := make([]RouteMetricSummary, len(all))
	for i, m := range all {
		effectiveSpeed := m.SingleSpeed
		if effectiveSpeed <= 0 {
			effectiveSpeed = m.DownloadSpeed
		}
		median := m.MedianSpeed
		if median <= 0 {
			median = effectiveSpeed
		}
		p10 := m.P10Speed
		if p10 <= 0 {
			p10 = m.MinSpeed
		}

		summaries[i] = RouteMetricSummary{
			ID:             m.ID,
			IP:             m.IP,
			Port:           m.Port,
			Colo:           m.Colo,
			Tier:           m.Tier,
			Health:         m.Health,
			StabilityGrade: m.StabilityGrade,
			Recommendation: m.Recommendation,
			Reasons:        m.RecommendationReasons,
			RTT:            m.RTT,
			PacketLoss:     m.PacketLoss,
			Jitter:         m.Jitter,
			SingleSpeed:    m.SingleSpeed,
			MinSpeed:       m.MinSpeed,
			P10Speed:       p10,
			Confidence:     m.Confidence,
			PeakHourScore:  m.PeakHourScore,
			FinalScore:     m.FinalScore,
			Speed: SpeedSummary{
				Avg:    math.Round(effectiveSpeed*10) / 10,
				Median: math.Round(median*10) / 10,
				P10:    math.Round(p10*10) / 10,
				Min:    math.Round(m.MinSpeed*10) / 10,
			},
			Stalls: StallSummary{
				Count:         m.StallCount,
				Rate:          math.Round(m.StallRate*1000) / 1000,
				TotalDuration: math.Round(m.TotalStallDuration*10) / 10,
			},
			Timestamp: m.Timestamp,
		}
	}
	writeJSON(w, http.StatusOK, summaries)
}

func handleAPIRouteDetail(w http.ResponseWriter, r *http.Request, idOrIP string) {
	metrics, exists := GlobalRouteStore.GetMetrics(idOrIP)
	if !exists {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "Route not found"})
		return
	}

	shortEWMA, longEWMA, _ := GlobalRouteStore.GetEWMASnapshots(idOrIP)
	windows := GlobalRouteStore.GetHistoryWindows(idOrIP)
	peakHours := GlobalRouteStore.GetPeakHours(idOrIP)

	effectiveSpeed := metrics.SingleSpeed
	if effectiveSpeed <= 0 {
		effectiveSpeed = metrics.DownloadSpeed
	}
	median := metrics.MedianSpeed
	if median <= 0 {
		median = effectiveSpeed
	}
	p10 := metrics.P10Speed
	if p10 <= 0 {
		p10 = metrics.MinSpeed
	}

	writeJSON(w, http.StatusOK, map[string]interface{}{
		"metrics":         metrics,
		"recommendation":  metrics.Recommendation,
		"stability_grade": metrics.StabilityGrade,
		"confidence":      metrics.Confidence,
		"final_score":     metrics.FinalScore,
		"speed": SpeedSummary{
			Avg:    math.Round(effectiveSpeed*10) / 10,
			Median: math.Round(median*10) / 10,
			P10:    math.Round(p10*10) / 10,
			Min:    math.Round(metrics.MinSpeed*10) / 10,
		},
		"stalls": StallSummary{
			Count:         metrics.StallCount,
			Rate:          math.Round(metrics.StallRate*1000) / 1000,
			TotalDuration: math.Round(metrics.TotalStallDuration*10) / 10,
		},
		"ewma_short": shortEWMA,
		"ewma_long":  longEWMA,
		"history":    windows,
		"peak_hours": peakHours,
	})
}

type SetTierRequest struct {
	IP   string    `json:"ip"`
	Tier RouteTier `json:"tier"`
}

func handleAPIRouteTier(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req SetTierRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "Invalid request body"})
		return
	}

	req.Tier = RouteTier(strings.ToUpper(string(req.Tier)))
	switch req.Tier {
	case TierActive, TierStandby, TierCandidate, TierFailed:
	default:
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "Invalid tier; must be ACTIVE, STANDBY, CANDIDATE, or FAILED"})
		return
	}

	if !GlobalRouteStore.SetTier(req.IP, req.Tier) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "Route IP not found in managed pool"})
		return
	}

	writeJSON(w, http.StatusOK, map[string]interface{}{
		"status": "updated",
		"ip":     req.IP,
		"tier":   req.Tier,
	})
}

type ProbeRequest struct {
	IP        string `json:"ip"`
	Port      int    `json:"port"`
	SpeedTest bool   `json:"speed_test"`
}

func handleAPIProbe(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req ProbeRequest
	if r.Header.Get("Content-Type") == "application/json" {
		_ = json.NewDecoder(r.Body).Decode(&req)
	} else {
		req.IP = r.URL.Query().Get("ip")
		req.SpeedTest = r.URL.Query().Get("speed_test") == "true"
	}

	if req.IP == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "IP is required"})
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), 30*time.Second)
	defer cancel()

	metrics, err := GlobalProbeScheduler.ProbeOnce(ctx, req.IP, req.SpeedTest)
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}

	writeJSON(w, http.StatusOK, metrics)
}

