// SECTION: INTERACTIVE WIZARD & CONFIG MEMORY
// ============================================================================
type lastWizardConfig struct {
	Mode        string `json:"mode"` // "goway", "cfst", "custom", "web"
	GowayTarget string `json:"goway_target,omitempty"`
	WSSHost     string `json:"wss_host,omitempty"`
	WSSPath     string `json:"wss_path,omitempty"`
	SNI         string `json:"sni,omitempty"`
	Port        int    `json:"port,omitempty"`
	CustomURL   string `json:"custom_url,omitempty"`
	Preset      string `json:"preset,omitempty"`
	AllSubnets  bool   `json:"all_subnets"`
}

func loadLastWizardConfig(path string) (lastWizardConfig, bool) {
	var lc lastWizardConfig
	data, err := os.ReadFile(path)
	if err != nil {
		return lc, false
	}
	if err := json.Unmarshal(data, &lc); err != nil {
		return lc, false
	}
	return lc, true
}

func saveLastWizardConfig(path string, lc lastWizardConfig) error {
	data, err := json.MarshalIndent(lc, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

func isInteractiveTTY() bool {
	inInfo, err := os.Stdin.Stat()
	if err != nil || (inInfo.Mode()&os.ModeCharDevice) == 0 {
		return false
	}
	outInfo, err := os.Stdout.Stat()
	if err != nil || (outInfo.Mode()&os.ModeCharDevice) == 0 {
		return false
	}
	return true
}

func applyWizardChoice(cfg *Config, lc lastWizardConfig) {
	if cfg == nil {
		return
	}
	if lc.Preset != "" {
		cfg.Preset = lc.Preset
		applyPreset(cfg)
	}
	cfg.AllSubnets = lc.AllSubnets
	if lc.Port > 0 {
		cfg.Port = lc.Port
	}
	switch lc.Mode {
	case "goway":
		cfg.Profile = "GOWAY-WSS"
		cfg.GowayTarget = lc.GowayTarget
		cfg.WSSHost = lc.WSSHost
		cfg.WSSPath = lc.WSSPath
		cfg.SNI = lc.SNI
	case "custom":
		cfg.Profile = "CUSTOM"
		if lc.CustomURL != "" {
			cfg.URL = lc.CustomURL
		}
		if lc.SNI != "" {
			cfg.SNI = lc.SNI
		}
	default:
		cfg.Profile = "CFST"
		cfg.WSSHost = ""
	}
	resolveGowayFields(cfg)
}

func runInteractiveWizardWithIO(cfg *Config, r io.Reader, w io.Writer, lastCfgPath string) bool {
	sc := bufio.NewScanner(r)
	readLine := func(prompt string) string {
		fmt.Fprint(w, prompt)
		if sc.Scan() {
			return strings.TrimSpace(sc.Text())
		}
		return ""
	}

	fmt.Fprintln(w, "============================================================")
	fmt.Fprintf(w, "   CFST v%s - GOWAY 边缘节点优选向导 (直接回车使用默认值)\n", AppVersion)
	fmt.Fprintln(w, "============================================================")

	last, hasLast := loadLastWizardConfig(lastCfgPath)
	defaultChoice := "1"
	if hasLast {
		defaultChoice = "0"
		summary := last.Mode
		if last.WSSHost != "" {
			summary = fmt.Sprintf("GOWAY %s%s", last.WSSHost, last.WSSPath)
		} else if last.CustomURL != "" {
			summary = fmt.Sprintf("Custom %s", last.CustomURL)
		}
		if last.Preset != "" {
			summary += " [" + last.Preset + "]"
		}
		fmt.Fprintf(w, "  [0] 复用上次配置: %s  (默认)\n", summary)
	}
	if hasLast {
		fmt.Fprintln(w, "  [1] GOWAY 访问 VPS 优选 (只需 VPS 域名，无需测试文件)")
	} else {
		fmt.Fprintln(w, "  [1] GOWAY 访问 VPS 优选 (只需 VPS 域名，无需测试文件)  (默认)")
	}
	fmt.Fprintln(w, "  [2] 标准 Cloudflare 边缘节点优选 (全网段)")
	fmt.Fprintln(w, "  [3] 自定义下载 URL 测速优选")
	fmt.Fprintln(w, "  [4] 启动 Web 可视化控制台")

	choice := readLine(fmt.Sprintf("请选择模式 [%s]: ", defaultChoice))
	if choice == "" {
		choice = defaultChoice
	}

	if choice == "0" && hasLast {
		applyWizardChoice(cfg, last)
		return last.Mode == "web"
	}
	if choice == "4" {
		return true
	}

	var lc lastWizardConfig
	lc.AllSubnets = true
	switch choice {
	case "2":
		lc.Mode = "cfst"
	case "3":
		lc.Mode = "custom"
		lc.CustomURL = readLine("请输入自定义测速文件 URL (https://...): ")
		if lc.CustomURL == "" {
			fmt.Fprintln(w, "  未输入自定义 URL，已切换为标准 Cloudflare 优选。")
			lc.Mode = "cfst"
		}
	default:
		lc.Mode = "goway"
		domainInput := readLine("请输入你的 VPS 域名 (支持 domain.com 或 domain.com:443/pyway，留空则走标准优选): ")
		if domainInput == "" {
			lc.Mode = "cfst"
		} else {
			host, port, path := parseGowayTarget(domainInput)
			lc.GowayTarget = domainInput
			lc.WSSHost = host
			lc.SNI = host
			if port > 0 {
				lc.Port = port
			}
			if path != "" {
				lc.WSSPath = path
			} else {
				p := readLine("请输入 GOWAY WSS 路径 [默认 /pyway]: ")
				if p == "" {
					p = "/pyway"
				}
				if !strings.HasPrefix(p, "/") {
					p = "/" + p
				}
				lc.WSSPath = p
			}
		}
	}

	fmt.Fprintln(w, "\n扫描档位:")
	fmt.Fprintln(w, "  [1] Fast     - 抽样 ~800 个 /24 网段 (~40秒)")
	fmt.Fprintln(w, "  [2] Standard - 100% 全网段扫描 (~5,900+ /24, 最稳最快)  (默认)")
	fmt.Fprintln(w, "  [3] Deep     - 100% 全网段 + 长稳态验证 (Top 50 / 12秒)")
	pChoice := readLine("选择档位 [2]: ")
	switch pChoice {
	case "1":
		lc.Preset = "fast"
		lc.AllSubnets = false
	case "3":
		lc.Preset = "deep"
		lc.AllSubnets = true
	default:
		lc.Preset = "standard"
		lc.AllSubnets = true
	}

	applyWizardChoice(cfg, lc)
	if lastCfgPath != "" {
		_ = saveLastWizardConfig(lastCfgPath, lc)
	}
	return false
}

// ============================================================================
// SECTION: MAIN ENTRYPOINT & CLI PARSING (from main.go)
// ============================================================================
func main() {
	cfg := DefaultConfig()

	flag.IntVar(&cfg.Port, "p", cfg.Port, "Target port")
	flag.IntVar(&cfg.MaxScan, "max", cfg.MaxScan, "Max IPs to scan (0 = 100% of /24 subnets)")
	flag.IntVar(&cfg.TopN, "topn", cfg.TopN, "Top N candidates by latency for speed test")
	flag.IntVar(&cfg.DLConc, "dlc", cfg.DLConc, "Parallel download test concurrency")
	flag.IntVar(&cfg.DownloadNum, "dn", cfg.DownloadNum, "Download test count")
	flag.IntVar(&cfg.Duration, "dt", cfg.Duration, "Download duration (seconds)")
	flag.Float64Var(&cfg.StopThreshold, "st", cfg.StopThreshold, "Stop threshold MB/s (0 = disabled)")
	flag.BoolVar(&cfg.Unique, "u", cfg.Unique, "Unique C-subnet")
	flag.StringVar(&cfg.IPFile, "f", cfg.IPFile, "Custom IP file")
	flag.StringVar(&cfg.Output, "o", cfg.Output, "Output file")
	flag.IntVar(&cfg.ScanConcurrent, "sc", cfg.ScanConcurrent, "Scan concurrency")
	flag.BoolVar(&cfg.Skip429, "skip429", cfg.Skip429, "Discard 429 rate-limited IPs silently")
	flag.StringVar(&cfg.URL, "url", cfg.URL, "Custom download test URL")
	flag.IntVar(&cfg.QuickDuration, "qd", cfg.QuickDuration, "Quick pre-filter duration in seconds")
	flag.StringVar(&cfg.FilterMode, "filter", cfg.FilterMode, "Candidate filter mode (speed, multi-colo, none)")
	flag.StringVar(&cfg.SNI, "sni", cfg.SNI, "Custom TLS SNI (supports domain/path for GOWAY-WSS)")
	flag.StringVar(&cfg.WSSHost, "wsshost", cfg.WSSHost, "WebSocket Host for GOWAY handshake check")
	flag.StringVar(&cfg.WSSPath, "wsspath", cfg.WSSPath, "WebSocket Path for GOWAY handshake check (default /pyway)")
	flag.StringVar(&cfg.Profile, "profile", cfg.Profile, "Probe profile: CFST (default), GOWAY-WSS, CUSTOM")
	flag.StringVar(&cfg.GowayTarget, "goway", cfg.GowayTarget, "GOWAY VPS target shorthand (domain[:port][/path], e.g. vps.example.com/pyway)")
	flag.StringVar(&cfg.Preset, "preset", cfg.Preset, "Scan preset: fast, standard (default), deep")
	flag.BoolVar(&cfg.AllSubnets, "all", cfg.AllSubnets, "Scan 100% of Cloudflare /24 subnets (sets -max 0 -u true)")
	flag.BoolVar(&cfg.Yes, "y", cfg.Yes, "Skip interactive wizard and start immediately with defaults/flags")
	flag.BoolVar(&cfg.DaemonMode, "daemon", cfg.DaemonMode, "Run as continuous Route Quality Probe daemon")
	flag.StringVar(&cfg.APIAddr, "api-addr", cfg.APIAddr, "Local API listen address (default 127.0.0.1:9876)")
	flag.IntVar(&cfg.ActiveInterval, "active-interval", cfg.ActiveInterval, "Active route probe interval in seconds")
	flag.IntVar(&cfg.StandbyInterval, "standby-interval", cfg.StandbyInterval, "Standby route probe interval in seconds")
	flag.IntVar(&cfg.CandidateInterval, "candidate-interval", cfg.CandidateInterval, "Candidate route probe interval in seconds")
	flag.IntVar(&cfg.FailedInterval, "failed-interval", cfg.FailedInterval, "Failed route recovery probe interval in seconds")
	flag.StringVar(&cfg.ScoreMode, "mode", cfg.ScoreMode, "Scoring mode: normal or peak")
	flag.StringVar(&cfg.StateFile, "state", cfg.StateFile, "State persistence JSON file path")
	flag.BoolVar(&cfg.DiscoveryEnabled, "discovery", cfg.DiscoveryEnabled, "Enable continuous Cloudflare IP discovery in daemon mode")
	flag.IntVar(&cfg.DiscoveryInterval, "discovery-interval", cfg.DiscoveryInterval, "Discovery scan interval in seconds (default 3600)")
	flag.IntVar(&cfg.DiscoveryScanCount, "discovery-count", cfg.DiscoveryScanCount, "Discovery IPs to scan per pass (default 200)")
	versionFlag := flag.Bool("v", false, "Show version and exit")
	flag.BoolVar(versionFlag, "version", false, "Show version and exit")

	webMode := false
	webPort := "9876"
	if len(os.Args) > 0 {
		var newArgs []string
		newArgs = append(newArgs, os.Args[0])
		for i := 1; i < len(os.Args); i++ {
			if os.Args[i] == "-web" {
				webMode = true
				if i+1 < len(os.Args) && !strings.HasPrefix(os.Args[i+1], "-") {
					webPort = os.Args[i+1]
					i++
				}
			} else {
				newArgs = append(newArgs, os.Args[i])
			}
		}
		os.Args = newArgs
	}

	flag.Bool("web", false, "Start Web UI server (-web <port>)")
	flag.Parse()

	if *versionFlag {
		println("CFST v" + AppVersion + " (GOWAY Route Quality Probe & Long-Term Stability Analyzer)")
		return
	}

	setFlags := make(map[string]bool)
	flag.Visit(func(f *flag.Flag) {
		setFlags[f.Name] = true
	})

	if setFlags["preset"] {
		explicitCfg := cfg
		applyPreset(&cfg)
		if setFlags["max"] {
			cfg.MaxScan = explicitCfg.MaxScan
		}
		if setFlags["topn"] {
			cfg.TopN = explicitCfg.TopN
		}
		if setFlags["dn"] {
			cfg.DownloadNum = explicitCfg.DownloadNum
		}
		if setFlags["dt"] {
			cfg.Duration = explicitCfg.Duration
		}
		if setFlags["qd"] {
			cfg.QuickDuration = explicitCfg.QuickDuration
		}
		if setFlags["sc"] {
			cfg.ScanConcurrent = explicitCfg.ScanConcurrent
		}
		if setFlags["u"] {
			cfg.Unique = explicitCfg.Unique
		}
	}

	if !cfg.Yes && !cfg.DaemonMode && !webMode && len(setFlags) == 0 && isInteractiveTTY() {
		if runInteractiveWizardWithIO(&cfg, os.Stdin, os.Stdout, ".cfst_last.json") {
			webMode = true
		}
	}

	resolveGowayFields(&cfg)

	if cfg.DaemonMode {
		RunDaemon(cfg)
	} else if webMode {
		cfg.WebMode = true
		cfg.WebPort = webPort
		if !strings.Contains(cfg.WebPort, ":") {
			cfg.WebPort = ":" + cfg.WebPort
		}
		RunWeb(cfg)
	} else {
		RunCLI(cfg)
	}
}
